// বাংলা MCQ ডেটা - 199টি প্রশ্ন
var data_bangla = [{"id":"bangla-1","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"ভাষার অর্থযুক্ত ক্ষুদ্রতম একক কোনটি?","options":["অক্ষর","রূপমূল","শব্দ","বর্গ"],"correctIndex":1,"subject":"বাংলা","explanation":"ভাষার মূল উপাদান/ক্ষুদ্রতম একক হলো ধ্বনি, যার নিজস্ব কোনো অর্থ নেই (যেমন: অ, আ, ই, উ)। কিন্তু ভাষা/শব্দের অর্থযুক্ত ক্ষুদ্রতম একক হলো রূপ বা রূপমূল (Morpheme), যার নিজস্ব অর্থ থাকে। যেমন 'পড়ি' শব্দের রূপমূল 'পড়'। রূপমূল থেকে শব্দ গঠিত হয় বলে শব্দতত্ত্বকে রূপতত্ত্ব (Morphology)ও বলা হয়। রূপমূল দুই প্রকার: মুক্ত রূপমূল (নিজে স্বাধীনভাবে অর্থ প্রকাশ করে, যেমন: কাজ, ঘর, চল) ও বদ্ধ রূপমূল (একা অর্থ প্রকাশ করে না, অন্য রূপমূলের সাথে যুক্ত হয়ে অর্থ তৈরি করে, যেমন: টি, গুলো, রা)। অপশন বিশ্লেষণ: অক্ষর (দল) হলো নিঃশ্বাসের স্বল্পতম প্রয়াসে উচ্চারিত ধ্বনি/ধ্বনিগুচ্ছ, উচ্চারণের একক; শব্দ হলো বাক্যের মৌলিক উপাদান, যার গঠনগত উপাদান বর্ণ; বর্গ হলো একাধিক শব্দে গঠিত বাক্যাংশ, বাক্যের একক।"},{"id":"bangla-2","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"ধ্বনি ও বর্ণের পার্থক্য কোথায়?","options":["লেখার ধরনে","উচ্চারণের বিশিষ্টতায়","সংখ্যাগত পরিমাণে","ইন্দ্রিয়গ্রাহ্যে"],"correctIndex":3,"subject":"বাংলা","explanation":"মানুষের কণ্ঠনিঃসৃত আওয়াজ হলো ধ্বনি, আর ধ্বনির লিখিত রূপ বা নির্দেশক প্রতীক/চিহ্ন হলো বর্ণ। ধ্বনি ও বর্ণের মূল পার্থক্য ইন্দ্রিয়গ্রাহ্যে, অর্থাৎ ইন্দ্রিয়ের সাহায্যে বোঝা যায় এমন বিষয়ে। ইন্দ্রিয় বলতে বোঝায় দেহের অঙ্গপ্রত্যঙ্গ ও শক্তি (চক্ষু, কর্ণ, নাসিকা, জিহ্বা, ত্বক, বাক, হস্ত, পদ ইত্যাদি) যা দিয়ে বাহ্য বিষয়ের জ্ঞান ও অনুভূতি উপলব্ধ হয়। অপশন বিশ্লেষণ: লেখার ধরন বা উচ্চারণের বিশিষ্টতায় ধ্বনি ও বর্ণের পার্থক্য করা যায় না, কারণ ধ্বনি মুখে উচ্চারিত হয় আর বর্ণ তারই প্রতীক (যেমন: ক ধ্বনির প্রতীক ক বর্ণ)। এখানে ধ্বনি শ্রুতিগ্রাহ্য আর বর্ণ দৃশ্যমান — অর্থাৎ পার্থক্যটা চোখ, কান ইত্যাদি ইন্দ্রিয়ের সাহায্যে বোধগম্যতায়।"},{"id":"bangla-3","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'মৃগয়া' শব্দের মৃগ বলতে কি বোঝানো হয়?","options":["বানর","সিংহ","পশু","বন"],"correctIndex":2,"subject":"বাংলা","explanation":"বাংলা একাডেমি আধুনিক বাংলা অভিধান অনুযায়ী 'মৃগয়া' শব্দের অর্থ হরিণ শিকার বা বন্য পশুপাখি শিকার। আর 'মৃগ' শব্দের অর্থ পশু, হরিণ। অপশন বিশ্লেষণ: বানর শব্দের সমার্থক শব্দ- শাখামৃগ, মর্কট, বাঁদর; সিংহ শব্দের সমার্থক- কেশরী, পশুরাজ, মৃগরাজ, মৃগেন্দ্র; বন শব্দের সমার্থক- অরণ্য, অটবি, কানন, বিপিন, বনানী, কুঞ্জ, কান্তার, গহন।"},{"id":"bangla-4","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'পরিবার থেকেই শিক্ষার শুরু'-এখানে 'থেকে' শব্দের সাথে যুক্ত 'ই'-এর ব্যাকরণিক পরিচয় কী?","options":["উপসর্গ","প্রত্যয়","ধাতু","বলক"],"correctIndex":3,"subject":"বাংলা","explanation":"যেসব শব্দাংশ পদের সঙ্গে যুক্ত হলে বক্তব্য জোরালো হয়, সেগুলোকে বলক বলে। 'তখনই'/'এখনও' পদের 'ই' বা 'ও' বলকের উদাহরণ। তাই 'পরিবার থেকেই শিক্ষার শুরু' বাক্যে 'থেকে' শব্দের সাথে যুক্ত 'ই' হলো বলক। অপশন বিশ্লেষণ: উপসর্গ শব্দমূলের পূর্বে বসে নতুন শব্দ গঠন করে (যেমন: 'পরিচালক' শব্দের 'পরি'); প্রত্যয় শব্দমূলের পরে বসে নতুন শব্দ গঠন করে (যেমন: 'সাংবাদিক' শব্দের 'ইক'); ধাতু হলো ক্রিয়াপদের মূল অংশ (যেমন: কর্, যা, চল্, ধৃ)।"},{"id":"bangla-5","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'স্বাধীন' শব্দের ব্যাসবাক্য কোনটি?","options":["স্বীয়-এর অধীন","সত্তার অধীন","স্ব-এর অধীন","স্বত্বের অধীন"],"correctIndex":2,"subject":"বাংলা","explanation":"'স্বাধীন' শব্দটি ৬ষ্ঠী তৎপুরুষ সমাসের দৃষ্টান্ত; এর ব্যাসবাক্য হলো- স্ব (নিজ) এর অধীন। পরপদের প্রাধান্য এবং ব্যাসবাক্যে নতুন করে র/এর বিভক্তি এলে ৬ষ্ঠী তৎপুরুষ সমাস হয়। অনুরূপ উদাহরণ: পুষ্পসৌরভ (পুষ্পের সৌরভ), চা-বাগান (চায়ের বাগান), মাতৃসেবা (মায়ের সেবা), এবং পরাধীন, বৈষম্যবিরোধী, গল্পপ্রেমিক, মৃগশিশু, ছাগদুগ্ধ, কন্যাসহ, অপরাহ্ন, পূর্বাহ্ন ইত্যাদি।"},{"id":"bangla-6","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'সত্যেকে স্বীকার করতে অনেক ব্যক্তিরাই চায়না।' এখানে ভুল ঘটেছে-","options":["বানান ও প্রত্যয়ের","অর্থ ও বচনের","অর্থ ও প্রত্যয়ের","বানান ও বচনের"],"correctIndex":3,"subject":"বাংলা","explanation":"প্রশ্নোল্লিখিত বাক্যে বানান ও বচনের ভুল ঘটেছে। ক্রিয়ার সাথে না-বোধক অব্যয় আলাদা বসে, তাই সঠিক বানান হবে- চায় না। আর দুটি বহুবচন শব্দ পাশাপাশি থাকলে একটি বাদ দিতে হয়, তাই সঠিক হবে- অনেক ব্যক্তিই। সুতরাং বাক্যটির সঠিক রূপ: সত্যকে স্বীকার করতে অনেক ব্যক্তিই চায় না।"},{"id":"bangla-7","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'এ কাজ করতে আমি বদ্ধ পরিকর'- এখানে 'পরিকর' শব্দের অর্থ কী?","options":["শ্বাস","প্রতিজ্ঞা","কোমর","প্রতিশ্রুত"],"correctIndex":3,"subject":"বাংলা","explanation":"বাংলা একাডেমি আধুনিক বাংলা অভিধান অনুযায়ী 'পরিকর' শব্দের অর্থ- অনুচর, পরিজন, কটিবদ্ধ (কোমরবদ্ধ), পালঙ্ক। তবে প্রশ্নে উল্লিখিত বাক্যে পরিকর বা বদ্ধপরিকর দ্বারা প্রতিশ্রুত বোঝানো হয়েছে। এছাড়া বদ্ধপরিকর শব্দটি দ্বারা বোঝায়- কোনো কাজ করার জন্য উঠেপড়ে লেগেছে এমন, কোমর বেঁধেছে এমন।"},{"id":"bangla-8","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"কোন শব্দটি বিসর্গসন্ধির মাধ্যমে গঠিত?","options":["নীরব","উজ্জ্বল","মানোন্তীর্ণ","সংগ্রাম"],"correctIndex":0,"subject":"বাংলা","explanation":"নীরব শব্দটি বিসর্গ সন্ধিজাত শব্দ। 'নী'-এর পরে 'র' যুক্ত অর্থপূর্ণ শব্দ (রব, রত, রক্ত, রোগ) থাকলে 'নী' পরিবর্তিত হয়ে 'নিঃ' হয়ে যায়— নীরব = নিঃ + রব; নীরত = নিঃ + রত; নীরক্ত = নিঃ + রক্ত; নীরোগ = নিঃ + রোগ। অপশন বিশ্লেষণ: উজ্জ্বল = উৎ + জ্বল (ব্যঞ্জনসন্ধি); মানোন্তীর্ণ = মান + উত্তীর্ণ (স্বরসন্ধি); সংগ্রাম = সম্ + গ্রাম (ব্যঞ্জনসন্ধি)।"},{"id":"bangla-9","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"কোন ধ্বনি পরিবর্তনটি যথাযথ নয়?","options":["ক্রন্দন > কাঁদা","অঞ্চল > আঁচল","সংগীত > গীতিকা","দন্ত > দাঁত"],"correctIndex":2,"subject":"বাংলা","explanation":"ধ্বনির পরিবর্তন হলো উচ্চারণের পরিবর্তন; সম্পূর্ণ নতুন শব্দ গঠিত হলে সেটি ধ্বনির পরিবর্তন নয়। সংগীত > গীতিকায় সম্পূর্ণ নতুন শব্দ গঠিত হয়েছে, তাই এই পরিবর্তনটি যথাযথ নয়। অপশন বিশ্লেষণ: ক্রন্দন > কাঁদা, অঞ্চল > আঁচল, দন্ত > দাঁত শব্দগুলোতে যথাযথভাবে নাসিক্যীভবন (নাসিক্য ব্যঞ্জন ঙ, ঞ, ণ, ন, ম লুপ্ত হয়ে আগের স্বরধ্বনি অনুনাসিক/চন্দ্রবিন্দু হওয়া) ঘটেছে, যেমন অঙ্কন > আঁকা। অনুরূপ: কণ্টক > কাঁটা, কম্পন > কাঁপা।"},{"id":"bangla-10","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'উৎক্ষেপণ' শব্দের 'উৎ' উপসর্গ কোন অর্থ ধারণ করেছে?","options":["জোর","ঊর্ধ্ব","আড়াল","গতি"],"correctIndex":1,"subject":"বাংলা","explanation":"উৎক্ষেপণ শব্দের অর্থ- ঊর্ধ্বে ক্ষেপণ (নিক্ষেপ)। এখানে 'উৎ' উপসর্গটি 'উপরের দিকে' বা 'ঊর্ধ্ব' অর্থ প্রকাশ করে। 'উৎ' উপসর্গ যেসব অর্থ ধারণ করে: ঊর্ধ্বে (উৎক্ষিপ্ত, উদগ্রীব, উত্তোলন, উদ্যম, উন্নতি), প্রস্তুতি (উৎপাদন, উচ্চারণ), আতিশয্য (উৎসুক, উৎফুল্ল, উৎসুক), বাহির (উন্মনা)।"},{"id":"bangla-11","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"কোন্ শব্দটি প্রত্যয়যোগে গঠিত?","options":["ডাক্তারখানা","হাসপাতাল","আকাশছোঁয়া","গুণমান"],"correctIndex":0,"subject":"বাংলা","explanation":"প্রকৃতির পরে যে শব্দাংশ যুক্ত হয়ে নতুন শব্দ তৈরি করে তাকে প্রত্যয় বলে (যেমন: প্রাচুর্য = প্রচুর+য, মশারি = মশা+আরি)। ডাক্তারখানা শব্দটি গঠিত হয়েছে 'খানা (বিদেশি)' প্রত্যয় দিয়ে; অনুরূপ: বৈঠকখানা, ছাপাখানা, কারিগর, নজরবন্দি, রাজবন্দি, চৌকিদার, হাবিলদার, জুতসই। অপশন বিশ্লেষণ: হাসপাতাল বিদেশি শব্দ, কোনো প্রত্যয় যুক্ত হয়নি; আকাশছোঁয়া সমাসযোগে গঠিত শব্দ (আকাশকে ছোঁয়া); গুণমান অশুদ্ধ শব্দ, সঠিক শব্দ গুণবান।"},{"id":"bangla-12","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"রবীন্দ্রনাথ ঠাকুর শব্দের শুরুতে মাত্রাযুক্ত এ-কার ব্যবহার করতেন কেন?","options":["এ-কার মাত্রা যুক্ত বলে","'এ' মাত্রাহীন বর্ণ বলে","'এ' উচ্চারণ বোঝাতে","'অ্যা' উচ্চারণ বোঝাতে"],"correctIndex":3,"subject":"বাংলা","explanation":"এ ধ্বনির দুটি উচ্চারণ হয়: এ > এ (সংবৃত) এবং এ > অ্যা (বিবৃত)। শব্দের শুরুতে এ-কারের উচ্চারণ সাধারণত সংবৃত হয় (যেমন: বেশি, মেয়ে)। তবে রবীন্দ্রনাথ ঠাকুর শব্দের শুরুতে মাত্রাযুক্ত এ-কার ব্যবহার করতেন 'অ্যা' উচ্চারণ বোঝাতে, যেমন এক [অ্যাক্], খেলা [খ্যালা], যেমন [জ্যামোন্]।"},{"id":"bangla-13","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"পারিভাষিক শব্দ বলতে বুঝায়-","options":["ইংরেজি শব্দের বাংলা রূপান্তর","বিদেশি শব্দের অনুবাদ","বিষয়গত সুনির্দিষ্ট অর্থবোধক শব্দ","ব্যবহারিক প্রয়োজনে নবনির্মিত শব্দ"],"correctIndex":2,"subject":"বাংলা","explanation":"পরিভাষা হলো বিশেষ অর্থ প্রকাশকারী শব্দ বা শব্দরাশি। যে সুনির্দিষ্ট অর্থবোধক শব্দ দ্বারা কোনো বিষয়কে ব্যক্ত করা যায় তা-ই পারিভাষিক শব্দ; এগুলো নির্দিষ্ট বিষয়, শাস্ত্র বা ক্ষেত্রের সাথে সম্পর্কিত। যেমন: Acting- ভারপ্রাপ্ত; Amicus curie- আদালতের বন্ধু; Pedagogy- শিক্ষণবিজ্ঞান/শিক্ষাতত্ত্ব; Heavenly body- জ্যোতিষ্ক।"},{"id":"bangla-14","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'তিনি কথা শুনে ঘুমাতে পারলেন না'- বাক্যটির অস্তিবাচক রূপ কী হবে?","options":["তিনি কথা না শুনে ঘুমাতে পারলেন না","তিনি কথা না শুনে ঘুমাতে পারলেন","তিনি জেগে রইলেন কথা না শুনে","তিনি কথা শুনে জেগে রইলেন"],"correctIndex":3,"subject":"বাংলা","explanation":"নেতিবাচক বাক্যকে অস্তিবাচক বাক্যে রূপান্তরের নিয়ম: (১) মূল অর্থ পরিবর্তন হবে না, (২) না-বোধক শব্দ বাদ দিতে হবে, (৩) প্রয়োজনে বিপরীত শব্দ ব্যবহার করা যাবে। এই নিয়ম অনুসারে 'তিনি কথা শুনে ঘুমাতে পারলেন না'-এর অস্তিবাচক রূপ: তিনি কথা শুনে জেগে রইলেন। এখানে মূল অর্থের পরিবর্তন হয়নি; না-বোধক শব্দ বাদ হয়েছে এবং বিপরীতধর্মী শব্দ বসেছে।"},{"id":"bangla-15","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'শিক্ষককে বুঝতে হবে শিক্ষার্থী কী চায়'- এই বাক্যে শিক্ষক ও শিক্ষার্থীর প্রয়োগ হয়েছে-","options":["একবচন বোঝাতে","বহুবচন বোঝাতে","একবচন ও বহুবচন উভয়ই বোঝাতে","প্রথমটি একবচন, পরেরটি বহুবচন বোঝাতে"],"correctIndex":1,"subject":"বাংলা","explanation":"এই বাক্যে শিক্ষক শব্দটি দ্বারা শিক্ষক জাতি/সকল শিক্ষক এবং শিক্ষার্থী শব্দটি দ্বারা শিক্ষার্থী জাতি/সকল শিক্ষার্থীকে বোঝানো হয়েছে। অর্থাৎ প্রশ্নোল্লিখিত বাক্যটি দ্বারা শিক্ষক ও শিক্ষার্থী উভয়েরই বহুবচন প্রয়োগ ঘটেছে।"},{"id":"bangla-16","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"ভাষা-পরিবার অনুযায়ী সাঁওতাল জনগোষ্ঠী প্রধানত কোন পরিবারভুক্ত?","options":["ইন্দো-আর্য","দ্রাবিড়","অস্ত্রিক-অস্ট্রো এশিয়াটিক (মুন্ডা)","তিব্বত-বর্মী"],"correctIndex":2,"subject":"বাংলা","explanation":"সাঁওতাল জনগোষ্ঠী অস্ত্রিক ভাষী; ভাষা-পরিবার অনুযায়ী এরা অস্ত্রিক-অস্ট্রো এশিয়াটিক (মুন্ডা) পরিবারভুক্ত। কোল ও মুন্ডারি ভাষার সঙ্গে সাঁওতালি ভাষার সাদৃশ্য রয়েছে; এরা আদি-অস্ট্রেলীয় (প্রোটো-অস্ট্রালয়েড) জনগোষ্ঠীর বংশধর। সাঁওতালরা ভারতীয় উপমহাদেশের অন্যতম আদি বাসিন্দা এবং কৃষি উৎপাদন ব্যবস্থা ও কৃষিসংস্কৃতির জনক-ধারক হিসেবে স্বীকৃত; তাদের বাসস্থান মূলত রাজশাহী, দিনাজপুর, রংপুর ও বগুড়া জেলায়, আর প্রধান নিবাস রাঢ়বঙ্গ, বিহার-উড়িষ্যার অরণ্য অঞ্চল ও ছোটনাগপুর। তাদের বছর শুরু হয় ফাল্গুন মাসে, আর পৌষ সংক্রান্তিতে পালিত হয় সোহরাই উৎসব।"},{"id":"bangla-17","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'কম দামে কেনা বেশী দামে বেচা আমাদের স্বাধীনতা'-বইটির লেখক কে?","options":["আবুল কালাম শামসুদ্দীন","আবুল মনসুর আহমদ","শামসুদ্দিন আবুল কালাম","এস ওয়াজেদ আলী"],"correctIndex":1,"subject":"বাংলা","explanation":"'বেশী দামে কেনা কম দামে বেচা আমাদের স্বাধীনতা' গ্রন্থটির রচয়িতা রম্য রচনার বিখ্যাত লেখক আবুল মনসুর আহমদ। এই গ্রন্থে ৪২টি নিবন্ধ রয়েছে, যার মধ্যে প্রথম ৩৯টি ১৯৭২ ও ১৯৭৩ সালে দৈনিক ইত্তেফাকে প্রকাশিত হয়েছিল।"},{"id":"bangla-18","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"চর্যাপদের খণ্ডিত পদগুলো তিব্বতি থেকে প্রাচীন বাংলায় রূপান্তর করেন-","options":["সুনীতিকুমার চট্টোপাধ্যায়","হরপ্রসাদ শাস্ত্রী","রাজেন্দ্রলাল মিত্র","সুকুমার সেন"],"correctIndex":3,"subject":"বাংলা","explanation":"চর্যাপদ তিব্বতি ভাষায় অনুবাদ করেন কীর্তিচন্দ্র; তবে চর্যাপদের তিব্বতি অনুবাদকে বাংলায় রূপান্তর করেন সুকুমার সেন। চর্যাপদের আবিষ্কৃত পদের সংখ্যা সাড়ে ছেচল্লিশটি (ড. মুহম্মদ শহীদুল্লাহর মত)। ২৩ নং পদটি (ভুসুকুপা রচিত) খণ্ডিত আকারে ৬ লাইন পাওয়া গেলেও বাকি ৪ লাইন পাওয়া যায়নি; এছাড়া ২৪ নং (কাহ্নপা), ২৫ নং (তন্ত্রীপা) ও ৪৮ নং (কুক্কুরীপা) পদগুলো পাওয়া যায়নি। যেহেতু সুকুমার সেন সম্পূর্ণ চর্যাপদের তিব্বতি অনুবাদকে বাংলায় রূপান্তর করেন, তাই খণ্ডিত ও হারানো পদগুলো (২৩, ২৪, ২৫ ও ৪৮) তিনিই তিব্বতি থেকে বাংলায় রূপান্তর করেন।"},{"id":"bangla-19","exam":"৪৯তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"আহমদ শরীফের মতে মধ্যযুগে চণ্ডীদাস নামে কতজন কবি ছিলেন?","options":["২","৩","৪","৫"],"correctIndex":1,"subject":"বাংলা","explanation":"মধ্যযুগে বাংলা সাহিত্যের অঙ্গনে চারজন চণ্ডীদাসের আবির্ভাব ঘটেছিল বলে সাধারণত মনে করা হয়- বড়ু চণ্ডীদাস, দ্বিজ চণ্ডীদাস, দীন চণ্ডীদাস ও চণ্ডীদাস (কেউ কেউ দ্বিজ ও দীন চণ্ডীদাসকে একই ব্যক্তি মনে করেন)। তাদের জন্মের স্থান-কাল ও সাহিত্যকর্ম নিয়ে মতবিরোধ ও অস্পষ্টতা 'চণ্ডীদাস সমস্যা' নামে পরিচিত। ড. আহমদ শরীফের মতে অবশ্য মধ্যযুগে চণ্ডীদাস নামে ৩ জন কবি ছিলেন: (১) অনন্ত বড়ু চণ্ডীদাস- সর্বপ্রাচীন চণ্ডীদাস, (২) চণ্ডীদাস- চৈতন্য পূর্বকালের বা জ্যেষ্ঠ সমসাময়িক, (৩) দীন চণ্ডীদাস- আঠারো শতকের শেষার্ধ।"},{"id":"bangla-20","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"'যে আলোতে কুমুদ ফোটে'- এককথায় কী হবে?","options":["কুমুদিন","কৌমুদী","প্রভাবতী","বিভা"],"correctIndex":1,"subject":"বাংলা","explanation":"কুমুদ শব্দের অর্থ পদ্ম। যে আলোতে কুমুদ ফোটে তাকে বলে কৌমুদী; কৌমুদী শব্দের অর্থ চাঁদের আলো, জ্যোৎস্না। কৌমুদী সংস্কৃত শব্দ, যার প্রকৃতি ও প্রত্যয় হলো কুমুদ+অ+ঈ। অপশন বিশ্লেষণ: কুমুদিন নামে কোনো শব্দ নেই (কুমুদিনী/মৃণালিনী শব্দের অর্থ পদ্মের ঝাড়); প্রভাবান শব্দের অর্থ দীপ্তিমান/উজ্জ্বল, যার স্ত্রীবাচক রূপ প্রভাবতী; বিভা শব্দের অর্থ আলোক, কিরণ, প্রভা।"},{"id":"bangla-21","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"কোন শব্দে দ্বিস্বরধ্বনি রয়েছে?","options":["তিসি","মালি","লাউ","মেয়ে"],"correctIndex":2,"subject":"বাংলা","explanation":"পূর্ণ স্বরধ্বনি ও অর্ধস্বরধ্বনি একত্রে উচ্চারিত হলে দ্বিস্বরধ্বনি বা যৌগিক স্বরধ্বনি সৃষ্টি হয়। লাউ শব্দে পূর্ণ স্বরধ্বনি [আ] ও অর্ধস্বরধ্বনি [উ] মিলে দ্বিস্বরধ্বনি [আউ] তৈরি হয়েছে। দ্বিস্বরধ্বনির আরও উদাহরণ: [আই]-তাই,নাই; [আও]-যাও,দাও; [আএ]-খায়,যায়; [অএ]-নয়,হয়; [এই]-সেই,নেই; [এউ]-কেউ,ঘেউ; [ওই]-কৈ,দই; [ওউ]-মৌ,বউ। অপশন বিশ্লেষণ: তিসি (ত্+ই+স্+ই), মালি (ম্+আ+ল্+ই), মেয়ে (ম্+এ+য়্+এ)- এই তিনটি শব্দে দুটি করে পৃথক (একক) স্বরধ্বনি আছে, দ্বিস্বরধ্বনি নয়।"},{"id":"bangla-22","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"প্রত্যয়যোগে গঠিত শব্দ কোনটি?","options":["ডাক্তারখানা","অনুগমন","দিলখোলা","সম্রাট"],"correctIndex":0,"subject":"বাংলা","explanation":"ডাক্তারখানা শব্দটি 'ডাক্তার+খানা' (তদ্ধিত প্রত্যয়যোগে) গঠিত। অনুগমন (পশ্চাৎ গমন) অব্যয়ীভাব সমাসে এবং দিলখোলা (দিল খোলা যার) বহুব্রীহি সমাসে গঠিত শব্দ। সম্রাট শব্দটিও কৃৎ প্রত্যয়যোগে (সম্+√রাজ্+অ) গঠিত বলে কোনো কোনো ব্যাখ্যায় উল্লেখ থাকলেও, বিপিএসসির প্রকাশিত সরকারি উত্তরমালা অনুযায়ী এই প্রশ্নের চূড়ান্ত সঠিক উত্তর নির্ধারিত হয়েছে ডাক্তারখানা।"},{"id":"bangla-23","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"'তিনি কথা বললেন না।'-বাক্যটির অস্তিবাচক রূপ কী হবে?","options":["তিনি কথা বলতে চাইলেন না।","তিনি কথা না বলে থাকতে পারলেন না।","তিনি নীরব থাকতে চেষ্টা করলেন।","তিনি চুপ করে থাকলেন।"],"correctIndex":3,"subject":"বাংলা","explanation":"নেতিবাচক বাক্যকে অস্তিবাচক বাক্যে রূপান্তরের নিয়ম: (১) মূল অর্থের পরিবর্তন হবে না, (২) না-বোধক শব্দ বাদ দিতে হবে, (৩) প্রয়োজনে বিপরীতধর্মী শব্দ ব্যবহার করা যাবে। এই নিয়ম অনুযায়ী 'তিনি কথা বললেন না।'-এর অস্তিবাচক রূপ হলো 'তিনি চুপ করে থাকলেন।' অনুরূপ উদাহরণ: 'মিথ্যাবাদীকে কেউ পছন্দ করে না' → 'মিথ্যাবাদীকে সবাই অপছন্দ করে'; 'তপুর আগে কেউ উঠতে পারত না' → 'তপু সবার আগে উঠত'; 'তাতে সমাজজীবন চলে না' → 'তাতে সমাজজীবন অচল হয়ে পড়ে'।"},{"id":"bangla-24","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"'অন্তর্ভুক্তিমূলক' শব্দ উচ্চারণে কয়টি অক্ষর পাওয়া যায়?","options":["৫","৬","৭","৮"],"correctIndex":1,"subject":"বাংলা","explanation":"নিঃশ্বাসের স্বল্পতম প্রয়াসে উচ্চারিত ধ্বনি বা ধ্বনিগুচ্ছকে অক্ষর বলে। সংশ্লিষ্ট টেকনিক- একটি শব্দে যতগুলো স্বরধ্বনি/স্বরচিহ্ন থাকে, সেই শব্দে ততগুলো অক্ষর থাকে। অন্তর্ভুক্তিমূলক শব্দ ভাঙলে পাওয়া যায়- অন্+তর্+ভুক্+তি+মূ+লক্, অর্থাৎ এতে ৬টি স্বরধ্বনি তথা ৬টি অক্ষর আছে। তুলনায়: বন্ধন = বন্+ধন (২টি অক্ষর), মা (১টি অক্ষর), বিশ্ববিদ্যালয় = বি+শ্ব+বি+দ্যা+লয় (৫টি অক্ষর)।"},{"id":"bangla-25","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"শুদ্ধ বাক্য কোনটি?","options":["সারা দেশব্যাপী দিবসটি উদ্‌যাপন করা হবে।","সারা দেশে দিবসটি উদ্যাপন করা হবে।","দেশব্যাপী দিবসটি উদ্যাপন করা হবে।","সারা দেশে দিবসটি উদ্‌যাপন করা হবে।"],"correctIndex":3,"subject":"বাংলা","explanation":"শুদ্ধ বাক্য নির্ণয়ে বানান ও ব্যাকরণসম্মত নিয়ম যথাযথভাবে প্রয়োগ করতে হয়; প্রশ্নে শুদ্ধ বাক্য হলো 'সারা দেশে দিবসটি উদ্‌যাপন করা হবে।' অপশন (ক)-তে 'সারা দেশব্যাপী' প্রয়োগ অশুদ্ধ, কারণ দেশব্যাপী অর্থই সমগ্র দেশে পরিব্যাপ্ত; এর আগে আবার 'সারা' বসালে অর্থ দাঁড়ায় 'সারা সমগ্র দেশে পরিব্যাপ্ত', যা বাহুল্য দোষে দুষ্ট। অপশন (খ) ও (গ)-তে 'উদ্যাপন' বানানটি ভুল। (উল্লেখ্য, মূল প্রশ্নপত্রেই অপশন (খ) ও (ঘ)-এর টেক্সট হুবহু একরকম মুদ্রিত হয়েছিল বলে একাধিক স্বতন্ত্র সমাধান-সূত্রেও পাওয়া যায়; সরকারি উত্তরমালায় নির্ধারিত সঠিক উত্তর অপশন (ঘ)।)"},{"id":"bangla-26","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"ক্রিয়া পদের মূল অংশকে কী বলে?","options":["কর্ম","ধাতু","প্রত্যয়","বিভক্তি"],"correctIndex":1,"subject":"বাংলা","explanation":"ক্রিয়াপদের মূল অংশকে বলা হয় ধাতু বা ক্রিয়ামূল। ক্রিয়াপদকে বিশ্লেষণ করলে দুটি অংশ পাওয়া যায়- প্রথম অংশ ধাতু/ক্রিয়ামূল এবং দ্বিতীয় অংশ ক্রিয়াবিভক্তি। ধাতু তিন প্রকার- মৌলিক ধাতু, সাধিত ধাতু ও যৌগিক ধাতু। অপশন বিশ্লেষণ: কর্তা যাকে আশ্রয় করে ক্রিয়া সম্পাদন করে তাকে কর্ম বলে; নাম প্রকৃতি বা ক্রিয়া প্রকৃতির পরে যুক্ত হয়ে শব্দ গঠনকারী শব্দাংশকে প্রত্যয় বলে; বাক্যস্থিত একটি শব্দের সঙ্গে অন্য শব্দের অন্বয় সাধনের জন্য যুক্ত বর্ণকে বিভক্তি বলে।"},{"id":"bangla-27","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"'আফতাব' শব্দের সমার্থক শব্দ কোনটি?","options":["অর্ণব","রাতুল","অর্ক","জলধি"],"correctIndex":2,"subject":"বাংলা","explanation":"'আফতাব' শব্দের সমার্থক শব্দ- অর্ক, সূর্য, রবি, আদিত্য, দিবাকর, পূষা, সবিতা, প্রভাকর, তপন, ভানু, ভাস্কর, দিনেশ, মার্তণ্ড, দিনকর প্রভৃতি। অপশন বিশ্লেষণ: রাতুল অর্থ লাল বা রক্তবর্ণ; জলধি ও অর্ণব উভয়ই সমুদ্র বোঝায়।"},{"id":"bangla-28","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"বাক্যের অন্তর্গত শব্দের পারস্পরিক সম্পর্ক ব্যাকরণের কোন অংশে আলোচিত হয়?","options":["সন্ধি","পদ","কাল","কারক"],"correctIndex":3,"subject":"বাংলা","explanation":"বাক্যস্থিত ক্রিয়াপদের সাথে নামপদের সম্পর্ককে কারক বলে; বাক্যের অন্তর্গত শব্দের পারস্পরিক সম্পর্ক কারকে আলোচিত হয়, আর কারক বাক্যতত্ত্বের আলোচ্য বিষয়। অপশন বিশ্লেষণ: সন্নিহিত দুটি ধ্বনির মিলনকে সন্ধি বলে, যার উদ্দেশ্য ধ্বনিগত মাধুর্য সৃষ্টি ও উচ্চারণ সহজবোধ্য করা; বিভক্তিযুক্ত শব্দ/ধাতু বা বাক্যে ব্যবহৃত প্রতিটি অর্থবোধক শব্দকে পদ বলে; ক্রিয়া সম্পন্ন হওয়ার সময়কে (বর্তমান/অতীত/ভবিষ্যৎ) কাল বলে।"},{"id":"bangla-29","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"অনুভূতিজাত দ্বিরুক্ত শব্দ কোনটি?","options":["ছমছম","ঝমঝম","টিকটিক","ঠিক ঠিক"],"correctIndex":0,"subject":"বাংলা","explanation":"যেসব দ্বিরুক্ত শব্দ দ্বারা আওয়াজ ছাড়া কেবল অনুভূতি প্রকাশ পায়, সেগুলো অনুভূতিজাত দ্বিরুক্ত শব্দ; যেমন- ছমছম (ভীতিজনিত শিহরনের ভাব), টনটন (দুঃসহ ব্যথার ভাব), বাঁ বাঁ (প্রখরতার ভাব), খাঁ খাঁ (শূন্যতার ভাব)। অপশন বিশ্লেষণ: ঝমঝম ও টিকটিক আওয়াজ/ধ্বনিব্যঞ্জনা বোঝায় (ঝমঝম- বৃষ্টি পড়ার অনুকার শব্দ; টিকটিক- টিকটিকির ডাক); ঠিক ঠিক শব্দটি আওয়াজ বা অনুভূতি কোনোটিই বোঝায় না, এর অর্থ ঠিকমতো/যথার্থ।"},{"id":"bangla-30","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"কোন বানানটি প্রমিত?","options":["পশ্চাদপদ","পশ্চাৎগামী","পশ্চাদ্‌ভূমি","পশ্চাৎবর্তী"],"correctIndex":2,"subject":"বাংলা","explanation":"প্রমিত/সঠিক বানান পশ্চাদ্‌ভূমি (অর্থ- পেছনের স্থান, পটভূমি); এর সন্ধিবিচ্ছেদ পশ্চাৎ+ভূমি। নিয়ম হলো- পশ্চাৎ ও পশ্চাৎপদ এই দুটি শব্দে খণ্ড-ত (ৎ) অক্ষুণ্ন থাকে; এই দুটি ছাড়া অন্য যেসব শব্দে পশ্চাৎ-এর পরে ভ, গ, দ-জাতীয় ধ্বনি বসে সেখানে সাধারণত 'দ' হয়, যেমন- পশ্চাদ্‌ভূমি, পশ্চাদ্গামী, পশ্চাদ্দেশ, পশ্চাদ্বর্তী, পশ্চাদপসারণ। এই নিয়মে অপশন (ক) পশ্চাদপদ ভুল (শুদ্ধ: পশ্চাৎপদ) এবং অপশন (খ) পশ্চাৎগামী ভুল (শুদ্ধ: পশ্চাদ্গামী)। অপশন (ঘ) পশ্চাৎবর্তীও অপ্রমিত রূপ (শুদ্ধ রূপ পশ্চাদ্বর্তী), তাই এই চারটির মধ্যে কেবল অপশন (গ) পশ্চাদ্‌ভূমি-ই প্রমিত বানান।"},{"id":"bangla-31","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"বাংলা অব্যয়ীভাব সমাসের উদাহরণ ব্যাকরণের কোন অংশের অন্তর্ভুক্ত করা যায়?","options":["সন্ধি","উপসর্গ","কারক","প্রত্যয়"],"correctIndex":1,"subject":"বাংলা","explanation":"অব্যয়ীভাব সমাসের পূর্বপদে উপসর্গ থাকে বলে এর উদাহরণগুলো উপসর্গের অন্তর্ভুক্ত করা যায়। যেমন- আমরণ, হাভাত, গরমিল, উপকূল, অনুদিন, অতিমানব, প্রতিবাদ প্রভৃতি অব্যয়ীভাব সমাসের উদাহরণ, যেখানে প্রতিটি শব্দের শুরুতে উপসর্গ (আ, হা, গর, উপ, অনু, অতি, প্রতি) রয়েছে।"},{"id":"bangla-32","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"কোনটি বিশেষণ?","options":["সৎ","একতা","দর্শন","জনতা"],"correctIndex":0,"subject":"বাংলা","explanation":"যে পদ অন্য পদের দোষ, গুণ, অবস্থা, সংখ্যা, পরিমাণ ইত্যাদি প্রকাশ করে তাকে বিশেষণ পদ বলে; যেমন- সৎ ব্যক্তি, সুন্দর পৃথিবী, চলন্ত গাড়ি, দুই ছেলে, তাজা মাছ। অপশন বিশ্লেষণ: একতা, দর্শন, জনতা- এই তিনটি শব্দ বিশেষ্য পদের উদাহরণ।"},{"id":"bangla-33","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"ছড়ার ছন্দকে কী বলে?","options":["স্বরবৃত্ত","মাত্রাবৃত্ত","অক্ষরবৃত্ত","গদ্যছন্দ"],"correctIndex":0,"subject":"বাংলা","explanation":"কাব্যের গতিসৌন্দর্য বিধায়ক স্বতঃস্ফূর্ত নির্মাণকৌশলকে ছন্দ বলে। বাংলা ছন্দ প্রধানত তিন প্রকার- স্বরবৃত্ত, অক্ষরবৃত্ত ও মাত্রাবৃত্ত। স্বরবৃত্ত ছন্দকে বলা হয় লৌকিক ছন্দ/ছড়ার ছন্দ/শ্বাসাঘাত প্রধান ছন্দ; অনেকের মতে আধুনিক স্বরবৃত্ত ছন্দ মধ্যযুগীয় কাব্য শ্রীকৃষ্ণকীর্তনের ধামালি ছন্দ থেকে উদ্ভূত। মাত্রাবৃত্ত ছন্দকে ছন্দের ক্ষেত্রে রবীন্দ্রনাথের শ্রেষ্ঠ অবদান বলে মনে করা হয়, একে ধ্বনিপ্রধান/বিস্তারপ্রধান/সরল কলামাত্রিক ছন্দও বলা হয়। অক্ষরবৃত্ত ছন্দ বাংলা কাব্যের প্রধান ছন্দ, একে তানপ্রধান ছন্দ/তত্ত্ব ছন্দ/আধুনিক মাত্রা ছন্দও বলা হয়; এই ছন্দের ভিত্তিতে সৃষ্ট অন্ত্যমিলহীন রূপকে অমিত্রাক্ষর ছন্দ বলে।"},{"id":"bangla-34","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"ভাষা","question":"Transparency শব্দের বাংলা পরিভাষা কী?","options":["যথার্থতা","নির্ভরযোগ্যতা","স্বচ্ছতা","দুর্নীতিদমন"],"correctIndex":2,"subject":"বাংলা","explanation":"Transparency শব্দের বাংলা পরিভাষা স্বচ্ছতা (Transparent অর্থ স্বচ্ছ)। অপশন বিশ্লেষণ: Accuracy-র পরিভাষা যথার্থতা, Reliability-র পরিভাষা নির্ভরযোগ্যতা, আর Anti-Corruption-এর পরিভাষা দুর্নীতিদমন।"},{"id":"bangla-35","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"সাহিত্য","question":"ফররুখ আহমদের 'সাত সাগরের মাঝি' কত সালে প্রকাশিত হয়?","options":["১৯০৫","১৯৪০","১৯৪৪","১৯৫৫"],"correctIndex":2,"subject":"বাংলা","explanation":"মুসলিম রেনেসাঁর কবি ও ইসলামি আদর্শের উজ্জ্বল প্রতীক ফররুখ আহমদের শ্রেষ্ঠ কাব্যগ্রন্থ 'সাত সাগরের মাঝি', যা ১৯৪৪ সালে প্রকাশিত হয়; এর মূল উপজীব্য ইসলামের ইতিহাস ও ঐতিহ্য। তাঁর অন্যান্য উল্লেখযোগ্য রচনা- হাতেমতায়ী (কাহিনিকাব্য, যার জন্য তিনি আদমজী পুরস্কার লাভ করেন), মুহূর্তের কবিতা (সনেট সংকলন), নৌফেল ও হাতেম (কাব্যনাট্য), সিরাজাম মুনীরা; শিশুতোষ গ্রন্থ পাখির বাসা (তাঁর প্রথম প্রকাশিত শিশুতোষ গ্রন্থ, যার জন্য ইউনেস্কো পুরস্কার লাভ করেন), নতুন লেখা, ছড়ার আসর, চাঁদের আসর, চিড়িয়াখানা, ফুলের জলসা, হরফের ছড়া; বিখ্যাত কবিতা- পাঞ্জেরি, উপহার, স্মরণী।"},{"id":"bangla-36","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"সাহিত্য","question":"'ইউসুফ-জোলেখা'র কবি শাহ মুহম্মদ সগীরের জন্ম কোথায়?","options":["বগুড়া","সিলেট","নদীয়া","চট্টগ্রাম"],"correctIndex":3,"subject":"বাংলা","explanation":"বাংলা সাহিত্যের প্রথম মুসলমান কবি শাহ মুহম্মদ সগীর (পনেরো শতকের কবি) সুলতান গিয়াসউদ্দীন আযম শাহের রাজকর্মচারী/সভাকবি ছিলেন এবং তাঁরই পৃষ্ঠপোষকতায় 'ইউসুফ-জোলেখা' রোমান্টিক প্রণয়োপাখ্যান রচনা করেন। তাঁর জন্মস্থান নিয়ে সরাসরি কোনো তথ্য পাওয়া না গেলেও, তাঁর কাব্যে তৎকালীন চট্টগ্রাম অঞ্চলের ভাষার প্রয়োগ থাকায় ধারণা করা হয় তিনি চট্টগ্রামের অধিবাসী ছিলেন। বাংলা রোমান্টিক প্রণয়োপাখ্যান ধারার আদি কবি/প্রথম বাঙালি কবি হিসেবে তিনি পরিচিত।"},{"id":"bangla-37","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"সাহিত্য","question":"'আজ চারদিক হতে ধনিক বণিক শোষণকারীর জাত, ও ভাই জোঁকের মতন শুষছে রক্ত, কাড়ছে থালার ভাত।'-কার লেখা?","options":["রবীন্দ্রনাথ ঠাকুর","কাজী নজরুল ইসলাম","গোলাম মোস্তফা","সত্যেন্দ্রনাথ দত্ত"],"correctIndex":1,"subject":"বাংলা","explanation":"উদ্ধৃতাংশটি বিদ্রোহী কবি কাজী নজরুল ইসলাম রচিত 'সর্বহারা' কাব্যগ্রন্থের অন্তর্গত 'কৃষাণের গান' কবিতার অংশ, যেখানে কবির বিদ্রোহী সত্তা ও শোষিত-বঞ্চিত কৃষক সমাজের প্রতি সহমর্মিতা প্রকাশ পেয়েছে।"},{"id":"bangla-38","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"সাহিত্য","question":"ইসমাইল হোসেন সিরাজীর কোন কাব্যটি বাজেয়াপ্ত হয়?","options":["'অনল প্রবাহ'","'আকাঙ্ক্ষা'","'উদ্বোধন'","'নব উদীপনা'"],"correctIndex":0,"subject":"বাংলা","explanation":"মুসলিম পুনর্জাগরণবাদী কবি সৈয়দ ইসমাইল হোসেন সিরাজীর প্রথম ও শ্রেষ্ঠ কাব্যগ্রন্থ 'অনল প্রবাহ' (১৯০০); মুসলিম জাগরণমূলক এই কাব্যে ইংরেজবিরোধী তীব্র মনোভাব প্রকাশ পাওয়ায় গ্রন্থটি ইংরেজ সরকার কর্তৃক নিষিদ্ধ/বাজেয়াপ্ত হয়। তাঁর অন্যান্য কাব্যগ্রন্থ- স্পেন বিজয় কাব্য (মহাকাব্য), আকাঙ্ক্ষা, উচ্ছ্বাস, নব উদীপনা, সঙ্গীত সঞ্জীবনী, প্রেমাঞ্জলি; উপন্যাস- রায়নন্দিনী, তারাবাঈ, ফিরোজা বেগম, নূরউদ্দীন।"},{"id":"bangla-39","exam":"৪৮তম বিসিএস প্রিলিমিনারি (বিশেষ) পরীক্ষা","topic":"সাহিত্য","question":"'শ্রীকৃষ্ণকীর্তন' কাব্যের প্রথম খণ্ডের নাম কী?","options":["জন্মখণ্ড","তাম্বুলখণ্ড","দানখণ্ড","রাধাবিরহ"],"correctIndex":0,"subject":"বাংলা","explanation":"মধ্যযুগের বাংলা সাহিত্যের আদি ও শ্রেষ্ঠ নিদর্শন 'শ্রীকৃষ্ণকীর্তন', যা সম্পূর্ণ বাংলা ভাষায় রচিত প্রথম গ্রন্থ; এর রচয়িতা মধ্যযুগের আদি কবি বড়ু চণ্ডীদাস। এ কাব্যে মোট ১৩টি খণ্ড রয়েছে, যার প্রথমটি জন্মখণ্ড (এরপর যথাক্রমে তাম্বুলখণ্ড, দানখণ্ড, নৌকাখণ্ড, ভারখণ্ড, ছত্রখণ্ড, বৃন্দাবনখণ্ড, কালিয়দমনখণ্ড, যমুনাখণ্ড, হারখণ্ড, বাণখণ্ড, বংশীখণ্ড ও বিরহখণ্ড)। ১৯০৯ সালে বসন্তরঞ্জন রায় বিদ্বদ্বল্লভ পশ্চিমবঙ্গের বাঁকুড়া জেলার কাঁকিল্যা গ্রামের একটি গোয়ালঘর থেকে কাব্যটি আবিষ্কার করেন, এবং ১৯১৬ সালে 'বঙ্গীয় সাহিত্য পরিষদ' থেকে এটি প্রকাশিত হয়।"},{"id":"bangla-40","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'লুই ভণই গুরু পুছিঅ জাণ।'-এখানে 'ভণই' শব্দের অর্থ কী?","options":["বলে","ভাবে","চায়","দেখে"],"correctIndex":0,"subject":"বাংলা","explanation":"লুই হলেন চর্যাপদের কবি লুইপা; 'ভণই' অর্থ বলে, 'গুরু' অর্থ শিক্ষক, 'পুছিঅ' অর্থ জিজ্ঞাসা করো, 'জাণ' অর্থ জ্ঞান। আধুনিক বাংলায় ছত্রটির অর্থ- কবি লুইপা বলেন, জ্ঞান লাভের জন্য গুরুকে জিজ্ঞাসা করো। এই পঙ্‌ক্তিটি চর্যাপদের ১নং পদের চরণ, যার রচয়িতা বাংলা সাহিত্যের আদি কবি লুইপা (চর্যার ১ ও ২৯ নং পদের রচয়িতা); তিনি সংস্কৃতে 'অভিসময় বিভঙ্গ' নামে একটি গ্রন্থ রচনা করেন।"},{"id":"bangla-41","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'শ্রীকৃষ্ণকীর্তন' কাব্যের অংশ নয় কোনটি?","options":["নৌকা খণ্ড","হার খণ্ড","রাধা বিরহ","প্রণয় খণ্ড"],"correctIndex":3,"subject":"বাংলা","explanation":"মধ্যযুগের বাংলা সাহিত্যের আদি ও শ্রেষ্ঠ নিদর্শন, বড়ু চণ্ডীদাস রচিত 'শ্রীকৃষ্ণকীর্তন' কাব্যে মোট ১৩টি খণ্ড রয়েছে- জন্মখণ্ড, তাম্বুলখণ্ড, দানখণ্ড, নৌকাখণ্ড, ভারখণ্ড, ছত্রখণ্ড, বৃন্দাবনখণ্ড, কালিয়দমনখণ্ড, যমুনাখণ্ড, হারখণ্ড, বাণখণ্ড, বংশীখণ্ড ও বিরহখণ্ড (বিরহখণ্ডকেই রাধাবিরহ বলা হয়)। এই তালিকায় 'প্রণয় খণ্ড' নামে কোনো খণ্ড নেই।"},{"id":"bangla-42","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"বিবৃত স্বরধ্বনি বলতে বোঝায়-","options":["যে স্বরধ্বনি উচ্চারণে ঠোঁট বেশি খোলে","যে স্বরধ্বনি উচ্চারণে জিভ উঁচু হয়","যে স্বরধ্বনি অবিকৃতভাবে উচ্চারিত হয়","যে স্বরধ্বনি উচ্চারণে বিকৃতি ঘটে"],"correctIndex":0,"subject":"বাংলা","explanation":"জিভের উচ্চতা ও ঠোঁটের উন্মুক্তি অনুযায়ী স্বরধ্বনির শ্রেণিবিভাগ করা হয়। বিবৃত স্বরধ্বনি উচ্চারণে ঠোঁট সবচেয়ে বেশি খোলে; বিবৃত স্বরধ্বনি একটি- 'আ', যা জিভের উচ্চতা অনুযায়ী নিম্ন স্বরধ্বনি। বিপরীতে, সংবৃত স্বরধ্বনি উচ্চারণের সময় ঠোঁট সবচেয়ে কম খোলে; সংবৃত স্বরধ্বনি দুটি- 'ই' ও 'উ', যা জিভের উচ্চতা অনুযায়ী উচ্চ স্বরধ্বনি। এই মাঝামাঝি ধাপে আছে অর্ধ-সংবৃত (এ, ও) ও অর্ধ-বিবৃত (অ্যা, অ) স্বরধ্বনি।"},{"id":"bangla-43","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"মনোয়েল দ্যা আসসুম্পসাঁও অভিধান প্রকাশের আগে কত বছর ধরে শব্দ সংগ্রহ করেন?","options":["২-৩ বছর","৫-৭ বছর","৯-১০ বছর","১৪-১৫ বছর"],"correctIndex":2,"subject":"বাংলা","explanation":"বাংলা অভিধানের সূচনা আঠারো শতকে, প্রথম দিকে যা ছিল প্রধানত দ্বিভাষিক। এ শ্রেণির প্রথম অভিধান 'Vocabulario em Idioma Bengalla e Portuguez' (সংক্ষেপে Vocabulario), যা পর্তুগিজ পাদ্রি মনোএল দা আসসুম্পসাঁউ ভাওয়ালের একটি গির্জায় ধর্মযাজকের দায়িত্ব পালনকালে খ্রিষ্টধর্ম প্রচারের সুবিধার্থে ১৭৩৪-৪২ খ্রিস্টাব্দের মধ্যে রচনা করেন এবং ১৭৪৩ সালে লিসবন থেকে রোমান হরফে মুদ্রিত হয়। এই অভিধান প্রকাশের আগে তিনি ৯-১০ বছর ধরে শব্দ সংগ্রহ করেন, মূলত পূর্ববঙ্গের ফরিদপুর জেলার লোকদের কথোপকথনের ভিত্তিতে। এটিই বাংলা ভাষার প্রথম ব্যাকরণ গ্রন্থও বটে, যার প্রথম অংশে বাংলা ব্যাকরণের সংক্ষিপ্তসার ও দ্বিতীয় অংশে বাংলা-পর্তুগিজ/পর্তুগিজ-বাংলা শব্দাভিধান রয়েছে; এতে রূপতত্ত্ব ও বাক্যতত্ত্ব আলোচিত হলেও ধ্বনিতত্ত্বের কোনো আলোচনা নেই।"},{"id":"bangla-44","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"গৌড়ী প্রাকৃত বলতে বোঝায়-","options":["গৌড় অঞ্চলের মুখের ভাষা","গৌড় সাহিত্যের স্বাভাবিক রীতি","গৌড় ভাষার লিখিত নমুনা","গৌড় ভাষার বিকৃত উচ্চারণ"],"correctIndex":0,"subject":"বাংলা","explanation":"গৌড়ী প্রাকৃত বলতে প্রাচীন ভারতের গৌড় অঞ্চলের মানুষের মুখের ভাষাকে বোঝায়। ড. মুহম্মদ শহীদুল্লাহর মতে খ্রিষ্টীয় সপ্তম শতকে গৌড়ীয় প্রাকৃত থেকে বাংলা ভাষার উদ্ভব হয়; তাঁর মতবাদ অনুযায়ী বাংলা ভাষার উৎপত্তির ধারা- প্রাকৃত > গৌড়ীয় প্রাকৃত > গৌড়ীয় অপভ্রংশ > বঙ্গকামরূপী > বাংলা। তুলনায়, মাগধী প্রাকৃত বলতে মগধ অঞ্চলের মুখের ভাষা বোঝায়; ড. সুনীতিকুমার চট্টোপাধ্যায়ের মতে খ্রিষ্টীয় দশম শতকে মাগধী প্রাকৃত থেকে বাংলা ভাষার উদ্ভব হয়।"},{"id":"bangla-45","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'Glossary' শব্দের বাংলা পরিভাষা-","options":["জ্ঞাপনপত্র","সর্বসাকল্যে","শব্দার্থপঞ্জি","গুদামজাত"],"correctIndex":2,"subject":"বাংলা","explanation":"'Glossary' শব্দের বাংলা পরিভাষা- শব্দপঞ্জি, শব্দার্থপঞ্জি, টীকাপুঞ্জ, টীকাগ্রন্থ বা শব্দকোষ। অপশন বিশ্লেষণ: Hand out-এর পরিভাষা জ্ঞাপনপত্র, In total-এর পরিভাষা সর্বসাকল্যে, আর Warehoused-এর পরিভাষা গুদামজাত।"},{"id":"bangla-46","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'ঐক্যমত' শব্দটি কোন বিবেচনায় অশুদ্ধ নয়?","options":["মতের ঐক্য - এভাবে সমাসসাধিত ধরলে","একমত + য - এভাবে প্রত্যয়সাধিত ধরলে","ঐক্য + মত - এভাবে উপসর্গসাধিত ধরলে","ঐক্যমত শব্দটিকে পারিভাষিক শব্দ ধরলে"],"correctIndex":0,"subject":"বাংলা","explanation":"'ঐক্যমত' শব্দটিকে 'মতের ঐক্য' অর্থে ৬ষ্ঠী তৎপুরুষ সমাসসাধিত ধরলে এটি অশুদ্ধ নয়। তবে প্রত্যয় দ্বারা গঠিত 'একমত+য' = 'ঐকমত্য' (অর্থ- একমত, মতের মিল) শব্দটিই বহুল প্রচলিত এবং প্রমিত/শুদ্ধ বানান হিসেবে স্বীকৃত।"},{"id":"bangla-47","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"১৯৩৬ সালে কলিকাতা বিশ্ববিদ্যালয়ের বানান সংস্কারের মূল উদ্দেশ্য ছিল-","options":["বানানকে উচ্চারণের কাছাকাছি নেওয়া","বানানের ঐতিহ্যকে বজায় রাখা","বানানের নিয়ম প্রণয়ন করা","বানানে বিকল্প বর্জন করা"],"correctIndex":2,"subject":"বাংলা","explanation":"বাংলা বানান প্রমিতকরণের প্রয়াস শুরু হয় উনিশ শতক থেকে। রবীন্দ্রনাথ ঠাকুরের উদ্যোগে ১৯৩৬ সালে কলকাতা বিশ্ববিদ্যালয় বানানের নিয়ম প্রণয়ন করলে বানানে অনেকটা শৃঙ্খলা ফিরে আসে। অর্থাৎ এই সংস্কারের মূল উদ্দেশ্য ছিল বানানের নিয়ম প্রণয়ন করা, যার একটি অংশ ছিল বানানে বিকল্প বর্জন করা।"},{"id":"bangla-48","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"অভিধানে ৎ, ঃ, ঁ, ং - এই বর্ণগুলোর অবস্থান কোথায়?","options":["স্বরবর্ণের আগে","স্বরবর্ণের শেষে","ব্যঞ্জনবর্ণের শেষে","এদের নির্দিষ্ট অবস্থান নেই"],"correctIndex":1,"subject":"বাংলা","explanation":"অভিধানে ব্যবহৃত বর্ণানুক্রম- অ আ ই ঈ উ ঊ ঋ এ ঐ ও ঔ, তারপর ং ঃ ঁ, তারপর ব্যঞ্জনবর্ণ (ক খ গ ঘ ঙ...ত(ৎ) থ দ ধ ন...ম য য় র ল শ ষ স হ)। অর্থাৎ ং, ঃ, ঁ- এই বর্ণগুলো স্বরবর্ণের শেষে (স্বরবর্ণের পরে ও ব্যঞ্জনবর্ণের আগে) বসে; আর 'ৎ' ব্যঞ্জনবর্ণের ক্রমে 'ত'-এর পরে নিজস্ব স্থানে বসে।"},{"id":"bangla-49","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"পূর্ববঙ্গীয় উচ্চারণে 'স্মরণ' শব্দের ক্ষেত্রে কোনটি ঘটে?","options":["স-এর উচ্চারণ শ হয়ে যায়","ণ-এর উচ্চারণ ন হয়ে যায়","ম-ফলার উচ্চারণ ম হয়ে যায়","শুরুতে নাসিক্য উচ্চারণ হয় না"],"correctIndex":0,"subject":"বাংলা","explanation":"পূর্ববঙ্গীয় (বাংলাদেশের) উচ্চারণরীতিতে প্রায়ই 'স'-এর উচ্চারণ 'শ' হয়ে যায়; যেমন- সাপ [শাপ্], স্মরণ [শঁরোন্], সাথী [শাথি]। অপশন বিশ্লেষণ: ন ও ণ ভিন্ন দুটি বর্ণ হলেও উচ্চারণ অভিন্ন, তাই 'স্মরণ' শব্দে ণ-এর উচ্চারণে বাড়তি কোনো পরিবর্তন ঘটে না (অপশন খ ভুল); ম-ফলা শব্দের শুরুতে উচ্চারিত হয় না বলে 'স্মরণ' শব্দে ম-ফলার উচ্চারণ 'ম' হয় না (অপশন গ ভুল); বরং শুরুতে ম উচ্চারিত না হয়ে নাসিক্য (ঁ) উচ্চারণ ঘটে (অপশন ঘ-ও ভুল)।"},{"id":"bangla-50","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'গড্ডালিকা প্রবাহ' বাগ্‌ধারার 'গড্ডল' শব্দের অর্থ কী?","options":["নদী","স্রোত","ভেড়া","মশা"],"correctIndex":2,"subject":"বাংলা","explanation":"গড্ডল/গড্ডর শব্দের অর্থ ভেড়া, মেষ, গাড়ল। গড্ডালিকা শব্দের অর্থ- অগ্রবর্তী ভেড়াকে অনুসরণকারী ভেড়ার পাল। 'গড্ডালিকা প্রবাহ' বাগ্‌ধারাটির অর্থ- বিচার-বিবেচনা না করে অন্যের অন্ধ অনুকরণ বা প্রচলিত ধারার অনুগামিতা।"},{"id":"bangla-51","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'বিরাট গরু-ছাগলের হাট'-ব্যানারে লেখা এই শিরোনামকে অপপ্রয়োগ বলা যায় না কেন?","options":["বিরাট শব্দটি হাটকে বিশেষিত করেছে","বিরাট শব্দটি গরু-ছাগলকে বিশেষিত করেছে","বিশেষণের অবস্থান যে-কোনো জায়গায় হতে পারে","বহুল ব্যবহারে প্রয়োগ-অশুদ্ধতা হারিয়েছে"],"correctIndex":0,"subject":"বাংলা","explanation":"'বিরাট' শব্দটি এখানে গরু-ছাগল সম্পর্কে নয়, বরং হাট সম্পর্কে তথ্য দিচ্ছে (প্রশ্ন: কেমন হাট? উত্তর: বিরাট হাট), তাই এটি অপপ্রয়োগ নয়। অনুরূপ উদাহরণ- 'খাঁটি সরিষার তেল' বাক্যাংশে 'খাঁটি' বিশেষণটি তেল সম্পর্কে তথ্য দেয় বলে এটিও সঠিক প্রয়োগ। অপশন বিশ্লেষণ: বিরাট শব্দটি গরু-ছাগলকে বিশেষিত করছে না, তাই অপশন (খ) ভুল; সাধারণত বিশেষণ বিশেষ্য/সর্বনামের পূর্বে বসলেও কখনো কখনো বাক্যের শুরুতে/মাঝে/শেষেও বসতে পারে, তবে অপশন (গ)-এ 'বিরাট' শব্দের উল্লেখই নেই বলে এটি সঠিক নয়; বহুল ব্যবহারে প্রয়োগ-অশুদ্ধতা হারানোর ধারণাটিও ভুল, কারণ বহুল ব্যবহৃত অশুদ্ধ শব্দ সাধারণত আধুনিক ব্যাকরণে ধীরে ধীরে শুদ্ধ করা হয়, এমনিতেই অশুদ্ধতা ঘুচে যায় না।"},{"id":"bangla-52","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'অজর' শব্দের বিপরীত কোনটি?","options":["অমলিন","বার্ধক্য","অমর","ব্যাধিগ্রস্ত"],"correctIndex":1,"subject":"বাংলা","explanation":"বাংলা একাডেমি আধুনিক বাংলা অভিধান অনুযায়ী 'অজর' শব্দের অর্থ জরারহিত/বার্ধক্যরহিত; এর বিপরীত শব্দ 'বার্ধক্য' (অর্থ- বৃদ্ধাবস্থা, বৃদ্ধ বয়স, জরা)। অপশন বিশ্লেষণ: অমলিন-এর বিপরীত মলিন; অমর-এর বিপরীত মরণশীল; ব্যাধিগ্রস্ত-এর বিপরীত নীরোগ/রোগমুক্ত।"},{"id":"bangla-53","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'ব্যাং' শব্দটি ং দিয়ে লিখতে হবে, কারণ-","options":["ঙ-এর হসন্ত উচ্চারণ ং হয়","য্‌ফলার পর ং হয়","ং বাংলা ভাষার নিজস্ব বর্ণ","ব্যাং একটি একাক্ষর শব্দ"],"correctIndex":0,"subject":"বাংলা","explanation":"ঙ-এর হসন্ত উচ্চারণ ং হয়, তাই 'ব্যাং' শব্দটি ং দিয়ে লিখতে হয়; 'ব্যাঙ্' এভাবে লেখা ভুল। অনুরূপভাবে 'রঙ্', 'ঢঙ্' লেখা ভুল, সঠিক হবে 'রং', 'ঢং'। তবে ং-এর পর স্বরচিহ্ন/কারচিহ্ন যুক্ত হলে সেখানে 'ঙ' বসে, যেমন- ব্যাঙাচি, রঙিন, ঢঙি।"},{"id":"bangla-54","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'সে কৌতুক করার কৌতূহল সংবরণ করতে পারল না।'-এই বাক্য কী কারণে ত্রুটিপূর্ণ?","options":["বানান ভুল আছে","বাক্যের পদবিন্যাস যথাযথ নয়","অর্থ অনুযায়ী শব্দের প্রয়োগ হয়নি","বিশেষ্য-বিশেষণের অপপ্রয়োগ ঘটেছে"],"correctIndex":2,"subject":"বাংলা","explanation":"কৌতুক শব্দের অর্থ আমোদ/মজা/পরিহাস, কৌতূহল শব্দের অর্থ অজ্ঞাত বিষয় জানার আগ্রহ (ঔৎসুক্য), আর সংবরণ শব্দের অর্থ নিবারণ/দমন। ফলে 'সে কৌতুক করার কৌতূহল সংবরণ করতে পারল না।' বাক্যটির অর্থ দাঁড়ায়- সে মজা করার অজ্ঞাত বিষয় জানার আগ্রহ দমন করতে পারল না, যা অর্থহীন শোনায়- কারণ এখানে অর্থ অনুযায়ী শব্দের যথাযথ প্রয়োগ হয়নি। সঠিক রূপ হবে- 'সে কৌতুক করার আগ্রহ/ইচ্ছা সংবরণ করতে পারল না।' অপশন বিশ্লেষণ: বাক্যটির সব বানান সঠিক (তাই ক ভুল); পদবিন্যাসও যথাযথ- কর্তা (সে), কর্ম (কৌতূহল), ক্রিয়া (পারল না) যথাক্রমে বসেছে (তাই খ ভুল); বিশেষ্য-বিশেষণের কোনো অপপ্রয়োগও ঘটেনি (তাই ঘ ভুল)।"},{"id":"bangla-55","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'নিত্য তোমার যে ফুল ফোটে ফুলবনে'-এখানে 'নিত্য' শব্দের প্রতিশব্দ কোনটি?","options":["অতিশয়","চিরন্তন","প্রকৃতি","অহরহ"],"correctIndex":3,"subject":"বাংলা","explanation":"বাংলা একাডেমি আধুনিক বাংলা অভিধান অনুযায়ী 'নিত্য' শব্দের প্রতিশব্দ- প্রত্যহ, অহরহ। উল্লেখ্য, 'নিত্য তোমার যে ফুল ফোটে ফুলবনে, তারি মধু কেন মনমধুপে খাওয়াও না?' পঙ্‌ক্তিটি রবীন্দ্রনাথ ঠাকুরের একটি গানের লাইন।"},{"id":"bangla-56","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"বাক্যের মধ্যে শব্দ অবস্থান করে কীভাবে?","options":["কর্তা ও ক্রিয়ার পদবিন্যাস অনুযায়ী","অর্থ ও ভাব অনুযায়ী","বর্গ বা গুচ্ছ আকারে","স্বাধীন পদের পরিচয় নিয়ে"],"correctIndex":1,"subject":"বাংলা","explanation":"একাধিক অর্থবোধক শব্দ পাশাপাশি বসে মনের ভাব প্রকাশ করলে তাকে বাক্য বলে; বাক্যের মধ্যে শব্দ মূলত অর্থ ও ভাব অনুযায়ী অবস্থান করে। যেমন 'পাখি আকাশে ওড়ে' সঠিক বাক্য, কারণ 'ওড়ে' ক্রিয়ার সাথে 'পাখি' শব্দের অর্থগত ও ভাবগত মিলবন্ধন আছে। অপশন বিশ্লেষণ: কর্তা-ক্রিয়ার পদবিন্যাস ঠিক থাকলেও অর্থ-ভাবের মিল না থাকলে বাক্য ভুল হতে পারে (যেমন- 'হাতি আকাশে ওড়ে'), তাই কেবল পদবিন্যাস নির্ধারক নয়; বাক্যে শব্দ সবসময় বর্গ/শব্দগুচ্ছ আকারে অবস্থান করে না (যেমন- 'বাবা বাড়ি আছে'-তে কোনো বর্গ নেই); আর প্রতিটি পদ স্বাধীন পদের পরিচয় নিয়ে বসলেও অর্থ-ভাবের সংগতি না থাকলে তা বাক্য গঠন করতে পারে না।"},{"id":"bangla-57","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"বাংলা একাডেমির 'আধুনিক বাংলা অভিধান'-এর সম্পাদক কে?","options":["আনিসুজ্জামান","আবু ইসহাক","মনসুর মুসা","জামিল চৌধুরি"],"correctIndex":3,"subject":"বাংলা","explanation":"'বাংলা একাডেমি আধুনিক বাংলা অভিধান'-এর সম্পাদক জামিল চৌধুরি। তুলনায়- 'আমার অভিধান'-এর সম্পাদক আনিসুজ্জামান; 'বাংলা একাডেমী সমকালীন বাংলা ভাষার অভিধান'-এর সম্পাদক আবু ইসহাক; 'বাংলায় প্রচলিত ইংরেজি শব্দের অভিধান'-এর সম্পাদক মনসুর মুসা ও মনোয়ার ইলিয়াস।"},{"id":"bangla-58","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'আলালের ঘরে দুলাল' প্রথমে কোন পত্রিকায় ধারাবাহিকভাবে প্রকাশিত হয়?","options":["বিবিধার্থ সংগ্রহ","সংবাদ প্রভাকর","মাসিক পত্রিকা","বঙ্গদর্শন"],"correctIndex":2,"subject":"বাংলা","explanation":"প্যারীচাঁদ মিত্র রচিত 'আলালের ঘরের দুলাল' (প্রকাশ ১৮৫৭, মতান্তরে ১৮৫৮) বাংলা সাহিত্যের প্রথম উপন্যাস; এটি প্রথমে 'মাসিক পত্রিকা'-য় ধারাবাহিকভাবে প্রকাশিত হয় (এই পত্রিকা ১৮৫৪ সালে প্যারীচাঁদ মিত্র ও রাধানাথ শিকদার যৌথভাবে প্রতিষ্ঠা ও সম্পাদনা করেন)। পরবর্তীতে হীরালাল মিত্র কর্তৃক এর নাট্যরূপ বেঙ্গল থিয়েটারে মঞ্চস্থ হয় (জানুয়ারি ১৮৭৫)। উপন্যাসটির মূল বিষয়বস্তু কলকাতার সমকালীন সমাজ ও উচ্চবিত্ত ঘরের আদুরে সন্তান মতিলালের উচ্ছৃঙ্খল জীবনাচার; চরিত্র- ঠকচাচা, মতিলাল, রামলাল, বাবুরাম, বাঞ্ছারাম। এই উপন্যাসে প্যারীচাঁদ মিত্র প্রথমবারের মতো যে কথ্য চলিত ভাষা ব্যবহার করেন, তা 'আলালী ভাষা' নামে পরিচিত।"},{"id":"bangla-59","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"কাজী নজরুল ইসলামের কোন গ্রন্থটি বাজেয়াপ্ত হয়নি?","options":["অগ্নিবীণা","বিষের বাঁশি","ভাঙার গান","চন্দ্রবিন্দু"],"correctIndex":0,"subject":"বাংলা","explanation":"কাজী নজরুল ইসলামের মোট ৫টি গ্রন্থ নিষিদ্ধ হয়- যুগবাণী (প্রথম নিষিদ্ধ গ্রন্থ/প্রবন্ধ সংকলন), বিষের বাঁশি (দ্বিতীয় নিষিদ্ধ গ্রন্থ/প্রথম নিষিদ্ধ কাব্যগ্রন্থ), ভাঙার গান, প্রলয় শিখা ও চন্দ্রবিন্দু। গ্রন্থ হিসেবে 'অগ্নি-বীণা' কাব্য কখনোই নিষিদ্ধ হয়নি, তবে এর অন্তর্গত 'রক্তাম্বরধারিণী মা' কবিতাটি একক কবিতা হিসেবে বাজেয়াপ্ত হয়। 'অগ্নি-বীণা' (১৯২২) নজরুলের প্রথম কাব্যগ্রন্থ, যাতে মোট ১২টি হিন্দু-মুসলিম ঐতিহ্যভিত্তিক কবিতা আছে; প্রথম কবিতা 'প্রলয়োল্লাস' এবং শেষ কবিতা 'মোহররম'।"},{"id":"bangla-60","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"জসীম উদ্‌দীনের 'কবর' কবিতাটি কোন কাব্যের অন্তর্গত?","options":["বালুচর","রাখালী","ধানক্ষেত","মা যে জননী কান্দে"],"correctIndex":1,"subject":"বাংলা","explanation":"জসীম উদ্‌দীনের প্রথম প্রকাশিত কাব্যগ্রন্থ 'রাখালী' (১৯২৭); এর অন্তর্গত তাঁর বিখ্যাত কবিতা 'কবর', যা প্রথম প্রকাশিত হয় 'কল্লোল' পত্রিকায় ১৩৩২ বঙ্গাব্দের শ্রাবণ সংখ্যায়। কবি দশম শ্রেণির ছাত্র থাকাকালে মাত্রাবৃত্ত ছন্দে এটি রচনা করেন; কবিতাটিতে ১১৮টি পঙ্‌ক্তি আছে এবং Dramatic Monologue রীতিতে একজন গ্রামীণ বৃদ্ধের একে একে প্রিয়জন হারানোর বেদনা ফুটে উঠেছে। রাখালী কাব্যের অন্যান্য কবিতা- পল্লীজননী, রাখাল ছেলে, বৈদেশী বন্ধু, তরুণ কিশোর, পাহাড়িয়া, কৃষাণ দুলালী।"},{"id":"bangla-61","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'সকলের তরে সকলে আমরা/ প্রত্যেকে আমরা পরের তরে।'- কোন কবিতার অংশ?","options":["পরার্থে","পাছে লোকে কিছু বলে","বড় কে","সুখ"],"correctIndex":3,"subject":"বাংলা","explanation":"প্রশ্নোক্ত চরণ দুটি কামিনী রায়ের 'সুখ' কবিতার অংশবিশেষ, যা তাঁর প্রথম কাব্যগ্রন্থ 'আলো ও ছায়া'-র অন্তর্গত (মাত্র ১৫ বছর বয়সে রচিত)। পুরাতন বোর্ড বইতে ভুলবশত এই চরণগুলো নিয়ে 'পরার্থে' নামে একটি পৃথক কবিতা সংযোজিত হয়েছিল, কিন্তু প্রকৃতপক্ষে কামিনী রায়ের 'পরার্থে' নামে কোনো কবিতা নেই; বর্তমান বোর্ড বইতে মূল কবিতার নাম অনুসারে 'সুখ' কবিতাই অন্তর্ভুক্ত রয়েছে। তাই অপশনে 'সুখ' ও 'পরার্থে' উভয়ই থাকলে সঠিক উত্তর হিসেবে 'সুখ' বেছে নিতে হয়।"},{"id":"bangla-62","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'এমন পিরিতি কভু নাহি দেখি শুনি।/ পরানে পরান বান্ধা আপনা আপনি॥'-কার লেখা?","options":["বিদ্যাপতি","চণ্ডীদাস","জ্ঞানদাস","গোবিন্দদাস"],"correctIndex":1,"subject":"বাংলা","explanation":"বৈষ্ণব কবি চণ্ডীদাসকে বাংলা সাহিত্যের প্রথম মানবতাবাদী কবি বলা হয়; উদ্ধৃত পঙ্‌ক্তিদ্বয় তাঁরই বিখ্যাত রচনা। তাঁর আরেকটি বিখ্যাত পঙ্‌ক্তি- 'সবার উপরে মানুষ সত্য তাহার উপরে নাই।' চণ্ডীদাসের জন্ম পশ্চিমবঙ্গের বীরভূম জেলার নান্নুর গ্রামে (মতান্তরে বাঁকুড়ার ছাতনায়); তিনি বৈষ্ণব পদাবলির বাংলা ভাষার আদি কবি/প্রথম বাঙালি কবি। রবীন্দ্রনাথ ঠাকুর তাঁকে 'দুঃখের কবি' এবং 'সহজ ভাষায় সহজ ভাবের কবি' বলে অভিহিত করেছেন। অপশন বিশ্লেষণ: বিদ্যাপতির বিখ্যাত পঙ্‌ক্তি 'এ সখি হামারি দুখের নাহি ওর'; জ্ঞানদাসের 'সুখের লাগিয়া এ ঘর বাঁধিনু অনলে পুড়িয়া গেল'; গোবিন্দদাসের 'নন্দ নন্দন চন্দ চন্দন গন্ধ নিন্দিত অঙ্গ'।"},{"id":"bangla-63","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"ফোর্ট উইলিয়াম কলেজ পর্বে রচিত বাংলা বইগুলো-","options":["সংস্কৃত বইয়ের অনুবাদ","ফরাসি বইয়ের অনুবাদ","ইংরেজি বইয়ের অনুবাদ","পণ্ডিতদের রচিত মৌলিক গ্রন্থ"],"correctIndex":0,"subject":"বাংলা","explanation":"ইস্ট ইন্ডিয়া কোম্পানির ব্রিটিশ কর্মকর্তাদের এদেশীয় ভাষা ও সংস্কৃতি শেখানোর উদ্দেশ্যে প্রতিষ্ঠিত ফোর্ট উইলিয়াম কলেজের অবদান বাংলা গদ্য সাহিত্য বিকাশে সবচেয়ে বেশি। এই পর্বে অল্প কিছু মৌলিক গ্রন্থ (যেমন উইলিয়াম কেরির 'কথোপকথন', রামরাম বসুর 'রাজা প্রতাপাদিত্য চরিত্র') রচিত হলেও অধিকাংশ বই ছিল সংস্কৃত গ্রন্থের অনুবাদ; যেমন মৃত্যুঞ্জয় বিদ্যালঙ্কারের বত্রিশ সিংহাসন (সংস্কৃত কথাসাহিত্যের অনুবাদ), রাজাবলি (সংস্কৃত ইতিহাসের অনুবাদ), হিতোপদেশ ও প্রবোধ চন্দ্রিকা (উভয়ই সংস্কৃত গ্রন্থের অনুবাদ); এছাড়া গোলকনাথ শর্মার হিতোপদেশ এবং হরপ্রসাদ রায়ের পুরুষপরীক্ষাও সংস্কৃত অনুবাদ।"},{"id":"bangla-64","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"সাহিত্যের রূপ ও রীতির বিচারে কোন গ্রন্থটি ব্যতিক্রম?","options":["বাংলা কাব্য","দিবারাত্রির কাব্য","শেষের কবিতা","নদী ও নারী"],"correctIndex":0,"subject":"বাংলা","explanation":"দিবারাত্রির কাব্য (মানিক বন্দ্যোপাধ্যায়), শেষের কবিতা (রবীন্দ্রনাথ ঠাকুর) ও নদী ও নারী (হুমায়ুন কবির)- এই তিনটিই মূলত উপন্যাস, যদিও নামে 'কাব্য'/কাব্যধর্মী শব্দ যুক্ত আছে। অন্যদিকে 'বাংলা কাব্য' নামে কোনো নির্দিষ্ট গ্রন্থ নেই- এটি বাংলা সাহিত্যের কবিতার সামগ্রিক রূপ/ধারাকে নির্দেশ করে, নির্দিষ্ট কোনো রচনার শিরোনাম নয়। সাহিত্যের রূপ ও রীতির বিচারে তাই 'বাংলা কাব্য' এই চারটির মধ্যে ব্যতিক্রম হিসেবে বিবেচিত হয়।"},{"id":"bangla-65","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"কোন্ মঙ্গলকাব্যে ঐতিহাসিক চরিত্র আছে?","options":["মনসামঙ্গল","চণ্ডীমঙ্গল","অন্নদামঙ্গল","ধর্মমঙ্গল"],"correctIndex":2,"subject":"বাংলা","explanation":"মঙ্গলকাব্য ধারার সর্বশেষ ও অষ্টাদশ শতাব্দীর শ্রেষ্ঠ কাব্য 'অন্নদামঙ্গল', রচয়িতা ভারতচন্দ্র রায় গুণাকর। কাব্যটি ৩ খণ্ডে বিভক্ত ও তিনটি স্বতন্ত্র কাহিনিতে পূর্ণ- প্রথম খণ্ডে শিবায়ন-অন্নদামঙ্গল (পৌরাণিক), দ্বিতীয় খণ্ডে বিদ্যাসুন্দর-কালিকামঙ্গল, তৃতীয় খণ্ডে মানসিংহ-ভবানন্দের কাহিনি, যা মূলত ঐতিহাসিক। মুঘল সম্রাট আকবরের সেনাপতি মানসিংহ কর্তৃক রাজা প্রতাপাদিত্যকে পরাজয় ও বন্দিকরণ এবং সম্রাট জাহাঙ্গীরের নিকট থেকে ভবানন্দের 'রাজা-ই-ফরমান' লাভের মতো ঐতিহাসিক ঘটনা এই তৃতীয় অংশে বর্ণিত হয়েছে, ফলে অন্নদামঙ্গল কাব্যে ঐতিহাসিক চরিত্র রয়েছে।"},{"id":"bangla-66","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"কোন্ কাব্যে আলাওল ব্যক্তিগত জীবনের কথা লিখেছেন?","options":["পদ্মাবতী","হপ্তপয়কর","সিকান্দরনামা","তোহফা"],"correctIndex":0,"subject":"বাংলা","explanation":"আরাকান রাজসভার শ্রেষ্ঠ কবি ও সপ্তদশ শতকের শ্রেষ্ঠ মুসলিম কবি আলাওল ১৬০৭ সালে ফতেহাবাদ পরগনা, ফরিদপুরে (মতান্তরে চট্টগ্রামের হাটহাজারীর জোবরা গ্রামে) জন্মগ্রহণ করেন। তাঁর মোট সাতটি কাব্যের মধ্যে প্রথম ও শ্রেষ্ঠ কাব্য 'পদ্মাবতী', যেখানে তিনি নিজের ব্যক্তিগত জীবনের কথা বিশেষভাবে তুলে ধরেছেন এবং পদ্মাবতীর রূপ বর্ণনায় কৃতিত্ব দেখিয়েছেন (নায়ক রত্নসেন, নায়িকা পদ্মাবতী, শুক পাখি হিরামন)। এছাড়া হপ্তপয়কর (ফারসি থেকে অনূদিত সাতটি গল্পের সংকলন, বাংলা নাম সপ্তপয়কর) ও সিকান্দরনামা (আলেকজান্ডারের দিগ্বিজয়ের কাহিনি) নিয়ামী গঞ্জাবীর কাব্যের অনুবাদ, আর তোহফা মূলত ধর্মীয় তত্ত্বোপদেশমূলক নীতিকাব্য।"},{"id":"bangla-67","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'তুরস্ক-ভ্রমণ' কার লেখা?","options":["ইসমাইল হোসেন সিরাজী","সৈয়দ মুজতবা আলী","আবু জাফর শামসুদ্দীন","শামসুদ্দীন আবুল কালাম"],"correctIndex":0,"subject":"বাংলা","explanation":"সৈয়দ ইসমাইল হোসেন সিরাজী রচিত ভ্রমণকাহিনি 'তুরস্ক-ভ্রমণ'-এর পটভূমি বলকান যুদ্ধ (১৯১২-১৯১৩); এই যুদ্ধকালে তিনি 'অল ইন্ডিয়া মেডিকেল মিশন'-এর বঙ্গীয় প্রতিনিধি হিসেবে তুরস্কে যান এবং তুর্কি স্বাস্থ্য অধিদপ্তরের ইন্সপেক্টরের দায়িত্ব পালন করেন; যুদ্ধ শেষে তুরস্ক সরকার তাঁকে 'গাজী এ বলকান' (১৯১৩) উপাধি দেয়। গ্রন্থে তিনি তৎকালীন তুরস্কের সমাজ-সংস্কৃতি ও ঐতিহাসিক প্রেক্ষাপট তুলে ধরেন। উপমহাদেশের প্রথম ব্রিটিশবিরোধী মুসলিম কবি হিসেবে পরিচিত সিরাজগঞ্জে জন্ম নেওয়া এই লেখক, বাগ্মী ও কৃষক নেতার জন্মস্থানের নামানুসারেই তাঁর নামের সাথে 'সিরাজী' উপাধি যুক্ত হয়।"},{"id":"bangla-68","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"সৈয়দ ওয়ালীউল্লাহর 'চাঁদের অমাবস্যা' উপন্যাসে কোন জীবনদর্শনের রূপায়ণ ঘটেছে?","options":["মার্কসবাদ","বাস্তববাদ","অস্তিত্ববাদ","পরাবাস্তববাদ"],"correctIndex":2,"subject":"বাংলা","explanation":"বাংলা ভাষায় মাত্র তিনটি উপন্যাস লিখে অসামান্য খ্যাতি অর্জনকারী সৈয়দ ওয়ালীউল্লাহর দ্বিতীয় উপন্যাস 'চাঁদের অমাবস্যা' (ষাটের দশকে ঢাকা থেকে প্রকাশিত) একটি মনস্তাত্ত্বিক উপন্যাস, যেখানে অস্তিত্ববাদের চিত্র দারুণভাবে উপস্থাপিত হয়েছে। উপন্যাসের কেন্দ্রীয় চরিত্র আরেফ আলী, একটি মাধ্যমিক স্কুলের শিক্ষক, যিনি প্রভাবশালী প্রতিষ্ঠাতা পরিবারের ছেলে কাদেরের ধর্ষণ ও হত্যাকাণ্ডের প্রত্যক্ষদর্শী হওয়ার পর মনস্তাত্ত্বিক দ্বন্দ্বে ভোগেন। সৈয়দ ওয়ালীউল্লাহর 'চাঁদের অমাবস্যা' ও 'কাঁদো নদী কাঁদো'- এই দুই ব্যতিক্রমধর্মী উপন্যাসে যথাক্রমে অস্তিত্ববাদ ও চেতনাপ্রবাহরীতির অসাধারণ রূপক প্রকাশ পেয়েছে।"},{"id":"bangla-69","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'প্রভাতফেরির মিছিল যাবে/ ছড়াও ফুলের বন্যা,/ বিষাদগীতি গাইছে পথে/ তিতুমীরের কন্যা।'-কার লেখা?","options":["শামসুর রাহমান","আল মাহমুদ","আহসান হাবীব","আবদুল গাফ্‌ফার চৌধুরী"],"correctIndex":1,"subject":"বাংলা","explanation":"প্রশ্নোল্লিখিত চরণগুলো কবি আল মাহমুদের 'একুশের কবিতা' থেকে উদ্ধৃত, যেখানে ভাষা আন্দোলনের শহিদদের প্রতি শ্রদ্ধা নিবেদন এবং তাঁদের আত্মত্যাগের মহিমা তুলে ধরা হয়েছে। কবিতায় ভাষাশহিদ বরকত ও ক্ষুদিরামের আত্মত্যাগের প্রসঙ্গও উঠে আসে।"},{"id":"bangla-70","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'হরফের ছড়া' কার লেখা বর্ণশিক্ষার বই?","options":["ঈশ্বরচন্দ্র বিদ্যাসাগর","রবীন্দ্রনাথ ঠাকুর","ফররুখ আহমদ","বন্দে আলী মিয়া"],"correctIndex":2,"subject":"বাংলা","explanation":"মুসলিম রেনেসাঁর কবি, ইসলামি স্বাতন্ত্র্যবাদী কবি ও মুসলিম পুনর্জাগরণের কবি নামে পরিচিত ফররুখ আহমদ রচিত বর্ণশিক্ষার বই 'হরফের ছড়া', যা শিশুদের ছড়ার মাধ্যমে বাংলা বর্ণমালা শেখানোর উদ্দেশ্যে লেখা। তাঁর অন্যান্য শিশুতোষ গ্রন্থ- পাখির বাসা (তাঁর প্রথম প্রকাশিত শিশুতোষ গ্রন্থ, যার জন্য ইউনেস্কো পুরস্কার লাভ করেন), নতুন লেখা, ছড়ার আসর, চাঁদের আসর, চিড়িয়াখানা, ফুলের জলসা। অপশন বিশ্লেষণ: ঈশ্বরচন্দ্র বিদ্যাসাগর রচিত শিশুদের বাংলা বর্ণমালার প্রথম সার্থক গ্রন্থ 'বর্ণপরিচয়'; রবীন্দ্রনাথ ঠাকুরের শিশুসাহিত্য 'সহজ পাঠ'; বন্দে আলী মিয়ার শিশুসাহিত্য- চোর জামাই, মেঘ কুমারী, সোনার হরিণ, শেয়াল পণ্ডিতের পাঠশালা প্রভৃতি।"},{"id":"bangla-71","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'রক্তকরবী' নাটকের অন্তর্গত বিষয় কী?","options":["নতুনের জয়গান গাওয়া","সামন্তবাদের বিলুপ্তি দেখানো","শ্রমিকদের অপ্রাপ্তি তুলে ধরা","পুঁজিবাদের নেতিবাচক প্রভাব দেখানো"],"correctIndex":3,"subject":"বাংলা","explanation":"রবীন্দ্রনাথ ঠাকুরের সাংকেতিক নাটক 'রক্তকরবী' ১৯২৩ সালে (বাংলা ১৩৩০ সন) শিলং-এর শৈলবাসে রচিত হয়, তখন এর নাম ছিল 'যক্ষপুরী'। ১৯২৪ সালে (১৩৩১ সনের আশ্বিন মাসে) 'প্রবাসী'-তে প্রকাশের সময় নাম হয় 'রক্তকরবী'। নাটকের মূল প্রতিপাদ্য পুঁজিবাদী শোষণের নেতিবাচক প্রভাব- কীভাবে আধুনিক যন্ত্রসভ্যতা মানুষকে কেবল উৎপাদনের হাতিয়ারে পরিণত করে এবং মানবিক সম্পর্ক ও আবেগ ধ্বংস করে দেয়, তা এতে দেখানো হয়েছে। উল্লেখযোগ্য চরিত্র- কিশোর, রঞ্জন, নন্দিনী।"},{"id":"bangla-72","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"মীর মশাররফ হোসেন সম্পর্কে কোন তথ্যটি যথার্থ নয়?","options":["তিন খণ্ডে 'বিষাদ-সিন্ধু' রচনা করেন","নিজের জীবনী রচনা করেন","জমিদারি দেখাশোনার কাজ করেছেন","বিবি কুলসুম তাঁর প্রথম স্ত্রী"],"correctIndex":3,"subject":"বাংলা","explanation":"মীর মশাররফ হোসেন আধুনিক বাংলা মুসলমান সাহিত্যিকদের পথিকৃৎ, প্রথম বাঙালি মুসলিম নাট্যকার ও প্রথম মুসলিম ঔপন্যাসিক। তিনি তিন খণ্ডে (মহরম পর্ব, উদ্ধার পর্ব, এজিদবধ পর্ব) 'বিষাদ-সিন্ধু' রচনা করেন, যা কারবালার বিষাদময় ঘটনা অবলম্বনে রচিত বাংলা সাহিত্যের একমাত্র গদ্য মহাকাব্য। তিনি নিজের জীবনীও রচনা করেন (উদাসীন পথিকের মনের কথা, গাজী মিয়াঁর বস্তানী) এবং কর্মজীবন শুরু করেন পিতার পদমদী এস্টেট (রাজবাড়ী) জমিদারি দেখাশোনার মাধ্যমে, পরে ফরিদপুর নবাব এস্টেটে এবং ১৮৮৫ সালে দেলদুয়ার এস্টেটের ম্যানেজার নিযুক্ত হন। তবে 'বিবি কুলসুম তাঁর প্রথম স্ত্রী' তথ্যটি যথার্থ নয়- তাঁর প্রথম স্ত্রীর নাম নওয়াবুন নেছা, দ্বিতীয় স্ত্রীর নাম বিবি কুলসুম; 'বিবি কুলসুম' তাঁর সর্বশেষ ও জীবনীমূলক রচনাগুলোর মধ্যে শ্রেষ্ঠত্বের দাবিদার গ্রন্থও বটে।"},{"id":"bangla-73","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"জীবনানন্দ দাশের মৃত্যুর পর কোন কাব্যগ্রন্থটি প্রকাশিত হয়?","options":["ঝরাপালক","রূপসী বাংলা","বনলতা সেন","সাতটি তারার তিমির"],"correctIndex":1,"subject":"বাংলা","explanation":"ত্রিশ দশকের কবি ও পঞ্চপাণ্ডবদের একজন জীবনানন্দ দাশ (১৮৯৯-১৯৫৪)-এর জীবিতাবস্থায় প্রকাশিত কাব্যগ্রন্থ যথাক্রমে- ঝরাপালক (১৯২৭, প্রথম), ধূসর পাণ্ডুলিপি (১৯৩৬), বনলতা সেন (১৯৪২), মহাপৃথিবী (১৯৪৪), এবং সাতটি তারার তিমির (১৯৪৮, জীবদ্দশায় প্রকাশিত সর্বশেষ কাব্য)। তাঁর মৃত্যুর পর প্রকাশিত কাব্যগ্রন্থ- রূপসী বাংলা (১৯৫৭) ও বেলা অবেলা কালবেলা (১৯৬১); তাঁর প্রথম প্রবন্ধগ্রন্থ 'কবিতার কথা'-ও মৃত্যুর পর ১৯৫৫ সালে প্রকাশিত হয়।"},{"id":"bangla-74","exam":"৪৭তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'তুমি অধম তাই বলিয়া আমি উত্তম না হইব কেন?'- কোন উপন্যাসে আছে?","options":["বঙ্কিমচন্দ্রের 'কপালকুণ্ডলা'","রবীন্দ্রনাথের 'গোরা'","শরৎচন্দ্রের 'চরিত্রহীন'","বিভূতিভূষণের 'আরণ্যক'"],"correctIndex":0,"subject":"বাংলা","explanation":"বঙ্কিমচন্দ্র চট্টোপাধ্যায়ের 'কপালকুণ্ডলা' (১৮৬৬) বাংলা সাহিত্যের প্রথম রোমান্টিক উপন্যাস। এই উপন্যাসের বিখ্যাত উক্তিগুলোর একটি- 'তুমি অধম তাই বলিয়া আমি উত্তম না হইব কেন?' অন্য দুটি বিখ্যাত উক্তি- 'প্রদীপ নিবিয়া গেল' এবং 'পথিক তুমি পথ হারাইয়াছ?' (যা বাংলা সাহিত্যের প্রথম রোমান্টিক সংলাপ হিসেবে পরিচিত)। উপন্যাসের চরিত্রসমূহ- কপালকুণ্ডলা, নবকুমার, মতিবিবি (লুৎফুন্নিসা)।"},{"id":"bangla-75","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"বাংলা ভাষায় কোন স্বরধ্বনি উচ্চারণকালে জিহ্বা উচ্চ অবস্থানে থাকে?","options":["আ","এ","উ","ও"],"correctIndex":2,"subject":"বাংলা","explanation":"বাংলা মৌলিক স্বরধ্বনি ৭টি- অ, আ, ই, উ, এ, ও, অ্যা। জিহ্বার উচ্চতা অনুযায়ী এদের ভাগ করা হয়- উচ্চ স্বরধ্বনি (ই, উ), উচ্চ-মধ্য স্বরধ্বনি (এ, ও), নিম্ন-মধ্য স্বরধ্বনি (অ্যা, অ) ও নিম্ন স্বরধ্বনি (আ)। প্রদত্ত অপশনগুলোর মধ্যে 'উ' উচ্চ স্বরধ্বনি, অর্থাৎ এটি উচ্চারণকালে জিহ্বা সবচেয়ে উঁচু অবস্থানে থাকে। অন্যদিকে 'আ' নিম্ন, আর 'এ', 'ও' উচ্চ-মধ্য স্বরধ্বনি।"},{"id":"bangla-76","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"বাংলা শব্দ ভাণ্ডারে অনার্য জাতির ব্যবহৃত শব্দ-","options":["তৎসম","তদ্ভব","দেশি","বিদেশি"],"correctIndex":2,"subject":"বাংলা","explanation":"বাংলা শব্দভাণ্ডারে অনার্য জাতির ব্যবহৃত শব্দকে দেশি শব্দ বলে; বাংলাদেশের আদিম অধিবাসীদের (কোল, মুণ্ড প্রভৃতি) ভাষা-সংস্কৃতির শব্দগুলো এই শ্রেণিতে পড়ে, যেমন- কুড়ি, পেট, চুলা, টোপর, ডাব, কালা, ঝাঁটা, ঝিনুক, কয়লা, জারুল, চাউল, কাতলা। অপশন বিশ্লেষণ: তৎসম শব্দ সংস্কৃত থেকে সরাসরি অপরিবর্তিতভাবে বাংলায় এসেছে (চন্দ্র, সূর্য, ধর্ম, মনুষ্য); তদ্ভব শব্দের মূল সংস্কৃতে থাকলেও প্রাকৃতের মাধ্যমে বিবর্তিত হয়ে বাংলায় এসেছে (চাঁদ, মুখ, হাত, ভাত); বিদেশি শব্দ রাজনৈতিক-ধর্মীয়-বাণিজ্যিক কারণে আগত ভাষা (আরবি, ফারসি, ইংরেজি, পর্তুগিজ) থেকে এসেছে। উল্লেখ্য, তৎসম ও তদ্ভব উভয়ই পারিভাষিক শব্দ; তৎসম শব্দের অপর নাম সংস্কৃত শব্দ, তদ্ভব শব্দের অপর নাম খাঁটি বাংলা শব্দ।"},{"id":"bangla-77","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'ধ্বনিবিজ্ঞান ও বাংলা ধ্বনিতত্ত্ব' গ্রন্থের রচয়িতা-","options":["মুহম্মদ আবদুল হাই","মুহম্মদ শহীদুল্লাহ","মুনীর চৌধুরী","মুহম্মদ এনামুল হক"],"correctIndex":0,"subject":"বাংলা","explanation":"'ধ্বনিবিজ্ঞান ও বাংলা ধ্বনিতত্ত্ব' (১৯৬৪) গ্রন্থের রচয়িতা মুহম্মদ আবদুল হাই; বাংলা ভাষার ধ্বনির গঠন, উচ্চারণ ও ব্যবহারবিধির বৈজ্ঞানিক ব্যাখ্যা-বিশ্লেষণে রচিত এই গ্রন্থ তাঁকে আন্তর্জাতিক খ্যাতি এনে দেয়; ভাষাতত্ত্বের মৌলিক বিষয়ে এমন উচ্চমানের গবেষণাগ্রন্থ দুই বাংলায় তিনিই প্রথম রচনা করেন। তাঁর অন্যান্য গ্রন্থ- সাহিত্য ও সংস্কৃতি, তোষামোদ ও রাজনীতির ভাষা, ভাষা ও সাহিত্য, বিলেতে সাড়ে সাতশ দিন। অপশন বিশ্লেষণ: মুহম্মদ শহীদুল্লাহর গ্রন্থ- বাঙালা ভাষার ইতিবৃত্ত, বাঙালা ব্যাকরণ; মুনীর চৌধুরীর- বাংলা ভাষার ব্যাকরণ; মুহম্মদ এনামুল হকের- ব্যাকরণ মঞ্জুরী।"},{"id":"bangla-78","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"বাংলা বর্ণমালায় যৌগিক স্বর কয়টি?","options":["১টি","২টি","৩টি","৪টি"],"correctIndex":1,"subject":"বাংলা","explanation":"পাশাপাশি দুটি মৌলিক স্বরধ্বনি দ্রুত উচ্চারিত হয়ে একটি যুক্ত স্বরধ্বনিতে রূপ নিলে তাকে যৌগিক স্বরধ্বনি বলে; যেমন- অ+ই=অই (বই, খই), আ+ই=আই (ভাই, যাই), আ+ও=আও (যাও, খাওয়া), অ+উ=অউ (বউ, মউ), আ+উ=আউ (লাউ, চাউল), ই+উ=ইউ (শিউলি)। বাংলা ভাষায় মোট যৌগিক স্বরধ্বনি ২৫টি হলেও বাংলা বর্ণমালায় যৌগিক স্বরজ্ঞাপক বর্ণ মাত্র ২টি- ঐ ও ঔ। যৌগিক স্বরের অপর নাম- দ্বিস্বর, দ্বৈতস্বর, যুগ্মস্বর, সন্ধিস্বর, মিশ্রস্বর।"},{"id":"bangla-79","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"যোগরূঢ় শব্দ কোনটি?","options":["কলম","মলম","বাঁশি","শাখামৃগ"],"correctIndex":3,"subject":"বাংলা","explanation":"সমাসনিষ্পন্ন যেসব শব্দ সম্পূর্ণভাবে সমস্যমান পদগুলোর অনুগামী না হয়ে কোনো বিশিষ্ট অর্থ গ্রহণ করে, তাদের যোগরূঢ় শব্দ বলে। যেমন- শাখামৃগ = শাখার ন্যায় মৃগ (শাখা অর্থ গাছের ডাল, মৃগ অর্থ হরিণ), কিন্তু এই সমাসবদ্ধ শব্দটি দ্বারা 'গাছের হরিণ' না বুঝিয়ে 'বানর' বোঝায়। অন্যান্য যোগরূঢ় শব্দ- রাজপুত, জলধি, পঙ্কজ, সরোজ, তুরঙ্গম, আদিত্য, সুহৃদ, পীতাম্বর, মহাযাত্রা। অপশন বিশ্লেষণ: কলম ও মলম আরবি শব্দ; বাঁশি একটি রূঢ়ি শব্দ।"},{"id":"bangla-80","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"উপসর্গযুক্ত শব্দ-","options":["বিদ্যা","বিদ্রোহী","বিষয়","বিপুল"],"correctIndex":1,"subject":"বাংলা","explanation":"'বিদ্রোহী' (বি + √দ্রহ্‌ + ইন) শব্দটি 'বি' উপসর্গযুক্ত শব্দের প্রচলিত ও স্বীকৃত দৃষ্টান্ত, তাই এটিই সরকারি উত্তরমালায় নির্ধারিত সঠিক উত্তর। অপশন বিশ্লেষণ: 'বিদ্যা' (√বিদ্‌ + য + আ) শব্দটি উপসর্গ সাধিত নয়, বরং প্রত্যয় সাধিত শব্দ। যদিও ধ্বনিতাত্ত্বিক বিশ্লেষণে বিষয় (বি+√সি+অ) ও বিপুল (বি+√পুল্‌+অ) শব্দেও কাঠামোগতভাবে 'বি' উপাদান খুঁজে পাওয়া যায়, প্রচলিত ব্যাকরণ চর্চায় ও প্রশ্নের সরকারি উত্তরমালায় একমাত্র 'বিদ্রোহী' শব্দটিকেই উপসর্গযুক্ত শব্দ হিসেবে গ্রহণ করা হয়েছে।"},{"id":"bangla-81","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"বিভক্তিযুক্ত শব্দ কোনটি?","options":["সরোবরে","চশমা","সরোজ","চম্পক"],"correctIndex":0,"subject":"বাংলা","explanation":"বাক্যস্থিত একটি শব্দের সঙ্গে অন্য শব্দের অন্বয় সাধনের জন্য যেসব বর্ণ যুক্ত হয়, তাদের বিভক্তি বলে। যেমন- 'সরোবরে পদ্ম ফোটে' বাক্যে 'সরোবরে' (সরোবর + এ) শব্দে মূল শব্দ 'সরোবর'-এর সাথে '৭মী বিভক্তি' 'এ' যুক্ত হয়েছে। শব্দবিভক্তি মোট ৭ প্রকার (১মা- শূন্য/অ; ২য়া- কে,রে; ৩য়া- দ্বারা,দিয়ে,কর্তৃক; ৪র্থী- কে,রে,জন্য; ৫মী- হতে,থেকে,চেয়ে; ৬ষ্ঠী- র,এর; ৭মী- এ,য়,তে)। উল্লেখ্য, ১মা/শূন্য বিভক্তির শব্দকে সাধারণত বিভক্তিযুক্ত শব্দ হিসেবে গণ্য করা হয় না, তাই চশমা, সরোজ, চম্পক (শূন্য বিভক্তিযুক্ত) বিভক্তিযুক্ত শব্দ নয়।"},{"id":"bangla-82","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"কোনটি প্রত্যয়-সাধিত শব্দ?","options":["ভাইবোন","রাজপথ","বকলম","ঐকিক"],"correctIndex":3,"subject":"বাংলা","explanation":"'ঐকিক' (এক + ইক) শব্দটি 'ইক' (তদ্ধিত) প্রত্যয়যোগে গঠিত। অপশন বিশ্লেষণ: ভাইবোন (ভাই ও বোন) ও রাজপথ (পথের রাজা) উভয়ই সমাসসাধিত শব্দ; বকলম (ব + কলম, ফারসি) উপসর্গ সাধিত শব্দ।"},{"id":"bangla-83","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'শিরশ্ছেদ' শব্দের সন্ধিবিচ্ছেদ-","options":["শির + ছেদ","শিরঃ + ছেদ","শিরশ্ + ছেদ","শির + উচ্ছেদ"],"correctIndex":1,"subject":"বাংলা","explanation":"'শিরশ্ছেদ' শব্দের সঠিক সন্ধিবিচ্ছেদ 'শিরঃ + ছেদ'; এটি বিসর্গ সন্ধিজাত শব্দ। নিয়ম হলো- র/রেফ এবং শ/ষ/স-এর পরিবর্তে বিসর্গ (ঃ) হয়। যেমন- অন্তর্ধান = অন্তঃ + ধান (রেফের পরিবর্তে বিসর্গ), দুরবস্থা = দুঃ + অবস্থা (র-এর পরিবর্তে বিসর্গ), নিশ্চয় = নিঃ + চয় (শ-এর পরিবর্তে বিসর্গ), চতুষ্পদ = চতুঃ + পদ (ষ-এর পরিবর্তে বিসর্গ), নমস্কার = নমঃ + কার (স-এর পরিবর্তে বিসর্গ)।"},{"id":"bangla-84","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'নীলকর' কোন সমাসের দৃষ্টান্ত?","options":["দ্বন্দ্ব","বহুব্রীহি","নিত্য","উপপদ তৎপুরুষ"],"correctIndex":3,"subject":"বাংলা","explanation":"উপপদের সাথে কৃদন্ত পদের সমাসকে উপপদ তৎপুরুষ সমাস বলে; এর ব্যাসবাক্যে ক্রিয়ার পর 'যে' (ব্যক্তিবাচক সমস্তপদে) বা 'যা' (বস্তুবাচক সমস্তপদে) বসে। যেমন- নীলকর = নীল চাষ/উৎপাদন করে যে; অনুরূপ উদাহরণ- জাদুকর (জাদু করে যে), পকেটমার (পকেট মারে যে), জলধি (জল ধারণ করে যা), পঙ্কজ (পঙ্কে জন্মে যা), জলদ (জল দেয় যা)।"},{"id":"bangla-85","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'Pedagogy' শব্দের পরিভাষা-","options":["সহশিক্ষা","নারীশিক্ষা","শিক্ষাতত্ত্ব","শিক্ষানীতি"],"correctIndex":2,"subject":"বাংলা","explanation":"Pedagogy শব্দের বাংলা পরিভাষা শিক্ষণবিজ্ঞান, যা প্রদত্ত অপশনগুলোর মধ্যে 'শিক্ষাতত্ত্ব'-এর সাথে সবচেয়ে সামঞ্জস্যপূর্ণ। অপশন বিশ্লেষণ: সহশিক্ষা- Co-education; নারীশিক্ষা- Female Education; শিক্ষানীতি- Education Policy।"},{"id":"bangla-86","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'বক্রিম' এর বিপরীত শব্দ কোনটি?","options":["বদ্দুর","অসম","সুষম","ঋজু"],"correctIndex":3,"subject":"বাংলা","explanation":"'বক্রিম' শব্দের অর্থ বাঁকা, যার বিপরীত শব্দ 'ঋজু' (সরল, সোজা)। অপশন বিশ্লেষণ: বদ্দুর-এর বিপরীত শব্দ মসৃণ; অসম-এর বিপরীত শব্দ সুষম (অর্থাৎ সুষম নিজেই অসম-এর বিপরীত, তাই এটি প্রশ্নের সঠিক উত্তর নয়)।"},{"id":"bangla-87","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"বাংলা একাডেমির 'প্রমিত বাংলা বানানের নিয়ম' কত সালে প্রণীত হয়?","options":["১৯৯০","১৯৯২","১৯৯৪","১৯৯৬"],"correctIndex":1,"subject":"বাংলা","explanation":"বাংলা বানান প্রমিতকরণের প্রয়াস শুরু হয় উনিশ শতক থেকে। রবীন্দ্রনাথ ঠাকুরের উদ্যোগে ১৯৩৬ সালে কলকাতা বিশ্ববিদ্যালয় বানানের নিয়ম প্রণয়ন করে বানানে অনেকটা শৃঙ্খলা আনে; বাংলাদেশে পাঠ্যপুস্তকে বানানের সমতাবিধানের জন্য ১৯৮৮ সালে জাতীয় শিক্ষাক্রম ও পাঠ্যপুস্তক বোর্ড (NCTB) বানানের নিয়ম প্রণয়ন করে। আর ১৯৯২ সালে বাংলা একাডেমি 'প্রমিত বাংলা বানানের নিয়ম' প্রণয়ন করে সব প্রতিষ্ঠানকে তা অনুসরণের আহ্বান জানায়।"},{"id":"bangla-88","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"কোন বানানটি শুদ্ধ?","options":["মুলো","মুলা","ধুলি","ধূলো"],"correctIndex":1,"subject":"বাংলা","explanation":"বাংলা একাডেমি আধুনিক বাংলা অভিধান অনুযায়ী 'মুলা' ও 'মুলো' উভয়ই প্রচলিত বানান হলেও, বিপিএসসির প্রকাশিত সরকারি উত্তরমালায় এই প্রশ্নের নির্ধারিত একক সঠিক উত্তর 'মুলা'। বাংলায় এমন দুই বানানই সঠিক এমন কিছু উদাহরণ আছে (যেমন- ধূলি/ধুলা(ধুলো), অনুবাদ/অনূদিত, কটু/কটূক্তি, মরু/মরূদ্যান, কৌতুক/কৌতূহল, পূজা/পুজো), তবে সেসব ক্ষেত্রে সাধারণত দুটি শব্দই ভিন্ন প্রসঙ্গে বা রূপভেদে ব্যবহৃত হয়; এই নির্দিষ্ট প্রশ্নে অভিধানসম্মত প্রমিত রূপ হিসেবে 'মুলা'-কেই গ্রহণ করা হয়েছে।"},{"id":"bangla-89","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'নদী'-র সমার্থক শব্দ কোনটি?","options":["সিন্ধু","হিল্লোল","তটিনী","নির্ঝর"],"correctIndex":2,"subject":"বাংলা","explanation":"নদীর সমার্থক শব্দ- তটিনী, তরঙ্গিনী, প্রবাহিনী, স্রোতস্বিনী, শৈবলিনী, মন্দাকিনী, নির্ঝরিণী, কল্লোলিনী, সরিৎ, অপগা, দরিয়া, কূলবতী। অপশন বিশ্লেষণ: সিন্ধু অর্থ সাগর; হিল্লোল অর্থ ঢেউ; নির্ঝর অর্থ ঝরনা।"},{"id":"bangla-90","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"চর্যাপদের কবিরা ছিলেন-","options":["মহাযানি বৌদ্ধ","বজ্রযানি বৌদ্ধ","বাউল","সহজযানি বৌদ্ধ"],"correctIndex":3,"subject":"বাংলা","explanation":"বাংলা ভাষা ও সাহিত্যের আদি নিদর্শন চর্যাপদের রচয়িতা বৌদ্ধ সহজিয়া সাধকগণ; 'সহজিয়া' একটি বিশেষ সম্প্রদায় যারা সহজপথে সাধনা করে এবং সকলেই বৌদ্ধধর্মের অনুসারী ছিলেন। এই বৌদ্ধ সহজিয়া মতবাদ 'সহজযান' নামে পরিচিত, আর এর অনুসারীরা সহজযানি বৌদ্ধ। চর্যাপদ রচনার উদ্দেশ্য ছিল ধর্মচর্চা; চর্যাকারদের বলা হয় মহাসিদ্ধ, আর 'পা' পদকর্তাদের সম্মানসূচক উপাধি। অপশন বিশ্লেষণ: মহাযান বৌদ্ধধর্মের একটি মূলধারা- বুদ্ধ নির্দেশিত নির্বাণে পৌঁছানোর মহৎ উপায়, এর অনুসারী মহাযানি; বজ্রযান বৌদ্ধধর্মের আরেকটি মতবাদ- বজ্রকে আশ্রয় করে নির্বাণ লাভের পথ, অনুসারী বজ্রযানি; বাউল লোকসম্প্রদায়ের একটি দেহভিত্তিক গুপ্ত সাধন-ভজন গোষ্ঠী, যেখানে সহজিয়া ও সুফি সাধনার সমিলন ঘটলেও সুফি প্রভাবই বেশি।"},{"id":"bangla-91","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'শূন্যপুরাণের' রচয়িতা-","options":["রামাই পণ্ডিত","হলায়ুধ মিশ্র","কাহ্নপা","কুক্কুরীপা"],"correctIndex":0,"subject":"বাংলা","explanation":"বাংলা সাহিত্যের অন্ধকার যুগের অন্যতম নিদর্শন 'শূন্যপুরাণ' কাব্যের রচয়িতা রামাই পণ্ডিত। সংস্কৃত ভাষায় রচিত ধর্মপূজার এই শাস্ত্রগ্রন্থে ৫১টি অধ্যায় আছে; গদ্য-পদ্য মিশ্রিত এই চম্পুকাব্যটি তেরো শতকে রচিত বলে অনুমিত হয়, যেখানে বৌদ্ধদের শূন্যবাদ ও হিন্দুদের লৌকিক ধর্মের মিশ্রণ ঘটেছে। 'নিরঞ্জনের উষ্মা' এর অন্তর্গত একটি বিখ্যাত কবিতা। অপশন বিশ্লেষণ: হলায়ুধ মিশ্র অন্ধকার যুগের আরেক নিদর্শন 'সেক শুভোদয়া' কাব্যের রচয়িতা; কাহ্নপা চর্যাপদের সর্বাধিক (১৩টি) পদ রচয়িতা ও শ্রেষ্ঠ কবি; কুক্কুরীপা চর্যাপদের একমাত্র নারী পদকর্তা (রচিত পদ ৩টি, প্রাপ্ত ২টি)।"},{"id":"bangla-92","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"বাংলা সাহিত্যের ইতিহাসে কাঁকিল্যা গ্রাম কেন উল্লেখযোগ্য?","options":["শ্রীচৈতন্যদেবের জন্মস্থান","বড়ু চণ্ডীদাসের জন্মস্থান","চর্যাপদের প্রাপ্তিস্থান","শ্রীকৃষ্ণকীর্তন কাব্যের প্রাপ্তিস্থান"],"correctIndex":3,"subject":"বাংলা","explanation":"মধ্যযুগের বাংলা সাহিত্যের আদি নিদর্শন 'শ্রীকৃষ্ণকীর্তন' কাব্য (সম্পূর্ণ বাংলা ভাষায় রচিত প্রথম গ্রন্থ, রচয়িতা বড়ু চণ্ডীদাস) শ্রী বসন্তরঞ্জন রায় বিদ্বদ্বল্লভ ১৯০৯ খ্রিস্টাব্দে বাঁকুড়া জেলার বনবিষ্ণুপুরের কাঁকিল্যা গ্রামের এক গৃহস্থের গোয়ালঘর থেকে আবিষ্কার করেন, তাই কাঁকিল্যা গ্রাম শ্রীকৃষ্ণকীর্তন কাব্যের প্রাপ্তিস্থান হিসেবে উল্লেখযোগ্য। অপশন বিশ্লেষণ: শ্রীচৈতন্যদেবের জন্মস্থান নদীয়া জেলার নবদ্বীপ শহর; বড়ু চণ্ডীদাসের জন্মস্থান পশ্চিমবঙ্গের বীরভূম জেলার নান্নুর গ্রাম (মতান্তরে বাঁকুড়ার ছাতনা); চর্যাপদের প্রাপ্তিস্থান নেপালের 'রাজগ্রন্থশালা' (রয়েল লাইব্রেরি)।"},{"id":"bangla-93","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'যে সবে বঙ্গেত জন্মি হিংসে বঙ্গবাণী। সে সব কাহার জন্ম নির্ণয় ন জানি।।'- কবিতাংশটি কোন কাব্যের অন্তর্গত?","options":["নূরনামা","নসিহতনামা","মধুমালতী","ইউসুফ-জুলেখা"],"correctIndex":0,"subject":"বাংলা","explanation":"উদ্ধৃত পঙ্‌ক্তিদ্বয় আবদুল হাকিম রচিত 'নূরনামা' কাব্যের অন্তর্গত 'বঙ্গবাণী' কবিতার অংশবিশেষ, যেখানে যারা বাংলায় জন্মেও বাংলা ভাষাকে ঘৃণা করে তাদের সমালোচনা করা হয়েছে। আবদুল হাকিম আনুমানিক ১৬২০ সালে সন্দ্বীপের সুধারামপুর গ্রামে জন্মগ্রহণ করেন; তাঁর অন্যান্য কাব্য- ইউসুফ জোলেখা, লালমতি, সয়ফুলমুলুক, শিহাবুদ্দিননামা, নসীহৎনামা, কারাবালা, শহরনামা। উল্লেখ্য, মধুমালতী কাব্যের রচয়িতা মুহম্মদ কবীর ও সৈয়দ হামজা; আর ইউসুফ-জুলেখা কাব্যের রচয়িতা আবদুল হাকিম ও শাহ মুহাম্মদ সগীর উভয়েই।"},{"id":"bangla-94","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"আলাওল কোন শতাব্দীর কবি?","options":["পঞ্চদশ","ষোড়শ","সপ্তদশ","অষ্টাদশ"],"correctIndex":2,"subject":"বাংলা","explanation":"আরাকান রাজসভার শ্রেষ্ঠ কবি ও সপ্তদশ শতকের শ্রেষ্ঠ মুসলিম কবি আলাওল ১৬০৭ খ্রিস্টাব্দে ফতেয়াবাদ পরগনা, ফরিদপুরে (মতান্তরে চট্টগ্রামের হাটহাজারীর জোবরা গ্রামে) জন্মগ্রহণ করেন। তুলনায়- পনেরো শতকের উল্লেখযোগ্য কবি শাহ মুহাম্মদ সগীর ও জয়েন উদ্দিন; ষোলো শতকের কবি দৌলত উজির বাহরাম খান, সাবিরিদ খান, মুহাম্মদ কবির; সপ্তদশ শতকের অন্যান্য কবি কোরেশী মাগন ঠাকুর, দৌলত কাজী, নওয়াজিস খান, আবদুল হাকিম।"},{"id":"bangla-95","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"কোন বাংলা গানকে ইউনেস্কো Heritage of Humanity অভিধায় ভূষিত করেছে?","options":["রবীন্দ্র সংগীত","নজরুল সংগীত","ভাটিয়ালি গান","বাউল গান"],"correctIndex":3,"subject":"বাংলা","explanation":"ইউনেস্কো তার প্যারিস সদর দপ্তর থেকে ২০০৫ সালে এক বিজ্ঞপ্তির মাধ্যমে বাংলাদেশের ঐতিহ্যবাহী বাউল গানকে Heritage of Humanity (মানবতার ধারক) অভিধায় ভূষিত করে/স্বীকৃতি দেয়; পরবর্তীতে ২০০৮ সালে ইউনেস্কো বাউল সংগীতকে Intangible Cultural Heritage হিসেবেও অন্তর্ভুক্ত করে।"},{"id":"bangla-96","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"চণ্ডীচরণ মুন্সী কে?","options":["শ্রীরামপুর মিশনের লিপিকর","ফোর্ট উইলিয়াম কলেজের পণ্ডিত","কেরী সাহেবের মুন্সী গ্রন্থের রচয়িতা","সমাচার চন্দ্রিকা পত্রিকার সম্পাদক"],"correctIndex":1,"subject":"বাংলা","explanation":"চণ্ডীচরণ মুন্সী ফোর্ট উইলিয়াম কলেজের পণ্ডিতদের অন্যতম, যিনি ১৮০১ সালে এই কলেজে যোগদান করেন; তাঁর রচিত গ্রন্থ 'তোতা ইতিহাস' (ফারসি 'তুতিনামা'-র বাংলা অনুবাদ)। অপশন বিশ্লেষণ: 'কেরী সাহেবের মুন্সী' গ্রন্থের রচয়িতা প্রমথনাথ বিশী; 'সমাচার চন্দ্রিকা' পত্রিকার সম্পাদক ভবানীচরণ বন্দ্যোপাধ্যায়।"},{"id":"bangla-97","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'রত্নপরীক্ষা' গ্রন্থের রচয়িতা-","options":["রামমোহন রায়","অক্ষয়কুমার দত্ত","ঈশ্বরচন্দ্র বিদ্যাসাগর","রাধানাথ শিকদার"],"correctIndex":2,"subject":"বাংলা","explanation":"ঈশ্বরচন্দ্র বিদ্যাসাগরের মৌলিক গ্রন্থসমূহের একটি 'রত্নপরীক্ষা', যা তিনি 'কন্যাচিৎ উপযুক্ত ভাইপো-সহচরস্য' ছদ্মনামে লেখেন; তাঁর অন্যান্য মৌলিক গ্রন্থ- প্রভাবতী সম্ভাষণ, আত্মচরিত, অতি অল্প হইল, আবার অতি অল্প হইল, ব্রজবিলাস, শব্দ মঞ্জরী, নিষ্কৃতি লাভের প্রয়াস। অপশন বিশ্লেষণ: রাজা রামমোহন রায়ের রচনা- বেদান্ত গ্রন্থ, বেদান্তসার, তুহফাত-উল মুওয়াহিদ্দীন প্রভৃতি; ব্রাহ্মধর্মের মুখপত্র 'তত্ত্ববোধিনী' পত্রিকার প্রথম সম্পাদক অক্ষয়কুমার দত্ত; ইয়ং বেঙ্গল-এর সদস্য, ডিরোজিওর ছাত্র ও গণিতজ্ঞ রাধানাথ শিকদার এভারেস্ট শৃঙ্গের আবিষ্কারক হিসেবে পরিচিত।"},{"id":"bangla-98","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"স্বর্ণকুমারী দেবীর পিতার নাম-","options":["দ্বারকানাথ ঠাকুর","দেবেন্দ্রনাথ ঠাকুর","রবীন্দ্রনাথ ঠাকুর","প্রমথ চৌধুরী"],"correctIndex":1,"subject":"বাংলা","explanation":"বাংলা সাহিত্যের প্রথম মহিলা ঔপন্যাসিক স্বর্ণকুমারী দেবীর জন্ম কলকাতার জোড়াসাঁকোর ঠাকুর পরিবারে; তাঁর পিতার নাম মহর্ষি দেবেন্দ্রনাথ ঠাকুর এবং দাদার নাম প্রিন্স দ্বারকানাথ ঠাকুর। স্বর্ণকুমারী দেবী রবীন্দ্রনাথ ঠাকুরের বড় বোন।"},{"id":"bangla-99","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"ভীষ্মদেব খোশনবীশ বঙ্কিমচন্দ্র চট্টোপাধ্যায়ের কোন গ্রন্থের চরিত্র?","options":["কমলাকান্ত","লোকরহস্য","মুচিরাম গুড়ের জীবনচরিত","যুগলাঙ্গরীয়"],"correctIndex":0,"subject":"বাংলা","explanation":"'ভীষ্মদেব খোশনবীশ' বঙ্কিমচন্দ্র চট্টোপাধ্যায়ের 'কমলাকান্তের দপ্তর' গ্রন্থের একটি চরিত্র। ইংরেজ সাহিত্যিক-সমালোচক ডি. কুইন্সির 'Confessions of an English Opium Eater' রচনার অনুকরণে বঙ্কিমচন্দ্র নকশাধর্মী রম্য রচনা 'কমলাকান্তের দপ্তর' রচনা করেন। অপশনের মধ্যে যুগলাঙ্গরীয় একটি উপন্যাস (চরিত্র- হিরণ্ময়ী, অমলা, ধনদাস, পুরন্দর), আর মুচিরাম গুড়ের জীবনচরিত-এর মূল চরিত্র মুচিরাম; বাকি তিনটি (কমলাকান্ত, লোকরহস্য, মুচিরাম গুড়ের জীবনচরিত) ব্যঙ্গাত্মক ও রম্য রচনা।"},{"id":"bangla-100","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"দীনবন্ধু মিত্রের 'নীলদর্পণ' নাটকের ইংরেজি অনুবাদক-","options":["জেয়া মার্শম্যান","ডেভিড হেয়ার","ঈশ্বরচন্দ্র বিদ্যাসাগর","মাইকেল মধুসূদন দত্ত"],"correctIndex":3,"subject":"বাংলা","explanation":"১৮৬০ সালে ঢাকার বাংলা প্রেস থেকে প্রকাশিত 'নীলদর্পণ' নাটকটি ১৮৬১ সালে মাইকেল মধুসূদন দত্ত 'A Native' ছদ্মনামে ইংরেজিতে অনুবাদ করেন এবং নাম দেন \"The Indigo Planting Mirror\"; পাদ্রি জেমস লং এটি প্রকাশ করে আদালত কর্তৃক অর্থদণ্ডে দণ্ডিত হন।"},{"id":"bangla-101","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"রঞ্জন চরিত্রটি রবীন্দ্রনাথ ঠাকুরের কোন নাটকের?","options":["বিসর্জন","রক্তকরবী","মুক্তধারা","ডাকঘর"],"correctIndex":1,"subject":"বাংলা","explanation":"রবীন্দ্রনাথ ঠাকুরের 'রক্তকরবী' নাটকের উল্লেখযোগ্য চরিত্র- কিশোর, রঞ্জন, নন্দিনী। তুলনায়- 'বিসর্জন' নাটকের চরিত্র অপর্ণা, গুণবতী, রঘুপতি, জয়সিংহ; 'মুক্তধারা' নাটকের চরিত্র অভিজিৎ, রনজিৎ, সুমন, অম্বা; 'ডাকঘর' নাটকের চরিত্র ঠাকুরদা, অমল, সুধা।"},{"id":"bangla-102","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'তৈল' প্রবন্ধটি লিখেছেন-","options":["সুকুমার রায়","রমেশচন্দ্র মজুমদার","শিবনারায়ণ রায়","হরপ্রসাদ শাস্ত্রী"],"correctIndex":3,"subject":"বাংলা","explanation":"মহামহোপাধ্যায় হরপ্রসাদ শাস্ত্রী রচিত প্রবন্ধসমূহ- তৈল, বাল্মীকির জয়, হাজার বছরের পুরাণ বাংলা ভাষায় বৌদ্ধ গান ও দোহা, প্রাচীন বাংলার গৌরব, মেঘদূত ব্যাখ্যা, বৌদ্ধধর্ম; তাঁর উপন্যাস- কাঞ্চনমালা, বেণের মেয়ে। নৈহাটি, পশ্চিমবঙ্গে জন্ম নেওয়া (আদি নিবাস কুমিরা গ্রাম, খুলনা) হরপ্রসাদ শাস্ত্রী ছিলেন ঢাকা বিশ্ববিদ্যালয়ের বাংলা ও সংস্কৃত বিভাগের প্রতিষ্ঠাতা চেয়ারম্যান এবং ১৯০৭ সালে নেপালের রাজগ্রন্থাগার থেকে চর্যাপদ আবিষ্কার করে ১৯১৬ সালে বঙ্গীয় সাহিত্য পরিষদ থেকে গ্রন্থাকারে প্রকাশ করেন। অপশন বিশ্লেষণ: সুকুমার রায়ের রচনা- আবোল-তাবোল, হ-য-ব-র-ল, খাই খাই; রমেশচন্দ্র মজুমদারের- চম্পা, বাংলা দেশের ইতিহাস; শিবনারায়ণ রায়ের- সাহিত্যচিন্তা, মৌমাছিতত্ত্ব, রেনেসাঁস প্রভৃতি।"},{"id":"bangla-103","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"\"নাম রেখেছি কোমল গান্ধার\" কাব্যের রচয়িতা-","options":["রবীন্দ্রনাথ ঠাকুর","বিষ্ণু দে","অমিয় চক্রবর্তী","প্রেমেন্দ্র মিত্র"],"correctIndex":1,"subject":"বাংলা","explanation":"মার্কসবাদী কবি বিষ্ণু দে রচিত কাব্যসমূহ- উর্বশী ও আর্টেমিস (প্রথম কাব্য), নাম রেখেছি কোমল গান্ধার, সন্দীপের চর, চোরাবালি, সাত ভাই চম্পা, তুমি শুধু পঁচিশে বৈশাখ, স্মৃতিসত্তা ভবিষ্যৎ, চিত্ররূপময় পৃথিবী। পঞ্চপাণ্ডবদের মধ্যে তিনিই সর্বাধিক কবিতা রচনা করেন। ('গান্ধার' শব্দের অর্থ স্বরগ্রামের তৃতীয় স্বর 'গা', দিবার দ্বিতীয় প্রহরে গেয় সংগীতের একটি রাগবিশেষ।) অপশন বিশ্লেষণ: অমিয় চক্রবর্তীর কাব্য- খসড়া (প্রথম কাব্যগ্রন্থ), অনিঃশেষ, পারাপার প্রভৃতি; প্রেমেন্দ্র মিত্রের কাব্য- প্রথমা, সম্রাট, সাগর থেকে ফেরা প্রভৃতি।"},{"id":"bangla-104","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'ও মন রমজানের ঐ রোজার শেষে এলো খুশির ঈদ'- গানটির রচয়িতা-","options":["কাজী নজরুল ইসলাম","গোলাম মোস্তফা","জসীমউদ্দীন","আব্বাস উদ্দীন আহমদ"],"correctIndex":0,"subject":"বাংলা","explanation":"'বুলবুল' নামে খ্যাত কাজী নজরুল ইসলামের কালজয়ী গান 'ও মন রমজানের ঐ রোজার শেষে এলো খুশির ঈদ', যা তিনি আব্বাস উদ্দীন আহমদের অনুরোধে রচনা করেন এবং নিজেই সুরারোপ করেন। নজরুলের অন্যান্য উল্লেখযোগ্য ইসলামি গান- 'আল্লাহ আমার প্রভু, আমার নাহি নাহি ভয়', 'আল্লাহ নামের বীজ বুনেছি', 'ত্রিভুবনের প্রিয় মোহাম্মদ এলো রে দুনিয়ায়', 'মসজিদেরই পাশে আমায় কবর দিও ভাই'।"},{"id":"bangla-105","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"শামসুর রাহমানের রচিত উপন্যাস-","options":["পতঙ্গ পিঞ্জর","প্রেম একটি লাল গোলাপ","রৌদ্র করোটিতে","অদ্ভুত আঁধার এক"],"correctIndex":3,"subject":"বাংলা","explanation":"কবি হিসেবে জনপ্রিয় হলেও শামসুর রাহমান কয়েকটি উপন্যাসও রচনা করেন- অক্টোপাস, নিয়ত মন্তাজ, অদ্ভুত আঁধার এক, এলো সে অবেলায়। তাঁর বিখ্যাত কাব্যগ্রন্থ- প্রথম গান দ্বিতীয় মৃত্যুর আগে, রৌদ্র করোটিতে, বাংলাদেশ স্বপ্ন দ্যাখে, দুঃসময়ের মুখোমুখি, নিজ বাসভূমে, বিধ্বস্ত নীলিমা, বন্দি শিবির থেকে; প্রবন্ধ- কবিতা এক ধরনের আশ্রয়, আমৃত্যু তাঁর জীবনানন্দ; আত্মস্মৃতি- স্মৃতির শহর, কালের ধুলোয় লেখা। অপশন বিশ্লেষণ: 'পতঙ্গ পিঞ্জর' উপন্যাসের রচয়িতা শওকত ওসমান; 'প্রেম একটি লাল গোলাপ' উপন্যাসের রচয়িতা রশীদ করিম; 'রৌদ্র করোটিতে' শামসুর রাহমানেরই একটি কাব্যগ্রন্থ, উপন্যাস নয়।"},{"id":"bangla-106","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"সেলিম আল দীনের নাটকে অনুসৃত শিল্পতত্ত্ব-","options":["অস্তিত্ববাদ","অভিব্যক্তিবাদ","পরাবাস্তববাদ","দ্বৈতাদ্বৈতবাদ"],"correctIndex":3,"subject":"বাংলা","explanation":"নতুন ধারার নাটকের পথিকৃৎ নাট্যাচার্য সেলিম আল দীনের নাটকে অনুসৃত শিল্পতত্ত্বের নাম দ্বৈতাদ্বৈতবাদ। পাশ্চাত্য শিল্পের প্রচলিত সব বিভাজনকে বাঙালির হাজার বছরের নন্দনতত্ত্বের আলোকে অস্বীকার করে তিনি বাংলা সাহিত্যে এই নবতর শিল্পরীতি প্রবর্তন করেন, যার মূলকথা হলো একটি লেখার মধ্যেই কবিতা, উপন্যাস, নাটক প্রভৃতি আঙ্গিকের সহাবস্থান। তিনি বাংলা নাটকের ফর্ম ও ভাষা নিয়েও নিরীক্ষাধর্মী কাজ করেন। তাঁর নাটক- কিত্তনখোলা, হাড্ডা-হাড্ডি, মুনতাসীর ফ্যান্টাসি, বনপাংশুল, চাকা, হরগজ, নিমজ্জন, কেরামত মঙ্গল প্রভৃতি।"},{"id":"bangla-107","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'পৃথক পালঙ্ক' কাব্যগ্রন্থের কবি-","options":["আল মাহমুদ","রফিক আজাদ","আবুল হাসান","আবুল হোসেন"],"correctIndex":2,"subject":"বাংলা","explanation":"'পৃথক পালঙ্ক' কাব্যগ্রন্থের রচয়িতা আবুল হাসান; তাঁর অন্যান্য কাব্য- রাজা যায় রাজা আসে, যে তুমি হরণ করো। অপশন বিশ্লেষণ: আল মাহমুদের কাব্য- লোক লোকান্তর, সোনালী কাবিন, কালের কলস, বখতিয়ারের ঘোড়া; রফিক আজাদের কাব্য- অসম্ভবের পায়ে, চুনিয়া আমার আর্কেডিয়া, সীমাবদ্ধ জলে সীমিত সবুজে; আবুল হোসেনের কাব্য- নববসন্ত (প্রথম কাব্যগ্রন্থ), বিরস সংলাপ, দুঃস্বপ্ন থেকে দুঃস্বপ্নে।"},{"id":"bangla-108","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"কোন গল্পকারের গল্পে ম্যাজিক রিয়েলিজমের প্রতিফলন ঘটেছে?","options":["জ্যোতিপ্রকাশ দত্ত","রিজিয়া রহমান","শহীদুল জহির","দিলারা হাশেম"],"correctIndex":2,"subject":"বাংলা","explanation":"বাংলা সাহিত্যের অন্যতম কথাশিল্পী শহীদুল জহিরের গল্পে ম্যাজিক রিয়েলিজম (জাদুবাস্তবতা)-এর প্রতিফলন ঘটেছে; তিনি নিজেই এক সাক্ষাৎকারে বলেন যে জাদুবাস্তবতার ধারণা তিনি গ্যাব্রিয়েল গার্সিয়া মার্কেসের (কলম্বিয়া, ম্যাজিক রিয়েলিজমের প্রবক্তা) কাছ থেকে পেয়ে সচেতনভাবে নিজের গল্প-উপন্যাসে প্রয়োগ করেছেন। শহীদুল জহিরের উপন্যাস- জীবন ও রাজনৈতিক বাস্তবতা, সে রাতে পূর্ণিমা ছিল, মুখের দিকে দেখি; গল্প- পারাপার, কাঁটা, ডুমুরখেকো মানুষ ও অন্যান্য গল্প। অপশন বিশ্লেষণ: জ্যোতিপ্রকাশ দত্তের গল্প- দুর্বিনীত কাল, বহে না সুবাতাস; রিজিয়া রহমানের প্রথম গ্রন্থ অগ্নিস্বাক্ষরা; দিলারা হাশেমের গল্প- নায়ক, হলদে পাখীর কান্না।"},{"id":"bangla-109","exam":"৪৬তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"\"একুশ মানে মাথা নত না করা\"- এই অমর পঙ্‌ক্তির রচয়িতা-","options":["আবদুল গাফ্‌ফার চৌধুরী","আবুল ফজল","মুনীর চৌধুরী","সিরাজুল চৌধুরী"],"correctIndex":1,"subject":"বাংলা","explanation":"ঢাকার মুসলিম সাহিত্য সমাজের অন্যতম প্রতিষ্ঠাতা ও 'বুদ্ধির মুক্তি আন্দোলন'-এর অন্যতম কর্ণধার আবুল ফজলের একটি বিখ্যাত প্রবন্ধ 'একুশ মানে মাথা নত না করা'। তাঁর অন্যান্য প্রবন্ধ- মানবতন্ত্র, বিচিত্র কথা, সমকালীন চিন্তা, সাহিত্য ও সংস্কৃতি সাধনা; উপন্যাস- চৌচির, রাঙা প্রভাত, প্রদীপ ও পতঙ্গ, জীবন পথের যাত্রী; আত্মকাহিনি- রেখাচিত্র, দুর্দিনের দিনলিপি।"},{"id":"bangla-110","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'ধ্বনি' সম্পর্কে নিচের কোন বাক্যটি সঠিক নয়?","options":["ধ্বনি দৃশ্যমান","মানুষের ভাষার মূলে আছে কতগুলো ধ্বনি","ধ্বনি উচ্চারণীয় ও শ্রবণীয়","অর্থবোধক ধ্বনিগুলোই মানুষের বিভিন্ন ভাষার বাগ্‌ধ্বনি"],"correctIndex":0,"subject":"বাংলা","explanation":"মানুষের বাগযন্ত্রের সাহায্যে তৈরি আওয়াজকে ধ্বনি বলে, অর্থাৎ মানুষের মুখনিঃসৃত অর্থবোধক আওয়াজ হলো ধ্বনি। ধ্বনি সম্পর্কে গুরুত্বপূর্ণ তথ্য: মানুষের ভাষার মূলে আছে কতগুলো ধ্বনি; ধ্বনি উচ্চারণীয় ও শ্রবণীয়; অর্থবোধক ধ্বনিগুলোই মানুষের বিভিন্ন ভাষার বাগ্‌ধ্বনি; ভাষার ক্ষুদ্রতম একক ও মূল ভিত্তি ধ্বনি; ধ্বনি পরিমাপের ক্ষুদ্রতম মানদণ্ড মাত্রা। কিন্তু 'ধ্বনি দৃশ্যমান' কথাটি সত্য নয় — ধ্বনির লিখিত রূপ/নির্দেশক চিহ্ন হলো বর্ণ, ধ্বনি দৃশ্যমান না হলেও বর্ণ দৃশ্যমান।"},{"id":"bangla-111","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"স্বরান্ত অক্ষরকে কী বলে?","options":["একাক্ষর","মুক্তাক্ষর","বদ্ধাক্ষর","যুক্তাক্ষর"],"correctIndex":1,"subject":"বাংলা","explanation":"নিঃশ্বাসের স্বল্পতম প্রয়াসে উচ্চারিত ধ্বনিগুচ্ছকে অক্ষর বলে; অক্ষর প্রধানত ২ প্রকার — মুক্তাক্ষর (স্বরান্ত অক্ষর) ও বদ্ধাক্ষর (ব্যঞ্জনান্ত অক্ষর)। মুক্তাক্ষর/স্বরান্ত অক্ষরের শেষে স্বরধ্বনি থাকে (যেমন: লা...-এর শেষে 'আ'), বদ্ধাক্ষরের শেষে ব্যঞ্জনধ্বনি থাকে (যেমন: বাং...-এর শেষে 'ং')। মুক্তাক্ষরের উচ্চারণে মুখ খোলা থাকে, বদ্ধাক্ষরের কিছু ক্ষেত্রে মুখ খোলা থাকে না। জেনে রাখা ভালো: মুক্তাক্ষরের চিহ্ন (U) আকৃতির, বদ্ধাক্ষরের চিহ্ন (–) আকৃতির।"},{"id":"bangla-112","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"শুদ্ধ বানানের গুচ্ছ কোনটি?","options":["শিরশ্ছেদ, দরিদ্রতা, সমীচীন","শিরোচ্ছেদ, দারিদ্র্য, সমীচিন","শিরঃচ্ছেদ, দরিদ্রতা, সমিচীন","শিরচ্ছেদ, দরিদ্রতা, সমীচীন"],"correctIndex":0,"subject":"বাংলা","explanation":"শুদ্ধ বানানসমূহ: শিরশ্ছেদ, দরিদ্রতা/দারিদ্র্য, সমীচীন। জেনে রাখা ভালো: শিরশ্ছেদ-এর সন্ধিবিচ্ছেদ শিরঃ + ছেদ (এটি বিসর্গ সন্ধিজাত শব্দ, বিসর্গের পরে শ-ধ্বনি হওয়ায় ছ যুক্ত হয়ে শিরশ্ছেদ হয়েছে)। দরিদ্রতা (দরিদ্র+তা) বা দারিদ্র্য (দরিদ্র+য) — দুটোই প্রত্যয়সাধিত শব্দ। 'সমীচীন' (সম্যক্‌+ঈন) শব্দটিও প্রত্যয়সাধিত, অর্থ সংগত/উপযুক্ত/উত্তম/যথার্থ/সত্য/উচিত। অপশন (ঘ) 'শিরচ্ছেদ' ভুল বানান — সঠিক 'শিরশ্ছেদ'।"},{"id":"bangla-113","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"আরবি 'কলম' শব্দটি 'কলমোস' শব্দ থেকে এসেছে। 'কলমোস' কোন ভাষার শব্দ?","options":["পাঞ্জাবি","ফরাসি","গ্রিক","স্পেনিশ"],"correctIndex":2,"subject":"বাংলা","explanation":"কলমোস (Kalamas) শব্দটি গ্রিক ভাষার শব্দ, যার অর্থ reed/reed pen। অপশন বিশ্লেষণ: প্রচলিত তথ্যানুযায়ী চাহিদা ও তারকা পাঞ্জাবি শব্দ বলে ধরা হলেও বাংলা একাডেমি আধুনিক বাংলা অভিধান অনুযায়ী চাহিদা তদ্ভব শব্দ ও তারকা সংস্কৃত শব্দ। ফরাসি শব্দের উদাহরণ: আঁতাত, ওলন্দাজ, কুপন, ক্যাফে, ক্যাসেট, গ্যারাজ, ডিপো, ডিভিডেন্ড, ডিস্ট্রিক্ট, ডেন্টিস্ট, ডেমারেজ, রেস্তোরাঁ, বুর্জোয়া, ম্যাগাজিন, ম্যাংগানিজ, ম্যাটিনি, মর্গ, রেনেসাঁস, ফর্মা। গ্রিক শব্দের আরও উদাহরণ: কেন্দ্র, দাম, ডাইনামাইট, ডায়নামো।"},{"id":"bangla-114","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'ভাষা চিন্তার শুধুই বাহনই নয়, চিন্তার প্রসূতিও।' মন্তব্যটি কোন ভাষা-চিন্তকের?","options":["সুনীতিকুমার চট্টোপাধ্যায়","মুহম্মদ শহীদুল্লাহ","মুহম্মদ এনামুল হক","সুকুমার সেন"],"correctIndex":3,"subject":"বাংলা","explanation":"সুকুমার সেন তাঁর 'ভাষার ইতিবৃত্ত' (১৯৩৯) গ্রন্থে উল্লিখিত মন্তব্যটি করেন। একই গ্রন্থে তিনি আরও বলেন: 'ভাষা মানুষের জন্মসূত্রে পাওয়া, তাহা এতই স্বাভাবিক যে চলাফেরা বা শ্বাসক্রিয়ার মতো স্বয়ংক্রিয় বৃত্তি বলিয়া মনে হয়' এবং 'মানুষের উচ্চারিত, অর্থবহ বহুজনবোধ্য ধ্বনিসমষ্টিই ভাষা।'"},{"id":"bangla-115","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"সর্বপ্রথম বাংলা ভাষার ব্যাকরণ রচনা করেন কে?","options":["মানোএল দ্য আসসুম্পসাঁও","রাজা রামমোহন রায়","রামেন্দ্রসুন্দর ত্রিবেদী","নাথানিয়েল ব্রাসি হালহেড"],"correctIndex":0,"subject":"বাংলা","explanation":"বাংলা ভাষার প্রথম ব্যাকরণ রচনা করেন মানোএল দ্য আসসুম্পসাঁও (পর্তুগিজ ভাষায় লেখেন); বইটির নাম 'ভোকাবুলারিও এম ইদিওমা বেনগল্লা ই পোর্তুগিজ' (১৭৪৩)। বাংলা ভাষার প্রথম ব্যাকরণগ্রন্থ রচনা করেন নাথানিয়েল ব্রাসি হালহেড (ইংরেজিতে লেখেন, তবে আংশিক বাংলায় মুদ্রিত); বইটির নাম 'A Grammar of the Bengal Language' (১৭৭৮)। বাঙালি কর্তৃক প্রথম বাংলা ব্যাকরণ রচনা করেন রাজা রামমোহন রায়; বইটির নাম 'গৌড়ীয় ব্যাকরণ' (১৮৩৩)।"},{"id":"bangla-116","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"উচ্চারণের রীতি অনুযায়ী নিচের কোনটি উচ্চমধ্য-সম্মুখ স্বরধ্বনি?","options":["অ","আ","ও","এ"],"correctIndex":3,"subject":"বাংলা","explanation":"জিভের উচ্চতা ও অবস্থান এবং ঠোঁটের উন্মুক্তি অনুযায়ী স্বরধ্বনির শ্রেণিবিভাগ করা হয়। সম্মুখ-উচ্চ 'ই' (সংবৃত), সম্মুখ-উচ্চমধ্য 'এ' (অর্ধ-সংবৃত), মধ্য-নিম্ন 'আ' (বিবৃত), পশ্চাৎ-উচ্চ 'উ' (সংবৃত), পশ্চাৎ-উচ্চমধ্য 'ও' (অর্ধ-সংবৃত), পশ্চাৎ-নিম্নমধ্য 'অ' (অর্ধ-বিবৃত)। সুতরাং উচ্চমধ্য-সম্মুখ স্বরধ্বনি হলো 'এ'।"},{"id":"bangla-117","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'তাম্বুলিক' শব্দের সমার্থক নয় কোনটি?","options":["পান-ব্যবসায়ী","পর্ণকার","তামসিক","বারুই"],"correctIndex":2,"subject":"বাংলা","explanation":"তাম্বুল শব্দের অর্থ পান/লতাবিশেষের পাতা (যা সুপারি-চুন প্রভৃতি সহযোগে খাওয়া হয়); তাম্বুলিক শব্দের অর্থ পান-ব্যবসায়ী, পর্ণকার (পান বিক্রেতা), বারুই (পান চাষী)। অপশন বিশ্লেষণ: 'তমস' শব্দের অর্থ 'অন্ধকার' আর তামসিক শব্দের অর্থ তমোগুণসংক্রান্ত/মেঘাচ্ছন্ন/(অলংকাররূপে) অজ্ঞতাপ্রসূত — এটি তাম্বুলিকের সমার্থক নয়। জেনে রাখা ভালো: 'তামসিক' (তমস+ইক) সংস্কৃত তদ্ধিত প্রত্যয়ের উদাহরণ।"},{"id":"bangla-118","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'তুমি তো ভারি সুন্দর ছবি আঁক!'—বাক্যটিতে কোন প্রকারের অব্যয় পদ ব্যবহৃত হয়েছে?","options":["পদান্বয়ী অব্যয়","অনুসর্গ অব্যয়","অনম্বয়ী অব্যয়","অনুকার অব্যয়"],"correctIndex":2,"subject":"বাংলা","explanation":"যে সকল অব্যয় বাক্যে স্বাধীনভাবে নানাবিধ ভাবপ্রকাশে ব্যবহৃত হয়, তাদের অনন্বয়ী অব্যয় বলে; উদাহরণ: মরি মরি!, হ্যাঁ, তো, উঃ, ছিছি, ওগো, পাছে। অনুকার/ধ্বন্যাত্মক অব্যয় অব্যক্ত রব বা ধ্বনির অনুকরণে গঠিত হয় (ঝম ঝম, কন কন, কল কল, ছম ছম, টন টন, খাঁ খাঁ)। অনুসর্গ/পদান্বয়ী অব্যয় বিশেষ্য-সর্বনাম পদের বিভক্তির মতো বসে কারকবাচকতা প্রকাশ করে (যেমন: 'ওকে দিয়ে এ কাজ হবে না'-তে 'দিয়ে')।"},{"id":"bangla-119","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"নিচের কোনটি যৌগিক শব্দ?","options":["প্রবীণ","জ্যেঠামি","সরোজ","মিতালি"],"correctIndex":3,"subject":"বাংলা","explanation":"যে সকল শব্দের ব্যুৎপত্তিগত অর্থ ও ব্যবহারিক অর্থ একই রকম, তাদের যৌগিক শব্দ বলে (শর্টকাট: মূল শব্দের অর্থ নতুন শব্দে থাকে)। যেমন: মিতা (মূল শব্দ, অর্থ বন্ধু) + আলি = মিতালি (নতুন শব্দ, অর্থ বন্ধুত্ব) — উৎপত্তিগত ও ব্যবহারিক অর্থ এক। অন্যান্য গুরুত্বপূর্ণ যৌগিক শব্দ: মধুর, গায়ক, কর্তব্য, বাবুয়ানা, দৌহিত্র, চিকামারা। অপশন বিশ্লেষণ: প্রবীণ (প্র+√বীণি+অ) ও জ্যেঠামি (সর্দারি/পাকামি) রূঢ়ি শব্দ; সরোজ (সরোবরে জন্মে যা) যোগরূঢ় শব্দ।"},{"id":"bangla-120","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'সুনামীর তাণ্ডবে অনেকেই সর্বশান্ত হয়েছে।'—বাক্যটিতে কয়টি ভুল আছে?","options":["একটি","দুটি","তিনটি","ভুল নেই"],"correctIndex":2,"subject":"বাংলা","explanation":"বাক্যটিতে ৩টি ভুল আছে; সঠিক বাক্য: 'সুনামির তাণ্ডবে অনেকেই সর্বস্বান্ত হয়েছে।' সুনামি (Tsunami) জাপানি/বিদেশি শব্দ, তাই বানানে ই-কার হবে। তাণ্ডব (তণ্ড+অ) তৎসম/সংস্কৃত শব্দ — নতৃ বিধি অনুযায়ী ট-বর্গীয় বর্ণের আগে দন্ত্য-ন না হয়ে মূর্ধন্য-ণ হয়, তাই সঠিক বানান তাণ্ডব। সঠিক বানান সর্বস্বান্ত (সর্বস্ব+অন্ত) — সব সম্পদ হারিয়ে নিঃস্ব হয়েছে এমন ব্যক্তিকে বোঝায়।"},{"id":"bangla-121","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"কৃদন্ত পদের পূর্ববর্তী পদকে কী বলে?","options":["উপপদ","প্রাতিপদিক","প্রপদ","পূর্বপদ"],"correctIndex":0,"subject":"বাংলা","explanation":"কৃদন্ত পদের পূর্ববর্তী পদ হলো উপপদ। যেমন: 'পকেটমার' শব্দে 'মার' কৃদন্ত পদ আর 'পকেট' উপপদ; অনুরূপভাবে ইন্দ্রজিৎ, সত্যবাদী, ধামাধরা শব্দে যথাক্রমে ইন্দ্র, সত্য, ধামা উপপদ। জেনে রাখা ভালো: উপপদকে পদের নিকটস্থ পদ/পূর্বপদও বলা হয়। অপশন বিশ্লেষণ: প্রাতিপদিক হলো বিভক্তিহীন নাম শব্দ/ধাতু (যেমন হাতে=হাত+এ-তে 'হাত'); প্রপদ পায়ের অগ্রভাগ/পাদপ্রান্ত বোঝায়; পূর্বপদ সমস্তপদের প্রথম অংশ (যেমন 'রান্নাঘর'-এ 'রান্না')।"},{"id":"bangla-122","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'তোমার নাম কী?'—এখানে 'কী' কোন প্রকারের পদ?","options":["প্রশ্নবাচক","অব্যয়","সর্বনাম","বিশেষণ"],"correctIndex":2,"subject":"বাংলা","explanation":"বিশেষ্যের পরিবর্তে ব্যবহৃত শব্দ সর্বনাম পদ; এর মধ্যে 'কী' প্রশ্নবাচক সর্বনামের উদাহরণ। অন্যান্য সর্বনাম শ্রেণি: ব্যক্তিবাচক (আমি, তুমি, সে...), আত্মবাচক (স্বয়ং, নিজ, খোদ, আপনি), সামীপ্যবাচক (এ, এই, এরা), অনির্দিষ্টতাজ্ঞাপক (কোন, কেহ, কেউ), ব্যতিহারিক (আপনা আপনি, নিজে নিজে, পরস্পর), সংযোগজ্ঞাপক (যে, যিনি, যারা), সাকুল্যবাচক (সব, সকল, সমুদয়) ও অন্যাদিবাচক (অন্য, অপর, পর)।"},{"id":"bangla-123","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'সরল' শব্দের বিপরীতার্থক নয় নিচের কোনটি?","options":["কুটিল","জটিল","বক্র","গরল"],"correctIndex":3,"subject":"বাংলা","explanation":"'সরল' শব্দের অর্থ ঋজু/সোজা; এর বিপরীত শব্দ কুটিল, জটিল ও বক্র। 'গরল' এর বিপরীত হলো অমৃত, তাই এটি সরলের বিপরীত নয়।"},{"id":"bangla-124","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'Rank' শব্দের বাংলা পরিভাষা কী?","options":["পদ","পদমর্যাদা","মাত্রা","উচ্চতা"],"correctIndex":1,"subject":"বাংলা","explanation":"পদমর্যাদাক্রমে নির্দিষ্ট অবস্থান বা সেনাবাহিনীতে পদমর্যাদা বোঝাতে 'Rank' শব্দটির বাংলা পরিভাষা পদমর্যাদা। অপশন বিশ্লেষণ: পদ-এর ইংরেজি Position, মাত্রা-এর Dimension, উচ্চতা-র Altitude/Height।"},{"id":"bangla-125","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"চর্যাপদের তিব্বতি অনুবাদ প্রকাশ করেন কে?","options":["প্রবোধচন্দ্র বাগচী","যতীন্দ্র মোহন বাগচী","প্রফুল্ল মোহন বাগচী","প্রণয়ভূষণ বাগচী"],"correctIndex":0,"subject":"বাংলা","explanation":"চর্যাপদ তিব্বতি ভাষায় অনুবাদ করেন কীর্তিচন্দ্র; ১৯৩৮ সালে এই অনুবাদ আবিষ্কার ও প্রকাশ করেন ড. প্রবোধচন্দ্র বাগচী। অপশন বিশ্লেষণ: যতীন্দ্রমোহন বাগচী (১৮৭৮-১৯৪৮) বাঙালি কবি ও সম্পাদক; বিখ্যাত কবিতা কাজলাদিদি, অন্ধবধূ, হাট; কাব্যগ্রন্থ লেখা, রেখা, অপরাজিতা, বন্ধুর দান, মহাভারতী। জেনে রাখা ভালো: বাংলা সাহিত্যের আদি নিদর্শন চর্যাপদ (মূলত গান/কবিতার সংকলন), যা মহামহোপাধ্যায় হরপ্রসাদ শাস্ত্রী নেপালের 'রাজগ্রন্থশালা' থেকে ১৯০৭ সালে আবিষ্কার করেন এবং ১৯১৬ সালে গ্রন্থাকারে প্রকাশ করেন।"},{"id":"bangla-126","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'গীতগোবিন্দ' কাব্যের রচয়িতা জয়দেব কার সভাকবি ছিলেন?","options":["শশাঙ্কদেবের","লক্ষ্মণ সেনের","যশোবর্মনের","হর্ষবর্ধনের"],"correctIndex":1,"subject":"বাংলা","explanation":"জয়দেব ছিলেন লক্ষ্মণসেনের রাজসভার পঞ্চরত্নের অন্যতম (অপর চারজন: গোবর্ধন আচার্য, শরণ, ধোয়ী, উমাপতিধর); কারও কারও মতে কিছুকাল উৎকলরাজেরও সভাপণ্ডিত ছিলেন। জয়দেব সংস্কৃত কবি, বিখ্যাত রচনা গীতগোবিন্দম্ (রাধাকৃষ্ণের প্রেমলীলা বিষয়ক সংস্কৃত গীতিকাব্য, ২৮৬টি শ্লোক ও ২৪টি গীতসহ ১২ সর্গে রচিত)। অপশন বিশ্লেষণ: যশোবর্মনের সভাকবি ছিলেন ভবভূতি, হর্ষবর্ধনের সভাকবি ছিলেন বানভট্ট; শশাঙ্কদেবের সভাকবি সম্পর্কে তথ্য নেই।"},{"id":"bangla-127","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"কবি যশোরাজ খান বৈষ্ণবপদ রচনা করেন কোন ভাষায়?","options":["ব্রজবুলি","বাংলা","সংস্কৃত","হিন্দি"],"correctIndex":0,"subject":"বাংলা","explanation":"কবি যশোরাজ খান বৈষ্ণবপদ রচনা করেন ব্রজবুলি ভাষায়; বাংলাদেশে প্রথম ব্রজবুলি পদ রচনা করেন তিনিই। আসামে শংকরদেব ও উড়িষ্যায় রামানন্দ রায়ও ব্রজবুলির চর্চা করেন (তিনজনই ষোলো শতকের কবি)। জেনে রাখা ভালো: বৈষ্ণব পদাবলি মধ্যযুগের বাংলা সাহিত্যের শ্রেষ্ঠ ফসল; এর অধিকাংশ পদ ব্রজবুলি ভাষায় রচিত। ব্রজবুলি মধ্যযুগীয় বাংলা সাহিত্যের দ্বিতীয় কাব্যভাষা/উপভাষা, যার উদ্ভাবক মিথিলার কবি বিদ্যাপতি — তিনি এ ভাষায় রাধাকৃষ্ণের লীলাবিষয়ক পদ রচনা করেন। বাংলা ও মৈথিলী ভাষার মিশ্রণ এই ব্রজবুলি; এর শ্রেষ্ঠ অবাঙালি কবি বিদ্যাপতি, শ্রেষ্ঠ বাঙালি কবি গোবিন্দদাস কবিরাজ।"},{"id":"bangla-128","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"নিচের কোন জন যুদ্ধকাব্যের রচয়িতা নন?","options":["দৌলত উজির বাহরাম খাঁ","সাবিরিদ","সৈয়দ সুলতান","সৈয়দ নূরুদ্দীন"],"correctIndex":3,"subject":"বাংলা","explanation":"মধ্যযুগীয় বাংলা সাহিত্যে মুসলিম ঐতিহ্যভিত্তিক যুদ্ধ-বিগ্রহ বিষয়ক কাব্য হলো জঙ্গনামা/যুদ্ধকাব্য (ফারসি 'জঙ্গ' অর্থ যুদ্ধ); হযরত মুহম্মদ (স.) ও তাঁর স্বজনদের যুদ্ধই এ শ্রেণির কাব্যের মূল বিষয়। জঙ্গনামা/যুদ্ধধারার উল্লেখযোগ্য কবি: দৌলত উজির বাহরাম খান, সৈয়দ সুলতান, সাবিরিদ খান, শেখ ফয়জুল্লাহ, ফকির গরিবুল্লাহ, মুহম্মদ খান, শেরবাজ, হেয়াত মামুদ প্রমুখ — এই তালিকায় সৈয়দ নূরুদ্দীনের নাম নেই।"},{"id":"bangla-129","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"কোনটি কবি জৈনুদ্দিনের কাব্যগ্রন্থ?","options":["রসুল বিজয়","মক্কা বিজয়","রসুলচরিত","মক্কানামা"],"correctIndex":0,"subject":"বাংলা","explanation":"জৈনুদ্দীন মধ্যযুগীয় বাংলা সাহিত্যের কবি, 'রসুলবিজয়' কাব্য রচনা করে খ্যাতি অর্জন করেন; পৃষ্ঠপোষক ছিলেন গৌড়ের যুবরাজ ইছপ খান (পরে সুলতান শামসুদ্দীন ইউসুফ শাহ)। রসুলবিজয় যুদ্ধবিষয়ক কাহিনিকাব্য, যাতে হযরত মুহম্মদ (স.) ও ইরাকাধিপতি জয়কুমের যুদ্ধের বর্ণনা আছে। একই সময়ে সুলতান বারবক শাহের রাজত্বকালে মালাধর বসু রচনা করেন শ্রীকৃষ্ণবিজয় কাব্য — রসুলবিজয় ও শ্রীকৃষ্ণবিজয় যথাক্রমে মুসলিম ও হিন্দু সম্প্রদায়ের প্রতিনিধিত্ব করে বলে মনে করা হয়। জেনে রাখা ভালো: সৈয়দ সুলতানের শ্রেষ্ঠ রচনা নবীবংশ কাব্য, যার ২য় খণ্ডের নাম রসুল চরিত।"},{"id":"bangla-130","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"\"বিদ্যাসাগর ও বাঙালি সমাজ\" গ্রন্থের রচয়িতা কে?","options":["বিনয় ঘোষ","সুবিনয় ঘোষ","বিনয় ভট্টাচার্য","বিনয় বর্মণ"],"correctIndex":0,"subject":"বাংলা","explanation":"বাংলা ভাষা ও লোকসংস্কৃতির গবেষক বিনয় ঘোষের জন্ম কলকাতায় (পৈতৃক নিবাস যশোরে); ছদ্মনাম 'কালপেঁচা'। মার্কসবাদে বিশ্বাসী হওয়ায় তাঁর রচনায় মার্কসীয় জীবনদর্শনের অনুশীলন লক্ষ করা যায়। গবেষণাগ্রন্থ হিসেবে বিদ্যাসাগর ও বাঙালীসমাজ (১৯৫৭), বিদ্রোহী ডিরোজিও, মধ্যবিত্ত বিদ্রোহ, বাংলার নবজাগৃতি, বাংলার লোকসংস্কৃতি ও সমাজতত্ত্ব প্রভৃতি তাঁর প্রধান রচনা। অন্যান্য গ্রন্থ: টাউন কলিকাতার কড়চা, কালপেঁচার নকসা, নববাবুচরিত, ডাস্টবিন (গল্প-সংকলন); উপন্যাস ৩০৪। ভারতীয় গণনাট্য সংঘের (১৯৪৩) সঙ্গে ঘনিষ্ঠ সম্পর্ক ছিল, যেখানে তাঁর 'ল্যাবরেটরী' নাটক অভিনীত হয়। জেনে রাখা ভালো: বিনয় ঘোষ কলকাতা বিশ্ববিদ্যালয়ের 'বিদ্যাসাগর বক্তৃতা'র প্রথম বক্তা (১৯৫৭)।"},{"id":"bangla-131","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"প্রথম সাহিত্যিক গদ্যের স্রষ্টা কে?","options":["রাজা রামমোহন রায়","ঈশ্বরচন্দ্র বিদ্যাসাগর","মৃত্যুঞ্জয় বিদ্যালঙ্কার","বঙ্কিমচন্দ্র চট্টোপাধ্যায়"],"correctIndex":1,"subject":"বাংলা","explanation":"ঈশ্বরচন্দ্র বিদ্যাসাগর বাংলা গদ্যের শব্দ-সাযুজ্য আবিষ্কার, বাক্য-কাঠামো সংস্কার, কর্তা-ক্রিয়াপদ ও ক্রিয়া-কর্মের যথাযথ অন্বয় স্থাপন করে বাংলা গদ্যকে মাধুর্য দান করেন; শ্বাস-যতি ও অর্থ-যতির সমন্বয় ঘটিয়ে ইংরেজি রীতির যতিচিহ্ন (বিশেষত কমা) ব্যবহার করেন। তাই তাঁকে 'প্রথম সাহিত্যিক গদ্যের স্রষ্টা'/'বাংলা গদ্যের জনক' বলা হয়। জেনে রাখা ভালো: তিনিই সর্বপ্রথম বিরামচিহ্নের প্রবর্তন করেন (প্রথম গ্রন্থ 'বেতাল পঞ্চবিংশতি'-তে)। অপশন বিশ্লেষণ: রাজা রামমোহন রায় প্রথম বাঙালি হিসেবে বাংলা ব্যাকরণ (গৌড়ীয় ব্যাকরণ) রচনা করেন; মৃত্যুঞ্জয় বিদ্যালঙ্কার ফোর্ট উইলিয়াম কলেজের পণ্ডিতদের মধ্যে সর্বাধিক (৫টি) গ্রন্থ রচনা করেন (বত্রিশ সিংহাসন, হিতোপদেশ, রাজাবলি, বেদান্ত চন্দ্রিকা, প্রবোধ চন্দ্রিকা); বঙ্কিমচন্দ্র চট্টোপাধ্যায় বাংলা সাহিত্য ধারার প্রতিষ্ঠাতা পুরুষ/প্রথম সার্থক ঔপন্যাসিক।"},{"id":"bangla-132","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"প্যারীচাঁদ মিত্রের \"আলালের ঘরের দুলাল\" প্রথম গ্রন্থাকারে প্রকাশিত হয় কত সালে?","options":["১৮৫৮ সালে","১৯৭৮ সালে","১৮৪৮ সালে","১৮৬৮ সালে"],"correctIndex":0,"subject":"বাংলা","explanation":"প্যারীচাঁদ মিত্র রচিত 'আলালের ঘরের দুলাল' (প্রকাশ ১৮৫৭, মতান্তরে ১৮৫৮) বাংলা সাহিত্যের প্রথম উপন্যাস; উল্লেখযোগ্য চরিত্র মতিলাল, ঠকচাচা, রামলাল। প্যারীচাঁদ মিত্রকে বলা হয় বাংলা উপন্যাস ধারার প্রতিষ্ঠাতা পুরুষ/বাংলা ভাষার প্রথম ঔপন্যাসিক।"},{"id":"bangla-133","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"শচীন, দামিনী ও শ্রীবিলাস রবীন্দ্রনাথ ঠাকুরের কোন উপন্যাসের চরিত্র?","options":["চতুরঙ্গ","চার অধ্যায়","নৌকাডুবি","ঘরে বাইরে"],"correctIndex":0,"subject":"বাংলা","explanation":"সাধুভাষায় লিখিত রবীন্দ্রনাথের সর্বশেষ উপন্যাস 'চতুরঙ্গ' (১৯১৬ সালে প্রকাশিত) — শচীশ নামের এক যুবকের আত্মানুসন্ধান সম্পর্কিত উপন্যাস, যার চরিত্র শচীশ, দামিনী, শ্রীবিলাস, জ্যাঠামশাই। অপশন বিশ্লেষণ: 'চার অধ্যায়'-এর চরিত্র এলা, ইন্দ্রনাথ, অতীন্দ্রনাথ; 'নৌকাডুবি'-র চরিত্র রমেশ, হেমনলিনী, কমলা; 'ঘরে-বাইরে'-র চরিত্র নিখিলেশ, বিমলা, সন্দীপ।"},{"id":"bangla-134","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"\"তুমি মা কল্পতরু, আমরা সব পোষাগরু\"—এই কবিতাংশটির রচয়িতা কে?","options":["রঙ্গলাল বন্দ্যোপাধ্যায়","ঈশ্বরচন্দ্র বিদ্যাসাগর","হেমচন্দ্র বন্দ্যোপাধ্যায়","ঈশ্বরচন্দ্র গুপ্ত"],"correctIndex":3,"subject":"বাংলা","explanation":"যুগসন্ধিক্ষণের কবি ঈশ্বরচন্দ্র গুপ্তের বিখ্যাত কবিতাংশ \"তুমি মা কল্পতরু, আমরা সব পোষাগরু\" (মহারাণী ভিক্টোরিয়াকে উদ্দেশ্য করে রচিত), যা তাঁর 'নীলকর' কবিতার অংশবিশেষ। 'কল্পতরু' অর্থ কল্পবৃক্ষ। বাংলা ভাষায় প্রকাশিত প্রথম দৈনিক 'সংবাদ প্রভাকর'-এর সম্পাদক ছিলেন ঈশ্বরচন্দ্র গুপ্ত; তাঁর কাব্য প্রবোধ প্রভাকর, হিতপ্রভাকর। অপশন বিশ্লেষণ: রঙ্গলাল বন্দ্যোপাধ্যায়ের উক্তি 'স্বাধীনতা হীনতায় কে বাঁচিতে চায়'; ঈশ্বরচন্দ্র বিদ্যাসাগরের উক্তি 'ফলবতী বৃক্ষ নত হয়, নত হয় গুণীজন, নত হয় না শুধু শুষ্ক বৃক্ষ আর মূর্খরা'; হেমচন্দ্র বন্দ্যোপাধ্যায়ের উক্তি 'বলো না কাতর স্বরে, বৃথা জন্ম এ সংসারে'।"},{"id":"bangla-135","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"মীর মশাররফ হোসেনের কোন গ্রন্থের উপজীব্য হিন্দু-মুসলমানের বিরোধ?","options":["গো-জীবন","ইসলামের জয়","এর উপায় কী","বসন্তকুমারী নাটক"],"correctIndex":0,"subject":"বাংলা","explanation":"আধুনিক বাংলা মুসলমান সাহিত্যিকদের পথিকৃৎ মীর মশাররফ হোসেন রচিত প্রবন্ধ 'গোজীবন' (১৮৮৯) — মূল বক্তব্য: কৃষিনির্ভর অর্থনীতিতে গো-হত্যা অনুচিত। লেখক ধর্মগ্রন্থ ও প্রাত্যহিক-বাস্তব অভিজ্ঞতা থেকে যুক্তি-তথ্য পরিবেশন করে হিন্দু-মুসলমান উভয় ধর্মাবলম্বীকে ঐক্যবদ্ধ করার মানসে এ প্রবন্ধ রচনা করেন। এটি তৎকালে মুসলিম ধর্মীয় নেতৃস্থানীয়দের মধ্যে প্রতিক্রিয়ার জন্ম দেয়; 'আখবারে এসলামিয়া' (১৮৮৪) পত্রিকা প্রতিবাদ প্রকাশ করে ও লেখককে মামলায় জড়িয়ে পড়তে হয়, শেষে চাপের মুখে তিনি গ্রন্থটি প্রত্যাহার করতে বাধ্য হন। জেনে রাখা ভালো: 'এর উপায় কি?' মীর মশাররফ হোসেন রচিত প্রহসন, 'বসন্তকুমারী' তাঁর রচিত নাটক।"},{"id":"bangla-136","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"রবীন্দ্রনাথ ঠাকুর কত বয়সে ছোটগল্পকার হিসেবে আত্মপ্রকাশ করেন?","options":["১০ বছর","১২ বছর","১৪ বছর","১৬ বছর"],"correctIndex":3,"subject":"বাংলা","explanation":"১২৮৪ বঙ্গাব্দে (১৮৭৭ খ্রিস্টাব্দে) মাত্র ষোলো বছর বয়সে 'ভিখারিনী' গল্প রচনার মাধ্যমে ছোটগল্প লেখক হিসেবে রবীন্দ্রনাথের আত্মপ্রকাশ ঘটে। এরপর জীবনের শেষদিন পর্যন্ত দীর্ঘ চৌষট্টি বছরে তিনি 'গল্পগুচ্ছ'-এ সংকলিত ৯৫টি ছোটগল্প রচনা করেন; এর বাইরেও 'গল্পসল্প', 'লিপিকা', 'সে' গ্রন্থে আরও গল্প সংকলিত হয়েছে। পারিবারিক জমিদারি তদারকির সূত্রে কুষ্টিয়ার শিলাইদহে বসবাসকাল ছিল তাঁর ছোটগল্প রচনার স্বর্ণযুগ। জেনে রাখা ভালো: প্রথম ছোটগল্প 'ভিখারিনি', প্রথম সার্থক ছোটগল্প 'দেনাপাওনা' (১৮৯০), সর্বশেষ গল্প 'মুসলমানীর গল্প'; মোট ছোটগল্প ১১৯টি।"},{"id":"bangla-137","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"নিচের কোনটি বিভূতিভূষণ বন্দ্যোপাধ্যায়ের গল্পগ্রন্থ নয়?","options":["ইছামতি","মেঘমল্লার","মৌরিফুল","যাত্রাবদল"],"correctIndex":0,"subject":"বাংলা","explanation":"বিভূতিভূষণ বন্দ্যোপাধ্যায়ের গল্পগ্রন্থ: মৌরীফুল, যাত্রাদল, মেঘমল্লার। 'ইছামতি' তাঁর রচিত শেষ উপন্যাস, যার জন্য তিনি রবীন্দ্র পুরস্কার (মরণোত্তর) লাভ করেন। জেনে রাখা ভালো: পথের পাঁচালী, অপরাজিত, আরণ্যক, দৃষ্টিপ্রদীপ, অশনি সংকেত, দেবযান, অভিযাত্রিক তাঁর প্রসিদ্ধ উপন্যাস।"},{"id":"bangla-138","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'আমার পথ' প্রবন্ধটি কাজী নজরুল ইসলামের কোন গ্রন্থ থেকে সংকলিত হয়েছে?","options":["যুগ-বাণী","রুদ্র-মঙ্গল","দুর্দিনের যাত্রী","রাজবন্দির জবানবন্দি"],"correctIndex":1,"subject":"বাংলা","explanation":"কাজী নজরুল ইসলাম রচিত প্রবন্ধগ্রন্থ/প্রবন্ধ সংকলন 'রুদ্র-মঙ্গল'-এ মোট ৮টি প্রবন্ধ স্থান পেয়েছে: রুদ্র-মঙ্গল, আমার পথ, মোহররম, বিষবাণী, ক্ষুদিরামের মা, ধূমকেতুর পথ, মন্দির ও মসজিদ, হিন্দু-মুসলমান।"},{"id":"bangla-139","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'জীবন ও বৃক্ষ' প্রবন্ধে মোতাহের হোসেন চৌধুরী কাকে তপোবন-প্রেমিক বলেছেন?","options":["বিভূতিভূষণ বন্দ্যোপাধ্যায়কে","জসীম উদ্‌দীনকে","রবীন্দ্রনাথ ঠাকুরকে","শরৎচন্দ্র চট্টোপাধ্যায়কে"],"correctIndex":2,"subject":"বাংলা","explanation":"'জীবন ও বৃক্ষ' প্রবন্ধে মোতাহের হোসেন চৌধুরী রবীন্দ্রনাথ ঠাকুরকে তপোবন-প্রেমিক বলেছেন — এই প্রবন্ধে বলা হয়েছে, রবীন্দ্রনাথ মনুষ্যত্বের সাদৃশ্য পেয়েছেন নদীর গতির মধ্যে আর অন্তরের সৃষ্টিধর্ম উপলব্ধি করেছেন বৃক্ষের পানে তাকিয়ে।"},{"id":"bangla-140","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'আমি যখন জেলে যাই তখন ওর বয়স মাত্র কয়েক মাস।'—এখানে 'ওর' বলতে শেখ মুজিবুর রহমান কাকে বুঝিয়েছেন?","options":["শেখ নাসেরকে","শেখ কামালকে","শেখ হাসিনাকে","শেখ রেহানাকে"],"correctIndex":1,"subject":"বাংলা","explanation":"চরণটি শেখ মুজিবুর রহমান রচিত 'অসমাপ্ত আত্মজীবনী' গ্রন্থের অন্তর্গত। ১৯৫২ সালের ২১ ফেব্রুয়ারি তিনি জেলখানায় আটক ছিলেন; মুক্তির পর বাসায় ফেরার একদিন সকালে জ্যেষ্ঠ পুত্র শেখ কামাল শেখ হাসিনাকে বলেছিল, 'হাচু আপা, হাচু আপা, তোমার আব্বাকে আমি একটু আব্বা বলি?' তখন শেখ মুজিবুর রহমান কামালকে কোলে নিয়ে বলেন, 'আমি তো তোমারও আব্বা।' অনেকদিন জেলে থাকার কারণে পিতার স্নেহ-মমতা থেকে বঞ্চিত হয়ে কামাল বাবাকে চিনতে পারছিল না — এই প্রসঙ্গে বঙ্গবন্ধু বলেন, 'আমি যখন জেলে যাই তখন ওর বয়স মাত্র কয়েক মাস।'"},{"id":"bangla-141","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"আখতারুজ্জামান ইলিয়াস জন্মগ্রহণ করেন কোথায়?","options":["গাইবান্ধায়","বগুড়ায়","ঢাকায়","সিরাজগঞ্জে"],"correctIndex":0,"subject":"বাংলা","explanation":"আখতারুজ্জামান ইলিয়াসের জন্ম গাইবান্ধা জেলার গোটিয়াগ্রামে (পৈতৃক নিবাস বগুড়া জেলায়)। উপন্যাস: চিলেকোঠার সেপাই (১৯৮৭, তাঁর প্রথম প্রকাশিত উপন্যাস), খোয়াবনামা (তেভাগা আন্দোলনকেন্দ্রিক)। গল্পগ্রন্থ: দুধে ভাতে উৎপাত (প্রথম গল্পগ্রন্থ), অন্য ঘর অন্য স্বর, দোজখের ওম, খোয়ারী, জাল স্বপ্ন, স্বপ্নের জাল। উল্লেখযোগ্য গল্প: রেইনকোট, ফেরারী, মিলির হাতে স্টেনগান, ফোঁড়া, অপঘাত, নিরুদ্দেশ যাত্রা, অসুখ বিসুখ, কীটনাশকের কীর্তি। প্রবন্ধ: সংস্কৃতির ভাঙা সেতু।"},{"id":"bangla-142","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"মাইকেল মধুসূদন দত্ত প্রবর্তিত 'অমিত্রাক্ষর ছন্দ' প্রকৃতপক্ষে বাংলা কোন ছন্দের নব-রূপায়ণ?","options":["স্বরবৃত্ত ছন্দ","অক্ষরবৃত্ত ছন্দ","মাত্রাবৃত্ত ছন্দ","গৈরিশ ছন্দ"],"correctIndex":1,"subject":"বাংলা","explanation":"মধুসূদন-পূর্ব হাজার বছরের বাংলা কবিতার ছন্দ ছিল পয়ার, যেখানে এক চরণের শেষে আরেক চরণের মিল রক্ষা করা অনড় প্রথা ছিল। মধুসূদন প্রথম চরণের সঙ্গে দ্বিতীয় চরণের মিল রক্ষা না করায় তাঁর প্রবর্তিত ছন্দকে বলা হয় 'অমিত্রাক্ষর ছন্দ' — তবে এটি বাংলা অক্ষরবৃত্ত ছন্দেরই নবরূপায়ণ। তাঁর শ্রেষ্ঠতম কীর্তি 'মেঘনাদবধ কাব্যে' এই ছন্দের সফল প্রয়োগ ঘটে; নতুন কিছু বিষয় যোগ করায় একে '১৪ মাত্রার অমিল প্রবহমান যতিস্বাধীন অক্ষরবৃত্ত ছন্দ' বলা হয়। জেনে রাখা ভালো: বাংলা কবিতায় ব্যবহৃত ছন্দ তিন প্রকার — স্বরবৃত্ত (লৌকিক ছন্দ), মাত্রাবৃত্ত (ধ্বনিপ্রধান ছন্দ), অক্ষরবৃত্ত (তানপ্রধান ছন্দ)।"},{"id":"bangla-143","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"\"বুক তার বাংলাদেশের হৃদয়\" কাব্যগ্রন্থের রচয়িতা কে?","options":["সৈয়দ শামসুল হক","শামসুর রাহমান","হাসান হাফিজুর রহমান","আহসান হাবীব"],"correctIndex":1,"subject":"বাংলা","explanation":"নাগরিক কবি শামসুর রাহমানের বিখ্যাত কাব্যগ্রন্থ: 'প্রথম গান দ্বিতীয় মৃত্যুর আগে' (প্রথম কাব্যগ্রন্থ), 'বুক তার বাংলাদেশের হৃদয়', বাংলাদেশ স্বপ্ন দ্যাখে, রৌদ্র করোটিতে, নিজ বাসভূমে, দুঃসময়ের মুখোমুখি, বিধ্বস্ত নীলিমা, বন্দী শিবির থেকে, নিরালোকে দিব্যরথ, ফিরিয়ে নাও ঘাতক কাঁটা, মাতাল ঋত্বিক। অপশন বিশ্লেষণ: সৈয়দ শামসুল হকের কাব্যগ্রন্থ বৈশাখে রচিত পঙ্‌ক্তিমালা, পরানের গহীন ভিতর, আমি জন্মগ্রহণ করিনি; হাসান হাফিজুর রহমানের প্রথম কাব্য বিমুখ প্রান্তর; আহসান হাবীবের প্রথম কাব্যগ্রন্থ রাত্রিশেষ (এর অন্তর্গত বিখ্যাত কবিতা 'সেই অস্ত্র' আসলে 'বিদীর্ণ দর্পণে মুখ'-এর অন্তর্গত)।"},{"id":"bangla-144","exam":"৪৫তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"\"দুর্দিনের দিনলিপি\" স্মৃতিগ্রন্থটি কার লেখা?","options":["আবুল ফজল","আবদুল কাদির","জাহানারা ইমাম","মুশতারি শফী"],"correctIndex":0,"subject":"বাংলা","explanation":"আবুল ফজলের জন্ম ১৯০৩ খ্রিস্টাব্দের ১লা জুলাই, চট্টগ্রামের সাতকানিয়ায়। উপন্যাস: চৌচির, রাঙা প্রভাত। গল্পগ্রন্থ: মাটির পৃথিবী, মৃতের আত্মহত্যা। প্রবন্ধ: সাহিত্য ও সংস্কৃতি সাধনা, সাহিত্য সংস্কৃতি ও জীবন, মানবতন্ত্র, সমাজ সাহিত্য ও রাষ্ট্র, একুশ মানে মাথা নত না করা। দিনলিপি: রেখা চিত্র, দুর্দিনের দিনলিপি। অপশন বিশ্লেষণ: জাহানারা ইমামের স্মৃতিগ্রন্থ একাত্তরের দিনগুলি।"},{"id":"bangla-145","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"শুদ্ধ বানান কোনটি?","options":["মুমুর্ষু","মৃম্মূর্ষূ","মুমূর্ষু","মৃমুর্ষু"],"correctIndex":2,"subject":"বাংলা","explanation":"সঠিক বানান 'মুমূর্ষু'। শব্দটি মনে রাখার শর্টকাট- আগে-পরে উ-কার (ু); মাঝখানে ঊ-কার (ূ)। 'মুমূর্ষু' শব্দটি বিশেষণ পদ। শব্দটির অর্থ- মৃত্যুকাল আসন্ন এমন, মরণাপন্ন, মৃতপ্রায়।"},{"id":"bangla-146","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'ইতরবিশেষ' বলতে বোঝায়-","options":["দুর্বৃত্ত","চালাকি","পার্থক্য","অপদার্থ"],"correctIndex":2,"subject":"বাংলা","explanation":"ইতর (বিশেষণ) শব্দের অর্থ- কল্পিত নিম্নশ্রেণিভুক্ত (ইতর লোক): পশুশ্রেণিভুক্ত (ইতর জীব), নীচ মনোভাবাপন্ন, অধম ইত্যাদি। ইতরবিশেষ অর্থ- পার্থক্য। অপশন বিশ্লেষণ: দুর্বৃত্ত (বিশেষণ) শব্দের অর্থ- দুশ্চরিত্র, অসৎ, উদ্ধত। চালাকি (বিশেষ্য) অর্থ- চাতুরী, চালবাজি, ফন্দি। অপদার্থ (বিশেষণ) অর্থ- অকর্মণ্য, অযোগ্য। জেনে রাখা ভালো: ইতরবিশেষ, উনিশ-বিশ বাগধারা দুটির অর্থও সামান্য পার্থক্য।"},{"id":"bangla-147","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"নিপাতনে সিদ্ধ স্বরসন্ধির দৃষ্টান্ত কোনটি?","options":["গো+অক্ষ = গবাক্ষ","পৌ+অক = পাবক","বি+অঙ্গ = বঙ্গ","যতি+ইন্দ্র = যতীন্দ্র"],"correctIndex":0,"subject":"বাংলা","explanation":"কতগুলো সন্ধি কোনো নিয়ম অনুসারে হয় না, এগুলোকে নিপাতনে সিদ্ধ সন্ধি বলে। গবাক্ষ শব্দটি নিপাতনে সিদ্ধ স্বরসন্ধির উদাহরণ, কারণ স্বরসন্ধির নিয়ম (ও+অ = অব+অ) অনুযায়ী গো+অক্ষ = গবক্ষ না হয়ে গবাক্ষ হয়েছে। অপশন বিশ্লেষণ: পাবক (পৌ+অক) এবং যতীন্দ্র (যতি+ইন্দ্র) স্বরসন্ধির নিয়মে সাধারণভাবে সাধিত; বি+অঙ্গ = বঙ্গ না হয়ে ব্যঙ্গ হবে। অন্যান্য নিপাতনে সিদ্ধ স্বরসন্ধি: কুলটা (কুল+অটা), প্রৌঢ় (প্র+ঊঢ়), অন্যান্য (অন্য+অন্য), গবেন্দ্র (গো+ইন্দ্র), শুদ্ধোদন (শুদ্ধ+ওদন), স্বৈর (স্ব+ঈর)।"},{"id":"bangla-148","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"নিচের কোন বাক্যটি প্রয়োগগত দিক থেকে শুদ্ধ?","options":["আমি কারও সাতেও নেই, সতেরোতেও নেই।","আপনি স্বপরিবারে আমন্ত্রিত","তার দু'চোখ অশ্রুতে ভেসে গেল।","সারা জীবন ভূতের মজুরি খেটে মরলাম।"],"correctIndex":2,"subject":"বাংলা","explanation":"প্রয়োগগত দিক থেকে 'অশ্রুজল' ভুল শব্দ, এর সঠিক রূপ 'অশ্রু'; তাই 'তার দু'চোখ অশ্রুতে ভেসে গেল' বাক্যটি শুদ্ধ। অন্য বাক্যগুলোর শুদ্ধ রূপ: 'আমি কারো সাতেও নেই, পাঁচেও নেই।'; 'আপনি সপরিবারে আমন্ত্রিত।' (স্ব-পরিবারে নয়); 'সারাজীবন ভূতের বেগার খেটে মরলাম।' (মজুরি নয়)।"},{"id":"bangla-149","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"নিচের কোনটি যৌগিক বাক্য?","options":["দোষ স্বীকার করলে তোমাকে শাস্তি দেওয়া হবে না।","তিনি বেড়াতে এসে কেনাকাটা করলেন।","মহৎ মানুষ বলে সবাই তাঁকে সম্মান করেন।","ছেলেটি চঞ্চল তবে মেধাবী।"],"correctIndex":3,"subject":"বাংলা","explanation":"পরস্পর নিরপেক্ষ দুই বা ততোধিক সরল/স্বাধীন বাক্য অব্যয় দ্বারা যুক্ত হয়ে একটি সম্পূর্ণ বাক্য গঠন করলে তাকে যৌগিক বাক্য বলে। 'ছেলেটি চঞ্চল তবে মেধাবী'-তে 'ছেলেটি চঞ্চল' ও 'ছেলেটি মেধাবী' দুটি স্বাধীন বাক্য, আর 'তবে' অব্যয়। সংশ্লিষ্ট টেকনিক: এবং, কিন্তু, অথবা, নতুবা, বরং, তথাপি, অথচ, তবে, সুতরাং ইত্যাদি একাধিক স্বাধীন বাক্যের মাঝে থাকলে বাক্যটি যৌগিক বাক্য হয়। জেনে রাখা ভালো: 'যদি...তবে' থাকলে বাক্যটি মিশ্র/জটিল বাক্য হবে। অপশন (ক), (খ), (গ)-এর বাক্য তিনটি সরল বাক্য।"},{"id":"bangla-150","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"ধ্বনি-পরিবর্তনের নিয়মে কোনটি বর্ণ-বিপর্যয়-এর দৃষ্টান্ত?","options":["রতন","কবাট","পিচাশ","মুলুক"],"correctIndex":2,"subject":"বাংলা","explanation":"শব্দের মধ্যে দুটি ব্যঞ্জনের পরস্পর স্থান পরিবর্তনকে বলে ধ্বনি বিপর্যয় বা বর্ণ বিপর্যয়। পিশাচ > পিচাশ-এ শ, চ পরস্পর স্থান পরিবর্তন করে চ, শ হয়েছে। অনুরূপ: রিকশা > রিশকা, লাফ > ফাল, বাক্স > বাসক। অপশন বিশ্লেষণ: রত্ন > রতন এবং মুলুক > মূলুক মধ্যস্বরাগম/বিপ্রকর্ষ/স্বরভক্তির উদাহরণ; কবাট > কপাট ব্যঞ্জন বিকৃতির উদাহরণ।"},{"id":"bangla-151","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"নিচের কোনটি 'অগ্নি'র সমার্থক শব্দ নয়?","options":["বহ্নি","আবীর","বায়ুসখা","বৈশ্বানর"],"correctIndex":1,"subject":"বাংলা","explanation":"'অগ্নি' শব্দের অর্থ আগুন; এর সমার্থক শব্দ- বহ্নি, বায়ুসখা, বৈশ্বানর, বীতিহোত্র, কৃশানু, অর্চি, পাবক, সর্বভুক, শিখা, দহন, হুতাশন, অনল ইত্যাদি। জেনে রাখা ভালো: 'আবীর' বানানটি অশুদ্ধ, শুদ্ধরূপ 'আবির' (আরবি শব্দ, অর্থ- সুগন্ধি রঞ্জক দ্রব্য/ফাগ), যা অগ্নির সমার্থক নয়।"},{"id":"bangla-152","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'দেশের যত নদীর ধারা জল না, ওরা অশ্রুধারা।'-এই উক্তিটি নিচের কোন পারিভাষিক অলংকার দ্বারা শোভিত?","options":["অপহ্নুতি","যমক","অর্থোন্নতি","অভিযোজন"],"correctIndex":0,"subject":"বাংলা","explanation":"দুটি বিষয়ের মধ্যে তুলনায় উপমেয়কে সম্পূর্ণ অস্বীকার করে উপমানকে স্বীকার/প্রতিষ্ঠা করা হলে অপহ্নুতি অলংকার হয় (অপহ্নুতি অর্থ সত্যের অপলাপ/অস্বীকার)। এই অলংকারে না, নহে, নাই, নয়, নয়তো, নতুবা ইত্যাদি অস্বীকারসূচক শব্দ বা ছল, ছলনা, ছদ্ম প্রভৃতি সত্য-গোপনীয় শব্দ ব্যবহৃত হয়। উদাহরণে 'নদীর ধারা' উপমেয়, 'অশ্রুধারা' উপমান, 'না' অস্বীকারসূচক অব্যয়— উপমেয়কে প্রাধান্য না দিয়ে উপমানকে প্রাধান্য দেওয়া হয়েছে। জেনে রাখা ভালো: অলংকার ২ প্রকার- শব্দালংকার (অনুপ্রাস, যমক, শ্লেষ, বক্রোক্তি, পুনরুক্তবদাভাস) ও অর্থালংকার; অপহ্নুতি অর্থালংকারের অন্তর্গত।"},{"id":"bangla-153","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'যথারীতি' কোন সমাসের দৃষ্টান্ত?","options":["অব্যয়ীভাব","দ্বিগু","বহুব্রীহি","দ্বন্দ্ব"],"correctIndex":0,"subject":"বাংলা","explanation":"পূর্বপদে অব্যয় (যথা, আ, উপ, নির, প্রতি, অনু, হা, গর ইত্যাদি) যোগে নিষ্পন্ন সমাসে অব্যয়ের অর্থের প্রাধান্য থাকলে তাকে অব্যয়ীভাব সমাস বলে। যথারীতি = রীতিকে অতিক্রম না করে (যথা= অনতিক্রম্যতা)। অনুরূপ: যথাসাধ্য, উপকূল (উপ=সামীপ্য), আমরণ (আ=পর্যন্ত), নিরামিষ (নির=অভাব), প্রতিদিন (প্রতি=বীপ্সা), অনুক্ষণ (অনু), হাভাত (হা=অভাব), গরমিল (গর=অভাব)।"},{"id":"bangla-154","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'মৃত্তিকা দিয়ে তৈরি'-কথাটি সংকোচন করলে হবে-","options":["তন্ময়","মন্ময়","মৃন্ময়","চিন্ময়"],"correctIndex":2,"subject":"বাংলা","explanation":"মৃন্ময় শব্দের অর্থ মাটির তৈরি বা মৃত্তিকা দিয়ে তৈরি; এটি তৎসম/সংস্কৃত বিশেষণ পদ, সন্ধিবিচ্ছেদ মৃৎ+ময় (ব্যঞ্জনসন্ধি)। অপশন বিশ্লেষণ: 'তন্ময়' অর্থ একাগ্রচিত্ত/বিভোর; 'চিন্ময়' অর্থ জ্ঞানময়/চৈতন্যস্বরূপ।"},{"id":"bangla-155","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'অর্ধচন্দ্র' কথাটির অর্থ-","options":["অমাবস্যা","গলাধাক্কা দেওয়া","কাচে টানা","কাস্তে"],"correctIndex":1,"subject":"বাংলা","explanation":"অর্ধচন্দ্র (বিশেষ্য) শব্দের আভিধানিক অর্থ অর্ধ প্রকাশিত চন্দ্র, কিন্তু বাগধারা হিসেবে 'অর্ধচন্দ্র'-এর অর্থ গলাধাক্কা দেওয়া। জেনে রাখা ভালো: 'অর্ধচন্দ্র' শব্দটির আরেকটি বিশেষ অর্থ সেনা সমাবেশের কৌশলবিশেষ।"},{"id":"bangla-156","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'হরতাল' কোন ভাষা থেকে আগত শব্দ?","options":["পর্তুগিজ","হিন্দি","গুজরাটি","ফরাসি"],"correctIndex":2,"subject":"বাংলা","explanation":"'হরতাল' (বিশেষ্য) শব্দটি গুজরাটি শব্দ, অর্থ প্রতিবাদ বা শক্তিপ্রদর্শনের উদ্দেশ্যে আহূত ধর্মঘট। জেনে রাখা ভালো: 'খাদি' শব্দটিও গুজরাটি (অর্থ- চরকায় কাটা কার্পাস সুতোয় তৈরি মোটা কাপড়)। পর্তুগিজ শব্দ: আনারস, আলমারি, আলপিন, কেদারা, গামলা, গির্জা, চাবি, পাউরুটি, বোমা। হিন্দি শব্দ: কাহিনি, ঝাণ্ডা, ঝাড়ু, জিলাপি, ঠান্ডা। ফরাসি শব্দ: আঁতাত, ওলন্দাজ, কুপন, ক্যাফে, গ্যারাজ, রেস্তোরাঁ, ম্যাগাজিন।"},{"id":"bangla-157","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"কোনটি 'জিগীষা'র সম্প্রসারিত প্রকাশ?","options":["জানিবার ইচ্ছা","জয় করিবার ইচ্ছা","হনন করিবার ইচ্ছা","যুদ্ধ করিবার ইচ্ছা"],"correctIndex":1,"subject":"বাংলা","explanation":"জিগীষা অর্থ জয় লাভ করিবার ইচ্ছা। ইচ্ছাসম্পর্কিত অন্যান্য এক কথায় প্রকাশ: জিজ্ঞাসা (জানিবার ইচ্ছা), জিঘাংসা (হনন করিবার ইচ্ছা), যুযুৎসা (যুদ্ধ করিবার ইচ্ছা), দিদৃক্ষা (দেখিবার ইচ্ছা), জুগুপ্সা (নিন্দা করার ইচ্ছা), বিবক্ষা (বলার ইচ্ছা), শুশ্রূষা (সেবা করার ইচ্ছা)।"},{"id":"bangla-158","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"নিচের কোনটি তৎসম শব্দ?","options":["পছন্দ","হিসাব","ধূলি","শৌখিন"],"correctIndex":2,"subject":"বাংলা","explanation":"যেসব শব্দ সংস্কৃত থেকে সোজাসুজি অপরিবর্তিতভাবে বাংলায় এসেছে তাদের তৎসম শব্দ বলে (তৎ+সম = তার সমান/সংস্কৃতের সমান)। উদাহরণ: চন্দ্র, সূর্য, ধর্ম, ধূলি, হস্ত, জ্যোৎস্না। সংশ্লিষ্ট টেকনিক: শব্দে ঈ, ঊ, ঋ, ণ, ষ, ঃ ইত্যাদি বর্ণ থাকলে সাধারণত তা তৎসম শব্দ হয়— যেমন ধূলি-তে ঊ-কার। অপশন বিশ্লেষণ: পছন্দ ফারসি শব্দ; হিসাব ও শৌখিন আরবি শব্দ।"},{"id":"bangla-159","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"নিচের কোনটি বাংলা 'ধাতু'র দৃষ্টান্ত?","options":["কহ্","কথ্","বুধ্","গঠ্"],"correctIndex":0,"subject":"বাংলা","explanation":"যেসব ধাতু সংস্কৃত থেকে পরিবর্তিত হয়ে বাংলায় এসেছে সেগুলো বাংলা ধাতু। সংস্কৃত ধাতু 'কথ্' পরিবর্তিত হয়ে বাংলা ধাতু 'কহ্' হয়েছে। অনুরূপ রূপান্তর: স্থা→থাক্, পঠ্→পড়্, দৃশ্→দেখ্, ক্রন্দ্→কাঁদ্, কৃ→কর্, খাদ্→খা, কৃৎ→কাঁট্, অঙ্ক→আঁক্, গঠ্→গড়্, বুধ্→বুঝ্, রক্ষ্→রাখ্। অপশন (খ), (গ), (ঘ)-এ থাকা কথ্, বুধ্, গঠ্ নিজেরাই মূল সংস্কৃত ধাতু, বাংলা ধাতু নয়।"},{"id":"bangla-160","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"ইসলাম ও সুফিমতের প্রভাবে ভারতবর্ষে ঘটেছিল-","options":["বর্ণবাদের পুনরুত্থান","রাষ্ট্রবিপ্লব","চিন্তাবিপ্লব","অভিবাসন বিপ্লব"],"correctIndex":2,"subject":"বাংলা","explanation":"ইসলামের আবির্ভাব ও সুফিমতের প্রভাবে ভারতীয় উপমহাদেশে চিন্তাবিপ্লব তথা মানুষের চেতনার জগৎ উন্মুক্ত হয়। সুফিবাদ ইসলামি আধ্যাত্মিক দর্শন, যার মুখ্য বিষয় আত্মা সম্পর্কিত আলোচনা; সুফিরা প্রেম-ভ্রাতৃত্ব-সাম্যের বাণী প্রচার করে সাধারণ মানুষের মন জয় করেন। সুফিসাহিত্য মধ্যযুগীয় বাংলা সাহিত্যের একটি বিশেষ ধারা, যেখানে ফারসি-হিন্দি সুফিসাহিত্য বাংলায় অনূদিত হয়— যেমন শাহ মুহম্মদ সগীরের 'ইউসুফ-জোলেখা', দৌলত উজির বাহরাম খানের 'লাইলী-মজনু', আলাওলের 'পদ্মাবতী'।"},{"id":"bangla-161","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'চণ্ডীমঙ্গল' কাব্যের উপাস্য 'চণ্ডী' কার স্ত্রী?","options":["জগন্নাথ","বিষ্ণু","প্রজাপতি","শিব"],"correctIndex":3,"subject":"বাংলা","explanation":"চণ্ডীমঙ্গল কাব্যের উপাস্য (পূজিত) 'চণ্ডী' (দেবী দুর্গা) ছিলেন শিবের (মহাদেব, শৈব সম্প্রদায়ের প্রধান দেবতা) স্ত্রী। মঙ্গলকাব্য ধারার শ্রেষ্ঠ কাব্য এটি; দেবী চণ্ডীর গুণকীর্তন ও পূজার প্রসারই এর মূল উপজীব্য। জেনে রাখা ভালো: চণ্ডীমঙ্গল কাব্যের আদিকবি মানিক দত্ত, প্রধান/শ্রেষ্ঠ কবি মুকুন্দরাম চক্রবর্তী। অপশন বিশ্লেষণ: জগন্নাথ হিন্দু দেবতা বিষ্ণু/কৃষ্ণের বিশেষ রূপ; প্রজাপতি (ব্রহ্মা) বিয়ের দেবতা বলে পরিচিত।"},{"id":"bangla-162","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'শ্রীকৃষ্ণকীর্তন কাব্য' কোথা থেকে উদ্ধার করা হয়েছিল?","options":["নেপালের রাজদরবার থেকে","গোয়ালঘর থেকে","পাঠশালা থেকে","কান্তজীর মন্দির থেকে"],"correctIndex":1,"subject":"বাংলা","explanation":"শ্রী বসন্তরঞ্জন রায় বিদ্বদ্বল্লভ ১৯০৯ সালে (১৩১৬ বঙ্গাব্দ) বাঁকুড়া জেলার বনবিষ্ণুপুরের কাঁকিল্যা গ্রামের এক গৃহস্থের গোয়ালঘর থেকে 'শ্রীকৃষ্ণকীর্তন কাব্য' আবিষ্কার করেন। ১৯১৬ সালে তাঁরই সম্পাদনায় বঙ্গীয় সাহিত্য পরিষদ থেকে এটি গ্রন্থাকারে প্রকাশিত হয়; 'শ্রীকৃষ্ণকীর্তন' নামটিও বসন্তরঞ্জন রায়েরই দেওয়া। উল্লেখ্য, প্রাপ্ত কাব্যটির প্রথম ও শেষাংশ খণ্ডিত ছিল বলে মূল নাম ও কবির প্রকৃত পরিচয় জানা যায়নি, তবে পুঁথিতে প্রাপ্ত একটি চিরকুট অনুসারে কাব্যের নাম শ্রীকৃষ্ণসন্দর্ভ।"},{"id":"bangla-163","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"বিদ্যাপতি মূলত কোন ভাষার কবি ছিলেন?","options":["মারাঠি","হিন্দি","মৈথিলি","গুজরাটি"],"correctIndex":2,"subject":"বাংলা","explanation":"বিদ্যাপতি মৈথিলী, অবহট্ঠ ও সংস্কৃত ভাষায় বহু গ্রন্থ ও পদ রচনা করেন; শৈব বংশে জন্ম বলে বহু শৈবসঙ্গীতও রচনা করেন। তবে ব্রজবুলি (বাংলা ও মৈথিলীর মিশ্রণ) ভাষায় রচিত বৈষ্ণব পদাবলি (রাধাকৃষ্ণবিষয়ক পদ) তাঁর শ্রেষ্ঠ কীর্তি; তিনি বৈষ্ণব পদাবলির শ্রেষ্ঠ অবাঙালি কবি, উপাধি 'মৈথিলি কোকিল'। জন্ম মিথিলার সীতামারী মহকুমার বিসফি গ্রামে শৈব ব্রাহ্মণ পরিবারে; মিথিলারাজ দেবসিংহ ও শিবসিংহের সভাসদ ছিলেন, রাজা শিবসিংহ তাঁকে 'কবি কণ্ঠহার' উপাধি দেন। উল্লেখযোগ্য গ্রন্থ: পুরুষপরীক্ষা, কীর্তিলতা, লিখনাবলী, কীর্তিপতাকা।"},{"id":"bangla-164","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'আমার সন্তান যেন থাকে দুধেভাতে।'-এই মনোবাঞ্ছাটি কার?","options":["ভবানন্দের","ভাঁড়ুদত্তের","ঈশ্বরী পাটুনীর","ফুল্লরার"],"correctIndex":2,"subject":"বাংলা","explanation":"মধ্যযুগের (আঠারো শতকের) শ্রেষ্ঠ কবি ভারতচন্দ্র রায় গুণাকর রচিত অন্নদামঙ্গল কাব্যের বিখ্যাত পঙ্‌ক্তি 'আমার সন্তান যেন থাকে দুধে ভাতে'- প্রার্থনাটি ঈশ্বরী পাটনীর (পাটনী অর্থ মাঝি); এতে সন্তানের মঙ্গল কামনার বিষয়টি ফুটে উঠেছে। অপশন বিশ্লেষণ: ভবানন্দ অন্নদামঙ্গল কাব্যেরই একটি চরিত্র; ভাঁড়ুদত্ত ও ফুল্লরা চণ্ডীমঙ্গল কাব্যের চরিত্র (ভাঁড়ুদত্তকে বলা হয় বাংলা সাহিত্যের প্রথম ঠগ চরিত্র, ফুল্লরা মধ্যযুগের সবচেয়ে প্রতিবাদী নারী চরিত্র)।"},{"id":"bangla-165","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"নিচের কোন ব্যক্তি 'বুদ্ধির মুক্তি' আন্দোলনের সঙ্গে যুক্ত ছিলেন না?","options":["কাজী আবদুল ওদুদ","এস ওয়াজেদ আলি","আবুল ফজল","আবদুল কাদির"],"correctIndex":1,"subject":"বাংলা","explanation":"১৯২৬ সালে অধ্যাপক আবুল হোসেনের নেতৃত্বে ও ড. মুহম্মদ শহীদুল্লাহর সভাপতিত্বে ঢাকায় 'মুসলিম সাহিত্য সমাজ' প্রতিষ্ঠিত হয়; এই সংগঠনের ধর্মীয়-সামাজিক কুসংস্কারবিরোধী প্রগতিশীল আন্দোলনই 'বুদ্ধির মুক্তি আন্দোলন' নামে পরিচিত। এর সাথে যুক্ত ছিলেন আবুল হোসেন, কাজী মোতাহার হোসেন, কাজী আব্দুল ওদুদ, আবুল ফজল, আব্দুল কাদির, আনোয়ারুল কাদির প্রমুখ। এস ওয়াজেদ আলী এই আন্দোলনের সাথে যুক্ত ছিলেন না।"},{"id":"bangla-166","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'মনোরমা' বঙ্কিমচন্দ্রের কোন উপন্যাসের চরিত্র?","options":["কৃষ্ণকান্তের উইল","দুর্গেশনন্দিনী","মৃণালিনী","বিষবৃক্ষ"],"correctIndex":2,"subject":"বাংলা","explanation":"বাংলা উপন্যাসের জনক বঙ্কিমচন্দ্র চট্টোপাধ্যায় রচিত ঐতিহাসিক পটভূমির উপন্যাস 'মৃণালিনী'-তে মুসলমান কর্তৃক বঙ্গদেশ বিজয়ের কাহিনি বর্ণিত; এর চরিত্র মনোরমা, হেমচন্দ্র, মৃণালিনী, পশুপতি। অপশন বিশ্লেষণ: 'কৃষ্ণকান্তের উইল'-এর চরিত্র রোহিণী, গোবিন্দলাল, ভ্রমর; 'দুর্গেশনন্দিনী'-র চরিত্র বিমলা, আয়েশা, জগৎসিংহ, তিলোত্তমা; 'বিষবৃক্ষ'-এর চরিত্র কুন্দনন্দিনী, নগেন্দ্রনাথ, সূর্যমুখী।"},{"id":"bangla-167","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'ব্যক্ত প্রেম' ও 'গুপ্ত প্রেম' কবিতা দুটি রবীন্দ্রনাথের কোন কাব্যগ্রন্থের অন্তর্গত?","options":["খেয়া","মানসী","কল্পনা","সোনার তরী"],"correctIndex":1,"subject":"বাংলা","explanation":"রবীন্দ্রনাথ ঠাকুরের কাব্যকলার পূর্ণপ্রতিষ্ঠামূলক কাব্যগ্রন্থ 'মানসী' (১৮৯০)-এর বিখ্যাত কবিতা: ব্যক্ত প্রেম, গুপ্ত প্রেম, অনন্ত প্রেম, উপহার, শেষ উপহার, আগন্তুক, নিষ্ফল কামনা, মেঘদূত। অপশন বিশ্লেষণ: 'খেয়া'-র কবিতা- খেয়া, শেষ খেয়া, ঘাটের পথ; 'কল্পনা'-র কবিতা- জুতা আবিষ্কার, প্রার্থী, জগদীশচন্দ্র বসু; 'সোনার তরী'-র কবিতা- সোনার তরী, নিরুদ্দেশ যাত্রা, বর্ষাযাপন।"},{"id":"bangla-168","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'অভীক' রবীন্দ্রনাথের কোন গল্পের নায়ক?","options":["নষ্টনীড়","নামঞ্জুর গল্প","রবিবার","ল্যাবরেটরি"],"correctIndex":2,"subject":"বাংলা","explanation":"রবীন্দ্রনাথ ঠাকুরকে বলা হয় বাংলা ছোটগল্পের জনক; তাঁর প্রথম প্রকাশিত ছোটগল্প 'ভিখারিনি', মোট ছোটগল্প ১১৯টি। 'রবিবার' ছোটগল্পের উল্লেখযোগ্য চরিত্র অভীক কুমার (অভয়চরণ) ও বিভা। অপশন বিশ্লেষণ: 'নষ্টনীড়'-এর চরিত্র চারুলতা, ভূপতি, মন্দাকিনী; 'নামঞ্জুর'-এর চরিত্র অমিয়া, গিরিবালা; 'ল্যাবরেটরি'-র চরিত্র সোহিনী, নন্দকিশোর। জেনে রাখা ভালো: রবিবার, শেষকথা, ল্যাবরেটরি- এই তিনটি গল্প রবীন্দ্রনাথের 'তিন সঙ্গী' সংকলনের অন্তর্ভুক্ত।"},{"id":"bangla-169","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'সকলের তরে সকলে আমরা/ প্রত্যেকে আমরা পরের তরে।'-কার রচিত পঙ্‌ক্তি?","options":["রজনীকান্ত সেন","ইসমাইল হোসেন সিরাজী","কামিনী রায়","দ্বিজেন্দ্রলাল রায়"],"correctIndex":2,"subject":"বাংলা","explanation":"চরণ দুটি কামিনী রায়ের 'সুখ' কবিতার অংশবিশেষ, যা তাঁর প্রথম কাব্যগ্রন্থ 'আলো ও ছায়া'-র অন্তর্গত (মাত্র ১৫ বছর বয়সে রচিত, ভূমিকা লেখেন হেমচন্দ্র বন্দ্যোপাধ্যায়)। কবি ও সমাজকর্মী কামিনী রায়ের অন্যান্য রচনা: মাল্য ও নির্মাল্য, অশোক সঙ্গীত, দীপ ও ধুপ। অপশন বিশ্লেষণ: রজনীকান্ত সেনের উক্তি 'বাবুই পাখিরে ডাকি বলিছে চড়াই...'; দ্বিজেন্দ্রলাল রায়ের উক্তি 'ধন ধান্য পুষ্পে ভরা আমাদের এই বসুন্ধরা'।"},{"id":"bangla-170","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'খোকা' ও 'রঞ্জু' মাহমুদুল হক-এর কোন উপন্যাসের চরিত্র?","options":["কালো বরফ","খেলাঘর","অনুর পাঠশালা","জীবন আমার বোন"],"correctIndex":3,"subject":"বাংলা","explanation":"কথাশিল্পী মাহমুদুল হকের মুক্তিযুদ্ধভিত্তিক বিখ্যাত উপন্যাস 'জীবন আমার বোন' (১৯৭৬)-এ নগরজীবনের পটভূমিতে খোকা, রঞ্জু, মুরাদ, রহমান চরিত্রগুলো এসেছে। জেনে রাখা ভালো: মাহমুদুল হকের প্রথম প্রকাশিত উপন্যাস 'অনুর পাঠশালা' (চরিত্র অনু, মিয়াচান, ফকিরা), যদিও প্রথম লেখা উপন্যাস 'দ্রৌপদীর আকাশে পাখি'; 'কালো বরফ' দেশবিভাগের পটভূমিতে (চরিত্র আব্দুল খালেক, মালেক), 'খেলাঘর' মুক্তিযুদ্ধের পটভূমিতে (চরিত্র মুকুল, রেহানা, ইয়াকুব)।"},{"id":"bangla-171","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"সৈয়দ ওয়ালীউল্লাহর লেখা নাটক কোনটি?","options":["কবর","বহিপীর","পায়ের আওয়াজ পাওয়া যায়","ওরা কদম আলী"],"correctIndex":1,"subject":"বাংলা","explanation":"সৈয়দ ওয়ালীউল্লাহ রচিত বিখ্যাত নাটক 'বহিপীর' (১৯৬০, ঢাকা থেকে প্রকাশিত); চরিত্র বহিপীর, তাহেরা, হাশেম, হকিকুল্লাহ। অপশন বিশ্লেষণ: 'কবর' নাটকের রচয়িতা মুনীর চৌধুরী; 'পায়ের আওয়াজ পাওয়া যায়'-এর রচয়িতা সৈয়দ শামসুল হক; 'ওরা কদম আলী'-র রচয়িতা মামুনুর রশীদ।"},{"id":"bangla-172","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"মীর মশাররফ হোসেনের 'বিষাদসিন্ধু' একটি-","options":["মহাকাব্য","ইতিহাস গ্রন্থ","উপন্যাস","ইতিহাস-আশ্রিত জীবনীগ্রন্থ"],"correctIndex":2,"subject":"বাংলা","explanation":"মীর মশাররফ হোসেন রচিত 'বিষাদ সিন্ধু' মূলত ইতিহাস-আশ্রিত উপন্যাস; কারবালার বিষাদময় ঘটনা এর মূল উপজীব্য। জেনে রাখা ভালো: তাঁর অন্যান্য উপন্যাস- রত্নবতী (বাঙালি মুসলমান রচিত প্রথম উপন্যাস), গাজী মিয়াঁর বস্তানী (আত্মজীবনীমূলক), উদাসীন পথিকের মনের কথা (আত্মজীবনীমূলক), বাঁধাখাতা, নিয়তি কি অবনতি।"},{"id":"bangla-173","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'চাঁদের অমাবস্যা' উপন্যাসের যুবক-শিক্ষকের নাম-","options":["আবদুল কাদের","খতিব মিয়া","আক্কাস আলী","আরেফ আলী"],"correctIndex":3,"subject":"বাংলা","explanation":"সৈয়দ ওয়ালীউল্লাহ রচিত 'চাঁদের অমাবস্যা' উপন্যাসের কেন্দ্রীয় চরিত্র যুবক শিক্ষক আরেফ আলী; অন্যান্য চরিত্র কাদের (দরবেশ নামে খ্যাত) ও দাদা সাহেব (আলফাজ উদ্দিন, কাদেরের বড় ভাই)। জেনে রাখা ভালো: সৈয়দ ওয়ালীউল্লাহর অন্যান্য উপন্যাস- লালসালু (চরিত্র মজিদ, রহিমা, জমিলা), কাঁদো নদী কাঁদো (চরিত্র মোস্তফা, কফিল উদ্দিন, সখিনা), এবং ইংরেজিতে রচিত The Ugly Asian।"},{"id":"bangla-174","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'মরণ রে তুঁহু মম শ্যাম সমান।'-পঙ্‌ক্তিটির রচয়িতা-","options":["বিদ্যাপতি","গোবিন্দদাস","রবীন্দ্রনাথ ঠাকুর","কৃষ্ণদাস কবিরাজ"],"correctIndex":2,"subject":"বাংলা","explanation":"'মরণ রে তুঁহু মম শ্যাম সমান' চরণটি রবীন্দ্রনাথ ঠাকুরের 'ভানুসিংহ ঠাকুরের পদাবলী' কাব্যের অন্তর্গত। রবীন্দ্রনাথ কৈশোরে ও প্রথম যৌবনে 'ভানুসিংহ' ছদ্মনামে বৈষ্ণব কবিদের অনুকরণে ব্রজবুলি ভাষায় কিছু পদ রচনা করেন, যা ১৮৮৪ সালে 'ভানুসিংহ ঠাকুরের পদাবলী' নামে প্রকাশিত হয়। অপশন বিশ্লেষণ: বিদ্যাপতির উক্তি 'এ সখি হামারি দুখের নাহি ওর'; গোবিন্দদাসের উক্তি 'মন্দির বাহির কঠিন কপাট'।"},{"id":"bangla-175","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'আনোয়ারা' উপন্যাসের রচয়িতার নাম-","options":["সৈয়দ মুজতবা আলী","কাজী আবদুল ওদুদ","নজিবর রহমান","রোকেয়া সাখাওয়াত হোসেন"],"correctIndex":2,"subject":"বাংলা","explanation":"'আনোয়ারা' (১৯১৪) বাঙালি ঔপন্যাসিক মোহাম্মদ নজিবর রহমান সাহিত্যরত্ন রচিত কালজয়ী সামাজিক উপন্যাস, তাঁর প্রথম ও জনপ্রিয় রচনা। গ্রামীণ সমাজের পটভূমিতে বাঙালি মুসলমান সম্প্রদায়ের পারিবারিক-সামাজিক চিত্র এতে প্রকাশিত; মূল চরিত্র আনোয়ারা ও নুরুল এসলাম। জেনে রাখা ভালো: নজিবর রহমানের অন্যান্য উপন্যাস- প্রেমের সমাধি, গরীবের মেয়ে, মেহেরুন্নিসা। অপশন বিশ্লেষণ: সৈয়দ মুজতবা আলীর উপন্যাস অবিশ্বাস্য, শবনম; কাজী আবদুল ওদুদের উপন্যাস নদীবক্ষে; বেগম রোকেয়ার উপন্যাস পদ্মরাগ ও Sultana's Dream।"},{"id":"bangla-176","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"নিচের কোন কাব্য কাজী নজরুল ইসলামের উদারনৈতিক ঐতিহ্যভাবনার ধারক?","options":["বিষের বাঁশী","অগ্নি-বীণা","সিন্ধু-হিন্দোল","চক্রবাক"],"correctIndex":1,"subject":"বাংলা","explanation":"কাজী নজরুল ইসলাম রচিত 'অগ্নি-বীণা' (১৯২২) কাব্যগ্রন্থে মোট ১২টি কবিতা আছে, যার সবগুলোই হিন্দু-মুসলিম ঐতিহ্যভিত্তিক- মুসলিম ঐতিহ্যের কামাল পাশা, রণ-ভেরী, মোহররম এবং হিন্দু ঐতিহ্যের বিদ্রোহী, ধূমকেতু, প্রলয়োল্লাস, রক্তাম্বরধারিণী মা। উভয় ধর্মের ঐতিহ্য একই কাব্যে থাকায় একে নজরুলের উদারনৈতিক ঐতিহ্যভাবনার ধারক বলা হয়। অপশন বিশ্লেষণ: 'বিষের বাঁশি' বিদ্রোহাত্মক ও জাতিজাগরণমূলক; 'সিন্ধু-হিন্দোল' ও 'চক্রবাক' নজরুলের প্রেমপ্রধান কাব্য। জেনে রাখা ভালো: অগ্নি-বীণার প্রথম কবিতা প্রলয়োল্লাস, দ্বিতীয় বিদ্রোহী, সর্বশেষ মোহররম।"},{"id":"bangla-177","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"নিচের কোনটি বিশ শতকের পত্রিকা?","options":["শনিবারের চিঠি","বঙ্গদর্শন","তত্ত্ববোধিনী","সংবাদ প্রভাকর"],"correctIndex":0,"subject":"বাংলা","explanation":"স্যাটায়ারধর্মী সাহিত্য পত্রিকা 'শনিবারের চিঠি' প্রথম প্রকাশিত হয় ১৯২৪ সালে (বিংশ শতাব্দী); বাকি তিনটি পত্রিকা উনিশ শতকের- বঙ্গদর্শন (১৮৭২, সম্পাদক বঙ্কিমচন্দ্র চট্টোপাধ্যায়), তত্ত্ববোধিনী (১৮৪৩, সম্পাদক অক্ষয়কুমার দত্ত), সংবাদ প্রভাকর (১৮৩১, সম্পাদক ঈশ্বরচন্দ্র গুপ্ত)। 'শনিবারের চিঠি'র প্রথম সম্পাদক-প্রকাশক-মুদ্রাকার যোগানন্দ দাস, পরবর্তীতে সম্পাদক হন সজনীকান্ত দাস।"},{"id":"bangla-178","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"নিচের কোনটি উপন্যাস নয়?","options":["দিবারাত্রির কাব্য","শেষের কবিতা","পল্লী-সমাজ","কবিতার কথা"],"correctIndex":3,"subject":"বাংলা","explanation":"'কবিতার কথা' জীবনানন্দ দাশের প্রথম প্রবন্ধগ্রন্থ (মননশীল ও নন্দনভাবনামূলক), তাঁর মৃত্যুর পর ১৯৫৫ সালে প্রথম প্রকাশিত হয়; এটি উপন্যাস নয়। বাকি তিনটি উপন্যাস: 'দিবারাত্রির কাব্য' (মানিক বন্দ্যোপাধ্যায়, চরিত্র হেরম্ব, আনন্দ, মালতী), 'শেষের কবিতা' (রবীন্দ্রনাথ ঠাকুর, চরিত্র অমিত, লাবণ্য), 'পল্লীসমাজ' (শরৎচন্দ্র চট্টোপাধ্যায়, চরিত্র রমা, রমেশ, বেণী)।"},{"id":"bangla-179","exam":"৪৪তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'বাঙালী ও বাঙলা সাহিত্য' গ্রন্থ কে রচনা করেছেন?","options":["দীনেশচন্দ্র সেন","গোপাল হালদার","আহমদ শরীফ","সুকুমার সেন"],"correctIndex":2,"subject":"বাংলা","explanation":"ঢাকা বিশ্ববিদ্যালয়ের বাংলা বিভাগের অধ্যাপক আহমদ শরীফ রচিত 'বাঙালী ও বাঙলা সাহিত্য' (দুই খণ্ড, ১৯৭৮ ও ১৯৮৩) মধ্যযুগের বাংলা সাহিত্যের পূর্ণাঙ্গ ইতিহাসগ্রন্থের মর্যাদা লাভ করেছে; এটি তাঁর শ্রেষ্ঠ রচনা। জেনে রাখা ভালো: আহমদ শরীফ সম্পাদিত দৌলত উজির বাহরাম খানের 'লায়লীমজনু' বাংলা একাডেমির প্রথম প্রকাশিত গ্রন্থ; ঢাকা বিশ্ববিদ্যালয়ের বাংলা বিভাগেরও প্রথম প্রকাশিত গ্রন্থ তাঁরই সম্পাদিত 'পুঁথি পরিচিতি'। অপশন বিশ্লেষণ: দীনেশচন্দ্র সেনের গ্রন্থ 'বঙ্গভাষা ও সাহিত্য' (বাংলা সাহিত্যের প্রথম ইতিহাসগ্রন্থ); গোপাল হালদারের 'বাংলা সাহিত্যের রূপ-রেখা'; সুকুমার সেনের 'বাংলা সাহিত্যের কথা', 'বাঙলা সাহিত্যের ইতিহাস'।"},{"id":"bangla-180","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'আসমান' কোন ভাষা থেকে আগত শব্দ?","options":["পর্তুগিজ","ফরাসি","আরবি","ফারসি"],"correctIndex":3,"subject":"বাংলা","explanation":"'আসমান' (অর্থ- আকাশ) শব্দটি ফারসি ভাষা থেকে আগত। অন্যান্য উল্লেখযোগ্য ফারসি শব্দ- খোদা, বেহেশত, দোযখ, নামায, রোযা, পয়গম্বর, ফেরেশতা, গুনাহ, দোকান, দারোগা, জানোয়ার, আমদানি, রপ্তানি, বদমাশ, নমুনা, চশমা, চাকর, সরকার, একতারা। অপশন বিশ্লেষণ: পর্তুগিজ শব্দ- আনারস, আলমারি, আলপিন, ইস্পাত, জানালা, গুদাম, চাবি, পাউরুটি, বালতি, সাবান; ফরাসি শব্দ- আঁতাত, ওলন্দাজ, কুপন, ক্যাফে, গ্যারেজ, ডিপো, বুর্জোয়া, রেস্তোরাঁ, রেনেসাঁ; আরবি শব্দ- আল্লাহ, আদালত, উকিল, এজলাস, কলম, কানুন, তারিখ, মামলা, শরবত, হারাম, হালাল।"},{"id":"bangla-181","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"নিম্নবিবৃত স্বরধ্বনি কোনটি?","options":["আ","ই","এ","অ্যা"],"correctIndex":0,"subject":"বাংলা","explanation":"জিভের উচ্চতা ও ঠোঁটের উন্মুক্তি অনুযায়ী স্বরধ্বনির শ্রেণিবিভাগে 'আ' নিম্ন, বিবৃত স্বরধ্বনি (জিভ সবচেয়ে নিচে থাকে, ঠোঁট সবচেয়ে বেশি খোলে)। অপশন বিশ্লেষণ: 'ই' উচ্চ সম্মুখ স্বরধ্বনি; 'এ' উচ্চ-মধ্য সম্মুখ স্বরধ্বনি; 'অ্যা' নিম্ন-মধ্য সম্মুখ স্বরধ্বনি।"},{"id":"bangla-182","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'জিজীবিষা' শব্দটির অর্থ কী?","options":["জীবননাশের ইচ্ছা","বেঁচে থাকার ইচ্ছা","জীবনকে জানার ইচ্ছা","জীবন-জীবিকার পথ"],"correctIndex":1,"subject":"বাংলা","explanation":"'জিজীবিষা' (√জীব্‌+সন্‌+অ+আ) শব্দের অর্থ বেঁচে থাকার ইচ্ছা। একই ধাঁচের (ইচ্ছার্থক সন্‌ প্রত্যয়যোগে গঠিত) অন্যান্য শব্দ- শুশ্রূষা (সেবা করার ইচ্ছা), চিকীর্ষা (করার ইচ্ছা), অনুচিকীর্ষা (অনুকরণ করার ইচ্ছা), জিগীষা (জয় করার ইচ্ছা), জিঘাংসা (হনন করার ইচ্ছা)।"},{"id":"bangla-183","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"বড় > বড্ড-এটি কোন ধরনের পরিবর্তন?","options":["বিষমীভবন","সমীভবন","ব্যঞ্জনদ্বিত্ব","ব্যঞ্জন-বিকৃতি"],"correctIndex":2,"subject":"বাংলা","explanation":"কখনো কখনো জোর দেওয়ার জন্য শব্দের অন্তর্গত ব্যঞ্জনের দ্বিত্ব উচ্চারণ হয়, একে দ্বিত্ব ব্যঞ্জন বা ব্যঞ্জনদ্বিত্ব বলে। যেমন- বড় > বড্ড, পাকা > পাক্কা, সকাল > সক্কাল, ছোট > ছোট্ট। (ট-বর্গের তৃতীয় ব্যঞ্জনবর্ণ 'ড' বাংলায় শব্দের মাঝে/শেষে 'ড়' রূপ নেয়, তাই 'বড়'-এর 'ড়' মূলত 'ড'-এরই রূপ।) অপশন বিশ্লেষণ: বিষমীভবন- দুটি সমবর্ণের একটি পরিবর্তিত হওয়া (শরীর>শরীল, লাল>নাল, মর্মর>মারবেল); সমীভবন- শব্দমধ্যস্থ দুটি ভিন্ন ধ্বনি একে অপরের প্রভাবে সমতা লাভ করা (জন্ম>জম্ম, কাঁদনা>কান্না); ব্যঞ্জন বিকৃতি- কোনো ব্যঞ্জন পরিবর্তিত হয়ে নতুন ব্যঞ্জনে রূপ নেওয়া (কবাট>কপাট, ধাইমা>দাইমা)।"},{"id":"bangla-184","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'সপ্তকাণ্ড রামায়ণ' বাগধারার অর্থ কী?","options":["রামায়ণের সাত পর্ব","রামায়ণে বর্ণিত বৃক্ষ","রামায়ণে বর্ণিত সাতটি সমুদ্র","বৃহৎ বিষয়"],"correctIndex":3,"subject":"বাংলা","explanation":"'সপ্তকাণ্ড রামায়ণ' বাগ্‌ধারাটির অর্থ বৃহৎ/বিরাট বিষয়, যদিও আক্ষরিকভাবে এটি রামায়ণের সাতটি কাণ্ড/পর্বকে নির্দেশ করে। সংখ্যাবাচক অন্যান্য বাগ্‌ধারা- একগুঁয়ে (অবাধ্য), একচোখা/একপেশে (পক্ষপাতদুষ্ট), পঞ্চত্বপ্রাপ্তি (মারা যাওয়া), পঞ্চমুখ (প্রশংসামুখর), ত্রিশঙ্কু অবস্থা (দোটানা অবস্থা), সাত সতেরো (বিচিত্র রকমের), বারো সতেরো (খুঁটিনাটি), ষোল আনা (সম্পূর্ণ), নবমী দশা (মূর্ছা), উনপঞ্চাশ বায়ু (পাগলামি), উনকোটি চৌষট্টি (প্রায় সম্পূর্ণ), নিরানব্বইয়ের ধাক্কা (সঞ্চয়ের প্রবৃত্তি)।"},{"id":"bangla-185","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'Attested' শব্দের বাংলা পরিভাষা কী?","options":["প্রত্যায়িত","সত্যায়িত","প্রতারিত","সত্যয়িত"],"correctIndex":1,"subject":"বাংলা","explanation":"বাংলা একাডেমি প্রশাসনিক পরিভাষা অনুযায়ী Attested শব্দের বাংলা পরিভাষা সত্যায়িত, আর Certified শব্দের পরিভাষা প্রত্যায়িত। অন্যান্য প্রশাসনিক পরিভাষা- Copyright (গ্রন্থস্বত্ব), Excise duty (আবগারি শুল্ক), Isolation (বিচ্ছিন্ন), Lien (পূর্বস্বত্ব), Octroi duty (নগর শুল্ক), Quarantine (সঙ্গরোধ), Revenue (রাজস্ব), Tariff (শুল্ক), Tenancy (প্রজাস্বত্ব)।"},{"id":"bangla-186","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'ডেকে ডেকে হয়রান হচ্ছি।'-এ বাক্যে 'ডেকে ডেকে' কোন অর্থ প্রকাশ করে?","options":["অসহায়ত্ব","বিরক্তি","কালের বিস্তার","পৌনঃপুনিকতা"],"correctIndex":3,"subject":"বাংলা","explanation":"দ্বিরুক্ত শব্দ (একই শব্দের পুনরাবৃত্তি) বিভিন্ন অর্থ প্রকাশ করতে পারে; 'ডেকে ডেকে হয়রান হচ্ছি।' বাক্যে 'ডেকে ডেকে' পৌনঃপুনিকতা (বার বার ঘটার ভাব) প্রকাশ করছে, যেমন- 'বার বার সে কামান গর্জে উঠল'। অপশন বিশ্লেষণ: বিরক্তি অর্থ প্রকাশের উদাহরণ- 'ছি ছি, তুমি এত নীচ!'; কালের বিস্তার প্রকাশের উদাহরণ- 'থেকে থেকে শিশুটি কাঁদছে।'"},{"id":"bangla-187","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"ভুল বানান কোনটি?","options":["ভূবন","অন্তঃসার","মুহূর্ত","অদ্ভুত"],"correctIndex":0,"subject":"বাংলা","explanation":"'ভূবন' বানানটি ভুল; শুদ্ধ বানান 'ভুবন' (হ্রস্ব উ-কার)। অপশনের অন্তঃসার, মুহূর্ত, অদ্ভুত বানানগুলো ইতিমধ্যে শুদ্ধ অবস্থায় আছে। কিছু গুরুত্বপূর্ণ শুদ্ধ বানান- অগ্র্যাশয়, অত্যধিক, অদ্যাপি, আকাঙ্ক্ষা, ইতঃপূর্বে, ইতোমধ্যে, প্রোজ্জ্বল, প্রজ্বলিত।"},{"id":"bangla-188","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'যিনি বিদ্বান, তিনি সর্বত্র আদরণীয়।'- এটি কোন ধরনের বাক্য?","options":["সরল বাক্য","জটিল বাক্য","যৌগিক বাক্য","খণ্ড বাক্য"],"correctIndex":1,"subject":"বাংলা","explanation":"যে বাক্যে একটি প্রধান খণ্ডবাক্যের সাথে এক বা একাধিক আশ্রিত খণ্ডবাক্য পরস্পর সাপেক্ষভাবে যুক্ত থাকে, তাকে মিশ্র/জটিল বাক্য বলে। 'যিনি বিদ্বান, তিনি সর্বত্র আদরণীয়।' বাক্যে 'যিনি-তিনি' সাপেক্ষ সর্বনামযুক্ত থাকায় এটি জটিল বাক্য। এমন সাপেক্ষ সর্বনাম/অব্যয়ের উদাহরণ- যে-সে, যারা-তারা, যখন-তখন, যেমন-তেমন, যদি-তবে, যদিও-তথাপি, যত-তত। অপশন বিশ্লেষণ: সরল বাক্যে একটিমাত্র কর্তা ও একটিমাত্র সমাপিকা ক্রিয়া থাকে (যেমন- পুকুরে পদ্মফুল জন্মে); যৌগিক বাক্যে দুই বা ততোধিক সরল/মিশ্র বাক্য এবং, ও, কিন্তু, অথবা প্রভৃতি অব্যয় দ্বারা যুক্ত থাকে (যেমন- আমি আসলাম, দেখলাম, জয় করলাম)।"},{"id":"bangla-189","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'চিকিৎসাশাস্ত্র' কোন সমাস?","options":["কর্মধারয়","বহুব্রীহি","অব্যয়ীভাব","তৎপুরুষ"],"correctIndex":0,"subject":"বাংলা","explanation":"যে সমাসে পরপদের প্রাধান্য থাকে এবং ব্যাসবাক্য থেকে মধ্যপদ লোপ পায়, তাকে মধ্যপদলোপী কর্মধারয় সমাস বলে। শব্দের শেষে 'শাস্ত্র/বিদ্যা' থাকলে সাধারণত তা মধ্যপদলোপী কর্মধারয় সমাস হয়; 'চিকিৎসাশাস্ত্র' = চিকিৎসা বিষয়ক শাস্ত্র (এখানে 'বিষয়ক' মধ্যপদটি লোপ পেয়েছে)। অনুরূপ উদাহরণ- আইনশাস্ত্র (আইন বিষয়ক শাস্ত্র), প্রাণিবিদ্যা (প্রাণী বিষয়ক বিদ্যা), সিংহাসন (সিংহ চিহ্নিত আসন), জ্যোৎস্নারাত (জ্যোৎস্না শোভিত রাত), স্মৃতিসৌধ (স্মৃতি রক্ষার্থে সৌধ), আয়কর (আয়ের উপর কর)।"},{"id":"bangla-190","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"কোনটি নামধাতুর উদাহরণ?","options":["চল্","কর্","বেতা","পড়্"],"correctIndex":2,"subject":"বাংলা","explanation":"বিশেষ্য, বিশেষণ ও ধ্বন্যাত্মক অব্যয়ের পরে 'আ' প্রত্যয়যোগে যেসব ধাতু গঠিত হয়, তাদের নামধাতু বলে। যেমন- বেত (বিশেষ্য)+আ = বেতা (নামধাতু); বাঁক (বিশেষণ)+আ = বাঁকা (নামধাতু); ধ্বন্যাত্মক অব্যয়যোগে- কনকনাচ্ছে, ফোঁসাচ্ছে, ভনভনাচ্ছে। সহজ কৌশল: মূল শব্দটি ক্রিয়াবাচক না হলেই তা নামধাতু হয়; ক্রিয়াবাচক হলে তা প্রযোজক ধাতু বা কর্মবাচ্যের ধাতু হয়। অপশন বিশ্লেষণ: চল্, কর্, পড়্- এই তিনটিই মৌলিক ধাতু, নামধাতু নয়।"},{"id":"bangla-191","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'গড্ডলিকা প্রবাহ' বাগধারায় 'গড্ডল' শব্দের অর্থ কী?","options":["স্রোত","ভেড়া","একত্র","ভাসা"],"correctIndex":1,"subject":"বাংলা","explanation":"গড্ডল/গড্ডর শব্দের অর্থ ভেড়া, মেষ, গাড়ল। গড্ডলিকা শব্দের অর্থ- অগ্রবর্তী ভেড়াকে অনুসরণকারী ভেড়ার পাল। 'গড্ডলিকা প্রবাহ' বাগ্‌ধারাটির অর্থ- বিচার-বিবেচনা না করে অন্যের অন্ধ অনুকরণ বা প্রচলিত ধারার অনুগামিতা।"},{"id":"bangla-192","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"'তাতে সমাজজীবন চলে না।'-এ বাক্যটির অস্তিবাচক রূপ কোনটি?","options":["তাতে সমাজজীবন চলে","তাতে না সমাজজীবন চলে","তাতে সমাজজীবন অচল হয়ে পড়ে","তাতে সমাজজীবন সচল হয়ে পড়ে"],"correctIndex":2,"subject":"বাংলা","explanation":"নেতিবাচক বাক্যকে অস্তিবাচক বাক্যে রূপান্তরের নিয়ম: (১) মূল অর্থ পরিবর্তন হবে না, (২) না-বোধক শব্দ বাদ দিতে হবে, (৩) প্রয়োজনে বিপরীত শব্দ ব্যবহার করা যাবে। এই নিয়মে 'তাতে সমাজজীবন চলে না।'-এর অস্তিবাচক রূপ 'তাতে সমাজজীবন অচল হয়ে পড়ে।' অনুরূপ উদাহরণ- 'লোকটি ধনী নয়' → 'লোকটি গরিব'; 'মিথ্যাবাদীকে কেউ পছন্দ করে না' → 'মিথ্যাবাদীকে সবাই অপছন্দ করে'; 'দেশের প্রচলিত ধর্মকর্মে তাঁহার আস্থা ছিল না' → 'দেশের প্রচলিত ধর্মকর্মে তাঁহার অনাস্থা ছিল'।"},{"id":"bangla-193","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"বাগযন্ত্রের অংশ কোনটি?","options":["স্বরযন্ত্র","ফুসফুস","দাঁত","উপরের সবকটি"],"correctIndex":3,"subject":"বাংলা","explanation":"ধ্বনি উচ্চারণের জন্য ব্যবহৃত প্রত্যঙ্গসমূহকে একত্রে বাগযন্ত্র বলে; এর অন্তর্গত অংশ- গলনালী, মুখবিবর, কণ্ঠ, জিহ্বা/জিভ, তালু, দন্ত/দাঁত, নাসিকা/নাক, ওষ্ঠ/ঠোঁট, স্বরযন্ত্র, আলজিভ, ফুসফুস ইত্যাদি। তাই স্বরযন্ত্র, ফুসফুস ও দাঁত- এই তিনটিই বাগযন্ত্রের অংশ।"},{"id":"bangla-194","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"ভাষা","question":"রবীন্দ্রনাথ কোন কারক বাদ দিতে চেয়েছিলেন?","options":["করণ কারক","সম্প্রদান কারক","অপাদান কারক","অধিকরণ কারক"],"correctIndex":1,"subject":"বাংলা","explanation":"ক্রিয়াপদের সাথে নামপদের সম্পর্ককে কারক বলে; কারক ৬ প্রকার- কর্তৃকারক, কর্মকারক, করণ কারক, সম্প্রদান কারক, অপাদান কারক ও অধিকরণ কারক। এর মধ্যে সম্প্রদান কারক নিয়ে ভাষাবিদদের মধ্যে মতান্তর আছে। রবীন্দ্রনাথ ঠাকুর ও সুনীতিকুমার চট্টোপাধ্যায়সহ অনেক ভাষাবিদের মতে সম্প্রদান কারকের প্রয়োজন নেই, কারণ কর্মকারক দিয়েই এর কাজ সম্পাদন করা যায়; অন্যদিকে ড. মুহম্মদ শহীদুল্লাহসহ কয়েকজন ভাষাবিদ সম্প্রদান কারক রাখার পক্ষে। উল্লেখ্য, নবম-দশম শ্রেণির বাংলা ব্যাকরণ ও নির্মিতি (২০২১) বইতে সম্প্রদান কারক বাদ দিয়ে তার স্থলে 'সম্বন্ধ কারক' নামে নতুন একটি কারক অন্তর্ভুক্ত করা হয়েছে।"},{"id":"bangla-195","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"কেন্তুমের কোন দুটি শাখা এশিয়ার অন্তর্গত?","options":["হিত্তিক ও তুখারিক","তামিল ও দ্রাবিড়","আর্য ও অনার্য","মাগধী ও গৌড়ী"],"correctIndex":0,"subject":"বাংলা","explanation":"পৃথিবীর প্রাচীন ভাষাবংশগুলোর মধ্যে ইন্দো-ইউরোপীয় ভাষাবংশ অন্যতম, এর প্রধান দুটি শাখা কেন্তুম ও শতম। কেন্তুম শাখায় অধিকাংশ ইউরোপীয় ভাষা (গ্রিক, ইতালিক, কেল্টিক, জার্মানিক) থাকলেও এর তোখারীয়/তুখারিক (তুরফা প্রদেশ, চীন) ও হিত্তীয়/হিত্তিক (এশিয়া মাইনর) শাখা দুটি এশিয়ার অন্তর্গত। অন্যদিকে শতম শাখায় অধিকাংশ ইন্দো-ইরানীয় (এশীয়) ভাষা অবস্থিত, তবে এর বাল্‌তো স্লাভিক ও আলবানীয় শাখা দুটি ইউরোপের অন্তর্গত। বাংলা ভাষার জন্ম ইন্দো-ইউরোপীয় ভাষাগোষ্ঠীর শতম শাখা থেকে।"},{"id":"bangla-196","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'রুখের তেঁতুল কুমিরে খাই'-এর অর্থ কী?","options":["তেজি কুমিরকে রুখে দিই","বৃক্ষের শাখায় পাকা তেঁতুল","গাছের তেঁতুল কুমিরে খায়","ভুল থেকে শিক্ষা নিতে হয়"],"correctIndex":2,"subject":"বাংলা","explanation":"'রুখের তেঁতুলি কুমিরে খাই' চরণটি চর্যাপদের একমাত্র নারী পদকর্তা কুক্কুরীপার ২য় পদের অংশ, যার অর্থ- গাছের তেঁতুল কুমিরে খায়। এখানে 'রুখ' অর্থ গাছ ও 'তেঁতুলি' অর্থ তেঁতুল; এই শব্দগুলো সন্ধ্যাভাষার (দ্ব্যর্থবোধক প্রতীকী ভাষা) নিদর্শন। চর্যাপদের অন্যান্য উল্লেখযোগ্য পঙ্‌ক্তি- 'কাআ তরুবর পঞ্চ বি ডাল' (দেহ গাছের মতো, এর পাঁচটি ডাল), 'অপণা মাংসে হরিণা বৈরী' (হরিণের নিজ মাংসই তার শত্রু)।"},{"id":"bangla-197","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"মনসা দেবীকে নিয়ে লেখা বিজয়গুপ্তের মঙ্গলকাব্যের নাম কী?","options":["'মনসামঙল'","'মনসাবিজয়'","'পদ্মাপুরাণ'","'পদ্মাবতী'"],"correctIndex":2,"subject":"বাংলা","explanation":"বাংলা সাহিত্যে মঙ্গলকাব্য ধারার প্রাচীনতম শাখা মনসামঙল; দেবী মনসার পূজা প্রচার ও চাঁদ সওদাগরের বিদ্রোহ এর মূল উপজীব্য। মনসা দেবীর অপর নাম কেতকা ও পদ্মাবতী হওয়ায় মনসামঙল কাব্যকে 'পদ্মাপুরাণ'ও বলা হয়। মনসামঙলের আদি কবি কানাহরিদত্ত এবং প্রধান/শ্রেষ্ঠ কবি বিজয়গুপ্ত; মনসা দেবীকে নিয়ে লেখা বিজয়গুপ্তের কাব্যের নাম তাই 'পদ্মাপুরাণ'।"},{"id":"bangla-198","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"দৌলত উজির বাহরাম খান সাহিত্য কীসের পৃষ্ঠপোষকতা লাভ করেন?","options":["সুলতান গিয়াসউদ্দিন আজম শাহ","কোরেশী মাগন ঠাকুর","সুলতান বরবক শাহ","জমিদার নিজাম শাহ"],"correctIndex":3,"subject":"বাংলা","explanation":"বাংলা রোমান্টিক প্রণয়োপাখ্যান কাব্যধারার পরিচিত কবি দৌলত উজির বাহরাম খানের রচিত কাব্য 'লাইলী মজনু' ও 'ইমাম বিজয়'। তিনি চট্টগ্রামের ফতেহবাদ/জাফরাবাদের অধিবাসী ছিলেন; তাঁর পূর্বপুরুষ হামিদ খান ছিলেন গৌড়ের সুলতান হুসেন শাহের প্রধান অমাত্য। গৌড়ের অধীনতা বিলুপ্ত হলে চট্টগ্রামের নৃপতি হন সামন্ত জমিদার নিজাম শাহ, এবং তাঁরই পৃষ্ঠপোষকতায় বাহরাম খান সাহিত্যসৃষ্টি করেন; নিজাম শাহই তাঁকে 'দৌলত উজির' উপাধি দেন।"},{"id":"bangla-199","exam":"৪৩তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"সাহিত্য","question":"'চর্যাপদের প্রাপ্তিস্থান কোথায়?","options":["বাংলাদেশ","নেপাল","উড়িয়া","ভুটান"],"correctIndex":1,"subject":"বাংলা","explanation":"মহামহোপাধ্যায় হরপ্রসাদ শাস্ত্রী নেপালের 'রাজগ্রন্থশালা' (রয়েল লাইব্রেরি) থেকে ১৯০৭ সালে (তৃতীয়বারের চেষ্টায়) চর্যাপদ আবিষ্কার করেন। এর আগে নেপালের রাজা রাজেন্দ্রলাল মিত্র সর্বপ্রথম নেপালের বৌদ্ধতান্ত্রিক সাহিত্যের কথা প্রকাশ করেন তাঁর 'Sanskrit Buddhist Literature in Nepal' গ্রন্থে, এবং তাঁরই আমন্ত্রণে হরপ্রসাদ শাস্ত্রী নেপাল ভ্রমণ করেন।"}];
